# ── DPI awareness — must run before any Tk window is created ──────────────────
# Without this, Windows bitmap-upscales the whole window at high-DPI settings,
# causing the blurry / pixelated appearance users see on 125 %+ displays.
import ctypes as _ctypes
try:
    _ctypes.windll.shcore.SetProcessDpiAwareness(2)   # PROCESS_PER_MONITOR_DPI_AWARE
except AttributeError:
    try:
        _ctypes.windll.user32.SetProcessDPIAware()
    except AttributeError:
        pass
except OSError:
    pass

CONFIG_FILE = Path("budget_config.json")   # optional pointer: {"data_path": "..."} (Settings → Move data file)


def _load_data_location() -> Path:
    try:
        cfg = json.loads(CONFIG_FILE.read_text(encoding="utf-8"))
        p = Path(str(cfg.get("data_path", "")))
        if cfg.get("data_path") and p.parent.is_dir():
            return p
    except Exception:
        pass
    return Path("budget_data.json")


DATA_FILE = _load_data_location()

