LEVEL_STEPS = (100, 150, 200)


def level_threshold(level: int) -> int:
    """Total Gold needed to *reach* `level` (level 1 = 0)."""
    n = max(0, int(level) - 1)
    return sum(LEVEL_STEPS[:min(n, len(LEVEL_STEPS))]) + max(0, n - len(LEVEL_STEPS)) * 250


