def season_for_month(month: int) -> str:
    """Australian seasons."""
    return {12: "summer", 1: "summer", 2: "summer", 3: "autumn", 4: "autumn", 5: "autumn",
            6: "winter", 7: "winter", 8: "winter"}.get(month, "spring")


