def previous_calendar_month_window(today: date) -> tuple[date, date]:
    """First and last day of the calendar month before ``today``."""
    first_this = today.replace(day=1)
    last_prev = first_this - timedelta(days=1)
    first_prev = last_prev.replace(day=1)
    return first_prev, last_prev


def outgoing_category_totals(
    transactions: List[TransactionRecord], start: date, end: date
) -> Dict[str, float]:
    """Sum money_out by category between ``start`` and ``end`` (inclusive)."""
    out: Dict[str, float] = {}
    for tx in transactions:
        if tx.direction() != "out" or tx.matched_type == "ignore":
            continue
        if tx.tx_date < start or tx.tx_date > end:
            continue
        cat = (tx.category or "").strip() or "Uncategorized"
        out[cat] = out.get(cat, 0.0) + tx.money_out
    return out


def percents_from_amounts(amounts: Dict[str, float]) -> Dict[str, float]:
    total = sum(amounts.values())
    if total <= 0:
        return {k: 0.0 for k in amounts}
    return {k: round(100.0 * v / total, 2) for k, v in amounts.items()}


def normalize_desc_text(desc: str) -> str:
    return re.sub(r"\s+", " ", (desc or "")).strip()


def normalize_merchant_key(desc: str) -> str:
    return normalize_desc_text(desc).lower()


def clamp(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))


def month_bounds(any_day: date) -> tuple[date, date]:
    first_day = any_day.replace(day=1)
    last_day = any_day.replace(day=calendar.monthrange(any_day.year, any_day.month)[1])
    return first_day, last_day


def extract_merchant_name(desc: str) -> str:
    text = normalize_desc_text(desc).upper()
    text = re.sub(r"\b(POS|VISA|DEBIT|CREDIT|PURCHASE|PAYMENT|TRANSFER|DIRECT DEBIT|CARD|ONLINE)\b", " ", text)
    text = re.sub(r"\d+", " ", text)
    text = re.sub(r"[^A-Z& ]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    if not text:
        return "Unknown Merchant"
    parts = [p for p in text.split() if len(p) >= 2]
    if not parts:
        return "Unknown Merchant"
    return " ".join(parts[:3]).title()


def merchant_group_key(desc: str) -> str:
    merchant = extract_merchant_name(desc).lower()
    merchant = re.sub(r"\b(australia|pty|ltd|store|stores|market|markets|service|services|payment|payments)\b", " ", merchant)
    merchant = re.sub(r"\s+", " ", merchant).strip()
    return merchant or normalize_merchant_key(desc)


# -----------------------------
# Models
# -----------------------------

@dataclass
class IncomeEntry:
    amount: float
    received_on: date
    source: str = "Primary Income"

    def to_dict(self):
        d = asdict(self)
        d["received_on"] = self.received_on.isoformat()
        return d

    @classmethod
    def from_dict(cls, data):
        return cls(float(data["amount"]), datetime.strptime(data["received_on"], "%Y-%m-%d").date(), data.get("source", "Primary Income"))


@dataclass
class Bill:
    name: str
    amount: float
    due_date: date
    frequency: str = "one-off"
    priority: str = "essential"
    category: str = "Bill"
    current_saved: float = 0.0

    def to_dict(self):
        d = asdict(self)
        d["due_date"] = self.due_date.isoformat()
        return d

    @classmethod
    def from_dict(cls, data):
        return cls(
            data["name"],
            float(data["amount"]),
            datetime.strptime(data["due_date"], "%Y-%m-%d").date(),
            data.get("frequency", "one-off"),
            data.get("priority", "essential"),
            data.get("category", "Bill"),
            float(data.get("current_saved", 0.0)),
        )


@dataclass
class Fund:
    name: str
    target_amount: float
    target_date: Optional[date] = None
    priority: str = "important"
    current_saved: float = 0.0
    contribution_mode: str = "auto"
    fixed_amount: float = 0.0
    category: str = "Fund"
    # Savings challenge bookkeeping (empty for ordinary funds)
    challenge: str = ""
    challenge_started: Optional[str] = None
    challenge_claimed: List[int] = field(default_factory=list)
    challenge_ticks: int = 0

    def to_dict(self):
        d = asdict(self)
        d["target_date"] = self.target_date.isoformat() if self.target_date else None
        return d

    @classmethod
    def from_dict(cls, data):
        td = data.get("target_date")
        return cls(
            data["name"],
            float(data["target_amount"]),
            datetime.strptime(td, "%Y-%m-%d").date() if td else None,
            data.get("priority", "important"),
            float(data.get("current_saved", 0.0)),
            data.get("contribution_mode", "auto"),
            float(data.get("fixed_amount", 0.0)),
            data.get("category", "Fund"),
            str(data.get("challenge", "") or ""),
            data.get("challenge_started") or None,
            list(data.get("challenge_claimed", [])),
            int(data.get("challenge_ticks", 0)),
        )


@dataclass
class Goal:
    name: str
    target_amount: float
    target_date: Optional[date] = None
    priority: int = 3
    current_saved: float = 0.0
    mode: str = "fixed"
    value: float = 0.0

    def to_dict(self):
        d = asdict(self)
        d["target_date"] = self.target_date.isoformat() if self.target_date else None
        return d

    @classmethod
    def from_dict(cls, data):
        td = data.get("target_date")
        return cls(
            data["name"],
            float(data["target_amount"]),
            datetime.strptime(td, "%Y-%m-%d").date() if td else None,
            int(data.get("priority", 3)),
            float(data.get("current_saved", 0.0)),
            data.get("mode", "fixed"),
            float(data.get("value", 0.0)),
        )


@dataclass
class GameStats:
    # Core
    total_score: int = 0
    level: int = 1
    streak_pays: int = 0
    best_streak: int = 0
    total_pays_processed: int = 0
    last_score_gain: int = 0
    achievements: List[str] = field(default_factory=list)
    mini_game_high_score: int = 0
    mini_game_rounds_won: int = 0
    # Progression systems
    gems: int = 0
    prestige_level: int = 0
    score_multiplier: float = 1.0
    streak_shields: int = 0
    active_buffs: List[str] = field(default_factory=list)
    season_year_month: str = ""
    season_xp: int = 0
    season_claimed_tiers: List[int] = field(default_factory=list)
    daily_challenges: List[dict] = field(default_factory=list)
    daily_challenges_date: str = ""
    perks_unlocked: List[str] = field(default_factory=list)
    lifetime_gems_earned: int = 0
    # Collection system
    cards_owned: List[str] = field(default_factory=list)   # list of card_ids (duplicates allowed)
    packs_opened: int = 0
    # Character system
    character_items_owned: List[str] = field(default_factory=lambda: ["hair_short_dark", "eyes_focused_brown", "outfit_starter_hoodie", "background_midnight"])
    character_equipped: Dict[str, str] = field(default_factory=lambda: {
        "hair": "hair_short_dark",
        "eyes": "eyes_focused_brown",
        "outfit": "outfit_starter_hoodie",
        "accessory": "",
        "aura": "",
        "background": "background_midnight",
    })
    character_favorites: List[str] = field(default_factory=list)
    # Streak chain (True = good pay, False = broken)
    streak_history: List[bool] = field(default_factory=list)
    # Last money-personality snapshot (for trend arrows). {"attrs": {...}, "archetype_id": "...", "captured_on": "YYYY-MM-DD"}
    personality_snapshot: dict = field(default_factory=dict)
    # Integrity
    last_pay_scored_date: str = ""   # YYYY-MM-DD — prevents same-day multi-scoring
    # Arcade daily earn caps — prevents grinding mini-games for infinite rewards
    arcade_daily_date: str = ""      # YYYY-MM-DD — rolls over at calendar day
    arcade_gold_today: int = 0
    arcade_gems_today: int = 0
    # Homestead (living scene) — tier is derived, claimed tiers award companions
    homestead_tier: int = 0
    homestead_claimed_tiers: List[int] = field(default_factory=list)
    # Daily Vault + engagement hooks
    vault_last_opened: str = ""        # YYYY-MM-DD
    vault_visit_streak: int = 0        # consecutive days the vault was opened
