@dataclass
class AdvancedMatchRule:
    rule_name: str
    rule_type: str = "contains"   # exact, contains, amount_contains
    keyword: str = ""
    amount: float = 0.0
    matched_type: str = "discretionary"
    matched_target: str = ""
    category: str = ""
    is_active: bool = True

    def to_dict(self):
        return asdict(self)

    @classmethod
    def from_dict(cls, data):
        return cls(
            data.get("rule_name", ""),
            data.get("rule_type", "contains"),
            data.get("keyword", ""),
            float(data.get("amount", 0.0)),
            data.get("matched_type", "discretionary"),
            data.get("matched_target", ""),
            data.get("category", ""),
            bool(data.get("is_active", True)),
        )


@dataclass
class TransactionRecord:
    tx_date: date
    description: str
    money_in: float = 0.0
    money_out: float = 0.0
    balance: Optional[float] = None
    source_file: str = ""
    fingerprint: str = ""
    matched_type: str = "unmatched"
    matched_target: str = ""
    category: str = ""
    confidence: str = "low"
    needs_review: bool = True
    user_verified: bool = False
    notes: str = ""
    flagged: bool = False   # user flagged for follow-up (e.g. forgotten subscription)

    def amount(self) -> float:
        return self.money_in if self.money_in > 0 else self.money_out

    def direction(self) -> str:
        return "in" if self.money_in > 0 else "out"

    def to_dict(self):
        d = asdict(self)
        d["tx_date"] = self.tx_date.isoformat()
        return d

    @classmethod
    def from_dict(cls, data):
        return cls(
            datetime.strptime(data["tx_date"], "%Y-%m-%d").date(),
            data["description"],
            float(data.get("money_in", 0.0)),
            float(data.get("money_out", 0.0)),
            float(data["balance"]) if data.get("balance") not in (None, "") else None,
            data.get("source_file", ""),
            data.get("fingerprint", ""),
            data.get("matched_type", "unmatched"),
            data.get("matched_target", ""),
            data.get("category", ""),
            data.get("confidence", "low"),
            bool(data.get("needs_review", True)),
            bool(data.get("user_verified", False)),
            data.get("notes", ""),
            bool(data.get("flagged", False)),
        )


@dataclass
class MerchantMemoryEntry:
    """Remember verified classification per normalized description + direction (for repeat imports)."""
    category: str
    matched_type: str = "discretionary"
    matched_target: str = ""
    direction: str = "out"

    def to_dict(self):
        return asdict(self)

    @classmethod
    def from_dict(cls, data):
        return cls(
            data.get("category", ""),
            data.get("matched_type", "discretionary"),
            data.get("matched_target", ""),
            data.get("direction", "out"),
        )


@dataclass
class AppState:
    pay_frequency: str = "fortnightly"
    emergency_fund_target: float = 5000.0
    incomes: List[IncomeEntry] = field(default_factory=list)
    bills: List[Bill] = field(default_factory=list)
    funds: List[Fund] = field(default_factory=list)
    goals: List[Goal] = field(default_factory=list)
    game: GameStats = field(default_factory=GameStats)
    transactions: List[TransactionRecord] = field(default_factory=list)
    advanced_match_rules: List[AdvancedMatchRule] = field(default_factory=list)
    expense_categories: List[str] = field(default_factory=lambda: list(DEFAULT_EXPENSE_CATEGORIES))
    merchant_memory: Dict[str, MerchantMemoryEntry] = field(default_factory=dict)
    expense_target_order: List[str] = field(
        default_factory=lambda: ["Food", "Fuel", "Groceries", "Subscription", "General", "Other"]
    )
    expense_target_pct: List[float] = field(
        default_factory=lambda: [18.0, 15.0, 22.0, 12.0, 23.0, 10.0]
    )
    last_target_submit: Optional[date] = None
    target_is_locked: bool = False
    target_unlock_events_this_month: int = 0
    last_month_scored: Optional[str] = None  # "YYYY-MM"
    last_seen_tx_month: Optional[str] = None  # "YYYY-MM"
    last_safe_to_spend: float = 0.0
    last_reserved_total: float = 0.0
    last_fund_total: float = 0.0
    last_goal_total: float = 0.0
    last_invest_total: float = 0.0
    onboarding_complete: bool = False
    tutorial_complete: bool = False
    income_baseline: float = 0.0   # EMA of recent pays — used for integrity flagging
    transfer_accounts: Dict = field(default_factory=lambda: {
        "spending": {"name": "Everyday Account", "hint": "Where your pay lands and daily spending comes from"},
        "bills": {"name": "Bills Account", "hint": "Direct debits, rent, subscriptions — auto-debited from here"},
        "savings": {"name": "Savings Account", "hint": "Sinking funds + goals — money you're building up"},
        "invest": {"name": "Investment Account", "hint": "Brokerage or high-interest account for investing"},
    })
    # Fingerprints of committed income-classified transactions awaiting user
    # confirmation to log as pay + trigger allocation. A card on the Today tab
    # surfaces each pending entry with "Log as pay" / "Dismiss" actions.
    pending_income_confirmations: List[str] = field(default_factory=list)
    # Gerald custom aliases: {"subs": "Netflix + Spotify"} — user-defined shortcuts expanded before parsing.
    gerald_aliases: Dict[str, str] = field(default_factory=dict)
    # Gerald reminders: [{"id": int, "text": str, "due_date": "YYYY-MM-DD", "created": "YYYY-MM-DD", "dismissed": bool}]
    gerald_reminders: List[Dict] = field(default_factory=list)
    # Starting position: snapshot balances per transfer account key
    # ("spending", "bills", "savings", "invest") entered in the setup wizard.
    account_balances: Dict[str, float] = field(default_factory=dict)
    starting_position_set: bool = False
    # "YYYY-MM" of the last month whose end-of-month report was viewed/dismissed
    last_month_report_seen: str = ""
    # Investing rules (mode / value / minimum buffer) — persisted so they
    # survive a restart (they used to live only in memory).
    investment_rules: Dict = field(default_factory=dict)
    # Bank statement pages for one-click access: [{name, url, every_days, last_opened}]
    bank_links: List[Dict] = field(default_factory=list)
    last_import_date: str = ""   # YYYY-MM-DD of the last statement import (drives 'statement time')
    # History cutoff: imported rows dated before max(starting_position_date, last logged pay)
    # are history — kept for Analysis, never allocated. No position and no pays = no cutoff.
    starting_position_date: str = ""
    first_launch_date: str = ""
    # Collapsible-section open/closed state, keyed "<tab>.<section>".
    # True = open. Missing key => the section's call-site default.
    # NOTE: must stay the LAST field — from_dict passes args positionally.
    ui_prefs: Dict[str, bool] = field(default_factory=dict)

    def to_dict(self):
        return {
            "pay_frequency": self.pay_frequency,
            "emergency_fund_target": self.emergency_fund_target,
            "incomes": [x.to_dict() for x in self.incomes],
            "bills": [x.to_dict() for x in self.bills],
            "funds": [x.to_dict() for x in self.funds],
            "goals": [x.to_dict() for x in self.goals],
            "game": self.game.to_dict(),
            "transactions": [x.to_dict() for x in self.transactions],
            "advanced_match_rules": [x.to_dict() for x in self.advanced_match_rules],
            "expense_categories": list(self.expense_categories),
            "merchant_memory": {k: v.to_dict() for k, v in self.merchant_memory.items()},
            "expense_target_order": list(self.expense_target_order),
            "expense_target_pct": list(self.expense_target_pct),
            "last_target_submit": self.last_target_submit.isoformat() if self.last_target_submit else None,
            "target_is_locked": bool(self.target_is_locked),
            "target_unlock_events_this_month": int(self.target_unlock_events_this_month),
            "last_month_scored": self.last_month_scored,
            "last_seen_tx_month": self.last_seen_tx_month,
            "last_safe_to_spend": self.last_safe_to_spend,
            "last_reserved_total": self.last_reserved_total,
            "last_fund_total": self.last_fund_total,
            "last_goal_total": self.last_goal_total,
            "last_invest_total": self.last_invest_total,
            "onboarding_complete": self.onboarding_complete,
            "tutorial_complete": self.tutorial_complete,
            "income_baseline": self.income_baseline,
            "transfer_accounts": self.transfer_accounts,
            "pending_income_confirmations": list(self.pending_income_confirmations),
            "gerald_aliases": dict(self.gerald_aliases),
            "gerald_reminders": list(self.gerald_reminders),
            "account_balances": {k: float(v) for k, v in self.account_balances.items()},
            "starting_position_set": self.starting_position_set,
            "last_month_report_seen": self.last_month_report_seen,
            "investment_rules": dict(self.investment_rules),
            "bank_links": [dict(l) for l in self.bank_links],
            "last_import_date": self.last_import_date,
            "starting_position_date": self.starting_position_date,
            "first_launch_date": self.first_launch_date,
            "ui_prefs": dict(self.ui_prefs),
        }

    @classmethod
    def from_dict(cls, data):
        raw_cats = data.get("expense_categories")
        if not raw_cats:
            merged_cats = list(DEFAULT_EXPENSE_CATEGORIES)
        else:
            merged_cats = list(raw_cats)
            for d in DEFAULT_EXPENSE_CATEGORIES:
                if not any(x.lower() == d.lower() for x in merged_cats):
                    merged_cats.append(d)
        merged_cats.sort(key=str.lower)
        mem_raw = data.get("merchant_memory") or {}
        merchant_memory = {k: MerchantMemoryEntry.from_dict(v) for k, v in mem_raw.items()}
        et_order = data.get("expense_target_order")
        if not et_order:
            et_order = ["Food", "Fuel", "Groceries", "Subscription", "General", "Other"]
        et_pct = data.get("expense_target_pct")
        if not et_pct or len(et_pct) != len(et_order):
            et_pct = [100.0 / len(et_order)] * len(et_order)
        pct_sum = sum(float(x) for x in et_pct)
        if pct_sum > 0:
            et_pct = [round(100.0 * float(x) / pct_sum, 2) for x in et_pct]
        else:
            et_pct = [100.0 / len(et_order)] * len(et_order)
        lt_raw = data.get("last_target_submit")
        last_target_submit = datetime.strptime(lt_raw, "%Y-%m-%d").date() if lt_raw else None
        target_is_locked = bool(data.get("target_is_locked", False))
        target_unlock_events_this_month = int(data.get("target_unlock_events_this_month", 0))
        last_month_scored = data.get("last_month_scored")
        last_seen_tx_month = data.get("last_seen_tx_month")
        return cls(
            data.get("pay_frequency", "fortnightly"),
            float(data.get("emergency_fund_target", 5000.0)),
            [IncomeEntry.from_dict(x) for x in data.get("incomes", [])],
            [Bill.from_dict(x) for x in data.get("bills", [])],
            [Fund.from_dict(x) for x in data.get("funds", [])],
            [Goal.from_dict(x) for x in data.get("goals", [])],
            GameStats.from_dict(data.get("game", {})),
            [TransactionRecord.from_dict(x) for x in data.get("transactions", [])],
            [AdvancedMatchRule.from_dict(x) for x in data.get("advanced_match_rules", [])],
            merged_cats,
            merchant_memory,
            list(et_order),
            et_pct,
            last_target_submit,
            target_is_locked,
            target_unlock_events_this_month,
            last_month_scored,
            last_seen_tx_month,
            float(data.get("last_safe_to_spend", 0.0)),
            float(data.get("last_reserved_total", 0.0)),
            float(data.get("last_fund_total", 0.0)),
            float(data.get("last_goal_total", 0.0)),
            float(data.get("last_invest_total", 0.0)),
            bool(data.get("onboarding_complete", False)),
            bool(data.get("tutorial_complete", False)),
            float(data.get("income_baseline", 0.0)),
            data.get("transfer_accounts", {
                "spending": {"name": "Everyday Account", "hint": "Where your pay lands and daily spending comes from"},
                "bills": {"name": "Bills Account", "hint": "Direct debits, rent, subscriptions — auto-debited from here"},
                "savings": {"name": "Savings Account", "hint": "Sinking funds + goals — money you're building up"},
                "invest": {"name": "Investment Account", "hint": "Brokerage or high-interest account for investing"},
            }),
            list(data.get("pending_income_confirmations", [])),
            dict(data.get("gerald_aliases", {})),
            list(data.get("gerald_reminders", [])),
            {k: float(v) for k, v in (data.get("account_balances") or {}).items()},
            bool(data.get("starting_position_set", False)),
            str(data.get("last_month_report_seen", "") or ""),
            dict(data.get("investment_rules", {}) or {}),
            [dict(l) for l in (data.get("bank_links") or [])],
            str(data.get("last_import_date", "") or ""),
            str(data.get("starting_position_date", "") or ""),
            str(data.get("first_launch_date", "") or ""),
            dict(data.get("ui_prefs", {}) or {}),
        )


# -----------------------------
# Engines
# -----------------------------

class BudgetEngine:
    PAY_CYCLE_DAYS = {"weekly": 7, "fortnightly": 14, "monthly": 30}

    def __init__(self, state: AppState):
        self.state = state

    def current_cycle_days(self) -> int:
        return self.PAY_CYCLE_DAYS.get(self.state.pay_frequency, 14)

    def days_until(self, due_date: Optional[date]) -> int:
        if due_date is None:
            return 999999
        return (due_date - date.today()).days

    def pays_until(self, due_date: Optional[date]) -> int:
        if due_date is None:
            return 1
        days = max(self.days_until(due_date), 0)
        return max(1, math.ceil(days / self.current_cycle_days()) if days > 0 else 1)

    def bill_recommended_allocation(self, bill: Bill) -> float:
        return round(max(bill.amount - bill.current_saved, 0.0) / self.pays_until(bill.due_date), 2)

    def fund_recommended_allocation(self, fund: Fund) -> float:
        """Per-pay contribution for a sinking fund.

        contribution_mode:
          auto    — save target_amount by target_date (spread over remaining pays)
          fixed   — fixed_amount each pay; target_amount optional (0 = no end)
          ongoing — fixed_amount each pay, forever (no target, no date)
          buffer  — keep current_saved topped up to target_amount; fixed_amount
                    (if > 0) caps how much one pay puts in
        """
        mode = fund.contribution_mode
        if mode == "ongoing":
            return round(max(fund.fixed_amount, 0.0), 2)
        unlimited = fund.target_amount <= 0
        remaining = float("inf") if unlimited else max(fund.target_amount - fund.current_saved, 0.0)
        if mode == "fixed":
            return round(min(max(fund.fixed_amount, 0.0), remaining), 2)
        if mode == "buffer":
            gap = 0.0 if unlimited else remaining
            cap = fund.fixed_amount if fund.fixed_amount > 0 else gap
            return round(min(gap, cap), 2)
        if unlimited:
            return round(max(fund.fixed_amount, 0.0), 2)
        return round(remaining / self.pays_until(fund.target_date), 2)

    @staticmethod
    def has_end_target(item) -> bool:
        """False for open-ended funds/goals (no target amount to complete)."""
        if isinstance(item, Fund) and item.contribution_mode == "ongoing":
            return False
        return float(getattr(item, "target_amount", 0.0) or 0.0) > 0

    def goal_remaining(self, goal: Goal) -> float:
        if goal.target_amount <= 0:
            return float("inf")   # open-ended goal — never "full"
        return max(goal.target_amount - goal.current_saved, 0.0)

    def next_due_date(self, due_date: date, frequency: str) -> date:
        if frequency == "monthly":
            import calendar
            month = due_date.month % 12 + 1
            year = due_date.year + (1 if due_date.month == 12 else 0)
            day = min(due_date.day, calendar.monthrange(year, month)[1])
            return due_date.replace(year=year, month=month, day=day)
        if frequency == "quarterly":
            import calendar
            month0 = due_date.month - 1 + 3
            year = due_date.year + month0 // 12
            month = month0 % 12 + 1
            day = min(due_date.day, calendar.monthrange(year, month)[1])
            return due_date.replace(year=year, month=month, day=day)
        return {
            "weekly": due_date + timedelta(days=7),
            "fortnightly": due_date + timedelta(days=14),
            "yearly": due_date.replace(year=due_date.year + 1),
        }.get(frequency, due_date)

    def mark_bill_paid(self, bill: Bill):
        """Reset what's set aside and move a recurring bill to its next occurrence —
        always at least one cycle on (paying early counts), then past today."""
        bill.current_saved = 0.0
        if bill.frequency != "one-off":
            bill.due_date = self.next_due_date(bill.due_date, bill.frequency)
            while bill.due_date <= date.today():
                nxt = self.next_due_date(bill.due_date, bill.frequency)
                if nxt <= bill.due_date:
                    break
                bill.due_date = nxt

    def allocate_pay(self, pay_amount: float, *, apply: bool = False, investment_mode: str = "fixed", investment_value: float = 0.0, minimum_buffer: float = 0.0, overrides: Optional[dict] = None) -> dict:
        """Split a pay across bills → funds → goals → investing.

        overrides: optional user edits from the allocation editor, keyed
        "bill:<idx>", "fund:<idx>", "goal:<idx>" or "invest". An override
        replaces the calculated recommendation for that line (still capped at
        what's left of the pay) and suppresses the underfunded warning for it."""
        overrides = overrides or {}
        remaining = round(pay_amount, 2)
        rb = rf = rg = ri = 0.0
        bill_breakdown: list = []
        fund_breakdown: list = []
        goal_breakdown: list = []
        warnings: list[str] = []
        priority_order = {"essential": 0, "important": 1, "optional": 2}

        def _want(key: str, calculated: float) -> float:
            if key in overrides:
                try:
                    return max(float(overrides[key]), 0.0)
                except (TypeError, ValueError):
                    return calculated
            return calculated

        for idx, bill in sorted(enumerate(self.state.bills), key=lambda x: (priority_order.get(x[1].priority, 9), x[1].due_date)):
            rec = self.bill_recommended_allocation(bill)
            key = f"bill:{idx}"
            actual = round(min(_want(key, rec), max(remaining, 0.0)), 2)
            rb += actual
            remaining -= actual
            bill_breakdown.append((idx, bill.name, actual, rec))
            if key not in overrides and actual + 0.009 < rec:
                warnings.append(f"Bill underfunded this pay: {bill.name} needs ${rec:.2f}, allocated ${actual:.2f}.")

        for idx, fund in sorted(enumerate(self.state.funds), key=lambda x: (priority_order.get(x[1].priority, 9), self.days_until(x[1].target_date))):
            rec = self.fund_recommended_allocation(fund)
            key = f"fund:{idx}"
            actual = round(min(_want(key, rec), max(remaining, 0.0)), 2)
            rf += actual
            remaining -= actual
            fund_breakdown.append((idx, fund.name, actual, rec))
            if key not in overrides and actual + 0.009 < rec:
                warnings.append(f"Fund behind recommended contribution: {fund.name} needs ${rec:.2f}, allocated ${actual:.2f}.")

        for idx, goal in sorted(enumerate(self.state.goals), key=lambda x: x[1].priority):
            target = goal.value if goal.mode == "fixed" else max(remaining, 0.0) * (goal.value / 100.0)
            key = f"goal:{idx}"
            want = _want(key, target)
            actual = round(min(want, self.goal_remaining(goal), max(remaining, 0.0)), 2)
            rg += actual
            remaining -= actual
            goal_breakdown.append((idx, goal.name, actual, target))
            if key not in overrides and target > 0 and actual + 0.009 < target:
                warnings.append(f"Goal contribution reduced this pay: {goal.name} target was ${target:.2f}, allocated ${actual:.2f}.")

        invest_base = max(remaining - minimum_buffer, 0.0)
        if "invest" in overrides:
            ri = round(min(_want("invest", 0.0), invest_base), 2)
        elif investment_mode == "percent":
            ri = round(min(invest_base * (investment_value / 100.0), invest_base), 2)
        else:
            ri = round(min(investment_value, invest_base), 2)
        remaining -= ri

        if apply:
            for idx, _, actual, _ in bill_breakdown:
                self.state.bills[idx].current_saved = round(min(self.state.bills[idx].amount, self.state.bills[idx].current_saved + actual), 2)
            for idx, _, actual, _ in fund_breakdown:
                f = self.state.funds[idx]
                cap = f.target_amount if (f.target_amount > 0 and f.contribution_mode != "ongoing") else float("inf")
                f.current_saved = round(min(cap, f.current_saved + actual), 2)
            for idx, _, actual, _ in goal_breakdown:
                g = self.state.goals[idx]
                cap = g.target_amount if g.target_amount > 0 else float("inf")
                g.current_saved = round(min(cap, g.current_saved + actual), 2)

        self.state.last_reserved_total = round(rb, 2)
        self.state.last_fund_total = round(rf, 2)
        self.state.last_goal_total = round(rg, 2)
        self.state.last_invest_total = round(ri, 2)
        self.state.last_safe_to_spend = round(max(remaining, 0.0), 2)

        return {
            "pay_amount": round(pay_amount, 2),
            "bill_total": round(rb, 2),
            "fund_total": round(rf, 2),
            "goal_total": round(rg, 2),
            "invest_total": round(ri, 2),
            "safe_to_spend": self.state.last_safe_to_spend,
            "warnings": warnings,
            "bill_breakdown": bill_breakdown,
            "fund_breakdown": fund_breakdown,
            "goal_breakdown": goal_breakdown,
        }


class BudgetGameEngine:
    def __init__(self, state: AppState):
        self.state = state

    def level_from_score(self, score: int) -> int:
        lvl = 1
        while score >= level_threshold(lvl + 1):
            lvl += 1
        return lvl

    def _expense_mix_match_bonus(self) -> tuple[int, list[str]]:
        """Bonus for how close last calendar month's spending mix was to a *submitted* target mix.

        The mix bonus only applies if the user has submitted the target mix. After the first day
        without a submission, the maximum potential bonus decays gradually until it reaches zero.
        """
        labels = self.state.expense_target_order
        targets = self.state.expense_target_pct
        if not labels or len(labels) != len(targets):
            return 0, ["Expense mix vs target: +0 (no usable target mix yet)."]

        if not self.state.last_target_submit:
            return 0, ["Expense mix vs target: +0 (submit a target mix on the Score tab to start scoring)."]

        today = date.today()
        days_since = max((today - self.state.last_target_submit).days, 0)

        start, end = previous_calendar_month_window(today)
        amounts = outgoing_category_totals(self.state.transactions, start, end)
        total_amt = sum(amounts.values())
        if total_amt <= 0:
            return 0, [f"Expense mix vs target: +0 (need committed outgoing data for {start.isoformat()}–{end.isoformat()})."]

        lo = [x.lower() for x in labels]
        bucket: Dict[str, float] = {lo[i]: 0.0 for i in range(len(lo))}
        other_key = "other" if "other" in bucket else None
        for cat, amt in amounts.items():
            cl = cat.lower()
            if cl in bucket:
                bucket[cl] += amt
            elif other_key is not None:
                bucket[other_key] += amt
            else:
                bucket[lo[-1]] += amt

        actual_vec = [100.0 * bucket[lo[i]] / total_amt for i in range(len(lo))]
        d = sum(abs(actual_vec[i] - targets[i]) for i in range(len(lo)))

        base_bonus = max(0, min(35, round(35 * (1.0 - d / 200.0))))
        if days_since <= 1:
            decay_factor = 1.0
        else:
            # After the first day without a submission, decay over the next 14 days to zero.
            decay_days = 14.0
            decay_factor = max(0.0, 1.0 - (days_since - 1) / decay_days)
        final_bonus = int(round(base_bonus * decay_factor))

        lines = [
            f"Expense mix vs target (last month {start.isoformat()}–{end.isoformat()}): +{final_bonus}",
            f"- Mix distance: {d:.1f} (lower is closer to your target pie)",
            f"- Target last submitted: {self.state.last_target_submit.isoformat()} (days since submit: {days_since})",
        ]
        if final_bonus < base_bonus:
            lines.append(f"- Daily decay cap reduced bonus from {base_bonus} to {final_bonus} (submit a fresh target to reset).")
        return final_bonus, lines

    def score_month_end_mix(self, year: int, month: int) -> tuple[int, list[str]]:
        """Score the *full month* mix bonus once, for (year, month) using committed transactions."""
        start = date(year, month, 1)
        if month == 12:
            end = date(year + 1, 1, 1) - timedelta(days=1)
        else:
            end = date(year, month + 1, 1) - timedelta(days=1)
        bonus, lines = self._expense_mix_match_bonus()
        # Rewrite first line to explicitly say month-end score.
        lines = [f"Month-end mix score for {start.strftime('%b %Y')}: {lines[0].split(':', 1)[-1].strip()}"] + lines[1:]
        return bonus, lines

    # ── Progression Systems ───────────────────────────────────────────────────

    def ensure_season(self):
        """Start or reset the season if the calendar month has changed."""
        current_ym = date.today().strftime("%Y-%m")
        g = self.state.game
        if g.season_year_month != current_ym:
            g.season_year_month = current_ym
            g.season_xp = 0
            g.season_claimed_tiers = []
            g.perks_unlocked = [p for p in g.perks_unlocked if p != "season_boost"]

    def add_season_xp(self, amount: int) -> List[int]:
        """Add Season XP (with Scholar bonus). Returns newly claimable tier indices."""
        g = self.state.game
        self.ensure_season()
        bonus = 1.25 if "season_boost" in g.perks_unlocked else 1.0
        if self.xp_window_active():
            bonus *= 2.0   # pay-week weekend: double XP
        gain = max(1, int(round(amount * bonus)))
        g.season_xp += gain
        self._track_weekly_xp(gain)
        return [i for i, (xp, _, _, _) in enumerate(SEASON_TIERS)
                if g.season_xp >= xp and i not in g.season_claimed_tiers]

    def claim_season_tier(self, tier_idx: int) -> dict:
        """Claim a season tier reward. Returns reward info dict or empty if not claimable."""
        g = self.state.game
        if tier_idx in g.season_claimed_tiers or tier_idx >= len(SEASON_TIERS):
            return {}
        xp_threshold, reward_type, reward_amount, tier_name = SEASON_TIERS[tier_idx]
        if g.season_xp < xp_threshold:
            return {}
        g.season_claimed_tiers.append(tier_idx)
        if reward_type == "gold":
            g.total_score += reward_amount
            g.level = self.level_from_score(g.total_score)
        elif reward_type == "gems":
            g.gems += reward_amount
            g.lifetime_gems_earned += reward_amount
        out = {"tier_name": tier_name, "reward_type": reward_type, "reward_amount": reward_amount}
        if tier_idx == len(SEASON_TIERS) - 1:
            pid = self.unlock_season_palette()
            if pid:
                out["palette"] = pid
        return out

    def generate_daily_challenges(self):
        """3 challenges a day, every one doable today. When a pay is expected
        (±1 day) one slot is swapped for a pay-day challenge."""
        import random
        g = self.state.game
        today_str = date.today().isoformat()
        if g.daily_challenges_date == today_str and len(g.daily_challenges) == 3:
            return
        picked = random.sample(CHALLENGE_POOL, 3)
        if self.is_pay_day_window():
            picked[0] = random.choice(PAYDAY_CHALLENGES)
        g.daily_challenges = [
            {"id": c[0], "description": c[1], "trigger": c[2],
             "reward_type": c[3], "reward_amount": c[4], "completed": False}
            for c in picked
        ]
        g.daily_challenges_date = today_str
        self.ensure_weekly()

    def complete_challenge(self, trigger: str) -> List[dict]:
        """Mark matching incomplete daily challenges done and award rewards.
        Also advances the weekly trio (completed ones land in
        `self.last_weekly_done` so the UI can toast them)."""
        g = self.state.game
        completed = []
        for ch in g.daily_challenges:
            if ch.get("trigger") == trigger and not ch.get("completed"):
                ch["completed"] = True
                if ch["reward_type"] == "gold":
                    g.total_score += ch["reward_amount"]
                    g.level = self.level_from_score(g.total_score)
                elif ch["reward_type"] == "gems":
                    g.gems += ch["reward_amount"]
                    g.lifetime_gems_earned += ch["reward_amount"]
                self.add_season_xp(15)
                completed.append(dict(ch))
        self.last_weekly_done = self._advance_weekly(trigger)
        return completed

    def draw_fortune_card(self) -> dict:
        """Draw a weighted random fortune card and apply its effect."""
        import random
        g = self.state.game
        cards = list(FORTUNE_CARDS)
        if "fortune_up" in g.perks_unlocked:
            cards = [(t, s, tx, eff, amt, int(w * 1.3) if eff != "none" else max(1, w - 5))
                     for t, s, tx, eff, amt, w in cards]
        weights = [c[5] for c in cards]
        title, symbol, text, effect_type, effect_amount, _ = random.choices(cards, weights=weights, k=1)[0]
        if effect_type == "gold":
            g.total_score += effect_amount
            g.level = self.level_from_score(g.total_score)
        elif effect_type == "gems":
            g.gems += effect_amount
            g.lifetime_gems_earned += effect_amount
        elif effect_type == "season_xp":
            self.add_season_xp(effect_amount)
        elif effect_type == "buff_double_mix":
            if "double_mix" not in g.active_buffs:
                g.active_buffs.append("double_mix")
        elif effect_type == "buff_streak_shield":
            g.streak_shields += 1
        return {"title": title, "symbol": symbol, "text": text,
                "effect_type": effect_type, "effect_amount": effect_amount}

    def _perk_multiplier_bonus(self) -> float:
        return self.state.game.perks_unlocked.count("score_boost") * 0.10

    def buy_perk(self, perk_id: str) -> tuple:
        """Buy a perk. Returns (success: bool, message: str)."""
        g = self.state.game
        perk = next((p for p in PERK_SHOP_ITEMS if p[0] == perk_id), None)
        if not perk:
            return False, "Unknown perk."
        pid, name, _, gem_cost, max_stacks = perk
        gem_cost = self.featured_cost(pid, gem_cost)   # today's deal
        if g.perks_unlocked.count(perk_id) >= max_stacks:
            return False, f"{name} is already at max level."
        if g.gems < gem_cost:
            return False, f"Not enough Gems. Need {gem_cost}, have {g.gems}."
        g.gems -= gem_cost
        g.perks_unlocked.append(perk_id)
        if perk_id == "score_boost":
            g.score_multiplier = round(1.0 + g.prestige_level * 0.10 + self._perk_multiplier_bonus(), 2)
        elif perk_id == "streak_shield":
            g.streak_shields += 1
        return True, f"{name} purchased!"

    def check_card_set_completions(self) -> list:
        """Check all card sets and auto-unlock any completed set rewards.
        Returns list of (set_name, reward_item_name) for newly completed sets."""
        g = self.state.game
        unique_owned = set(g.cards_owned)
        newly_completed = []
        for sid, sname, sdesc, card_ids, reward_item_id in CARD_SETS:
            if reward_item_id in g.character_items_owned:
                continue  # already claimed
            if all(cid in unique_owned for cid in card_ids):
                g.character_items_owned.append(reward_item_id)
                item = AVATAR_ITEMS.get(reward_item_id, {})
                newly_completed.append((sname, item.get("name", reward_item_id)))
        return newly_completed

    def card_set_progress(self) -> dict:
        """Return completion progress for all card sets.
        Returns {set_id: (owned_count, total_count, is_complete, reward_claimed)}"""
        g = self.state.game
        unique_owned = set(g.cards_owned)
        result = {}
        for sid, sname, sdesc, card_ids, reward_item_id in CARD_SETS:
            owned_count = sum(1 for cid in card_ids if cid in unique_owned)
            total = len(card_ids)
            complete = owned_count == total
            claimed = reward_item_id in g.character_items_owned
            result[sid] = (owned_count, total, complete, claimed)
        return result

    HOMESTEAD_COMPANIONS = {1: "comp_hen", 2: "comp_cat", 3: "comp_fox", 4: "comp_owl", 5: "comp_dragonet"}

    # ── Daily Pulse + variable Vault ─────────────────────────────────────
    # The Pulse is the daily unit of real behaviour: (1) yesterday's cash
    # spending or a no-spend tick, (2) one imported row sorted, (3) open the
    # vault. Finishing it extends the daily run. Freezes are earned every
    # 7 days (bank of 2) and absorb missed days; a broken run can be
    # repaired within 48 h for Gems.
    VAULT_CHESTS = {
        # tier: (gold, gems, season_xp, label)
        "bronze": (6, 0, 10, "Bronze chest"),
        "silver": (12, 0, 10, "Silver chest"),
        "gold":   (20, 1, 15, "Gold chest"),
        "mythic": (40, 3, 40, "Mythic chest"),
    }
    PULSE_MILESTONES = (3, 7, 14, 21, 30, 60, 100, 200, 365)
    PULSE_FREEZE_CAP = 2

    def mark_real_action(self):
        self.state.game.last_real_action_date = date.today().isoformat()

    @staticmethod
    def vault_odds(day: int) -> dict:
        """Chest odds (percent) for run day `day`. Every 7th day guarantees Gold+."""
        d = max(1, int(day))
        if d % 7 == 0:
            return {"bronze": 0, "silver": 0, "gold": 70 if d % 14 else 55, "mythic": 30 if d % 14 else 45}
        k = min(d, 6) - 1
        bronze = max(0, 55 - 9 * k)
        silver = 30 + 5 * k
        gold = 12 + 3 * k
        mythic = 3 + k
        return {"bronze": bronze, "silver": silver, "gold": gold, "mythic": mythic}

    def _pulse_missed_days(self, last: date, today: date) -> int:
        skip_weekends = bool(self.state.ui_prefs.get("pulse.skip_weekends", False))
        missed = 0
        d = last + timedelta(days=1)
        while d < today:
            if not (skip_weekends and d.weekday() >= 5):
                missed += 1
            d += timedelta(days=1)
        return missed

    def ensure_pulse(self):
        """Roll the daily run forward: consume freezes for missed days or break
        the run (remembering it for a 48 h repair window). Idempotent."""
        g = self.state.game
        today = date.today()
        if not g.pulse_last_date:
            return
        try:
            last = date.fromisoformat(g.pulse_last_date)
        except ValueError:
            g.pulse_last_date = ""
            return
        if last >= today:
            return
        missed = self._pulse_missed_days(last, today)
        if missed == 0:
            return
        if g.pulse_streak > 0 and missed <= g.pulse_freezes:
            g.pulse_freezes -= missed
            g.pulse_freeze_log = (g.pulse_freeze_log + [today.isoformat()] * missed)[-20:]
            g.pulse_last_date = (today - timedelta(days=1)).isoformat()
            return
        if g.pulse_streak > 0:
            g.pulse_broken_len = g.pulse_streak
            g.pulse_broken_date = today.isoformat()
        g.pulse_streak = 0
        g.pulse_last_date = (today - timedelta(days=1)).isoformat()   # don't re-break tomorrow

    def _pulse_progress_today(self) -> dict:
        g = self.state.game
        t = date.today().isoformat()
        if g.pulse_progress.get("date") != t:
            g.pulse_progress = {"date": t, "spend": False, "sort": False, "no_spend": False, "logged": 0.0, "note": ""}
        return g.pulse_progress

    def pulse_mark_beat(self, beat: str, **extra):
        p = self._pulse_progress_today()
        p[beat] = True
        for k, v in extra.items():
            p[k] = v

    def repair_cost(self) -> int:
        g = self.state.game
        return int(min(6, 2 + g.pulse_broken_len // 7))

    def pulse_repairable(self) -> Optional[dict]:
        g = self.state.game
        if g.pulse_broken_len <= 0 or not g.pulse_broken_date:
            return None
        try:
            broke = date.fromisoformat(g.pulse_broken_date)
        except ValueError:
            return None
        hours_left = 48 - int((datetime.now() - datetime.combine(broke, datetime.min.time())).total_seconds() // 3600)
        if hours_left <= 0:
            g.pulse_broken_len = 0
            g.pulse_broken_date = ""
            return None
        return {"length": g.pulse_broken_len, "cost": self.repair_cost(), "hours_left": hours_left}

    def repair_pulse(self) -> tuple:
        g = self.state.game
        rep = self.pulse_repairable()
        if not rep:
            return False, "Nothing to repair."
        if g.gems < rep["cost"]:
            return False, f"Need {rep['cost']} Gems (have {g.gems})."
        g.gems -= rep["cost"]
        g.pulse_streak = rep["length"]
        g.pulse_broken_len = 0
        g.pulse_broken_date = ""
        if g.pulse_last_date != date.today().isoformat():
            g.pulse_last_date = (date.today() - timedelta(days=1)).isoformat()
        return True, f"Run restored to {g.pulse_streak} days."

    def vault_status(self) -> dict:
        """Everything the Pulse card needs. `day` is the run day the vault
        would be (or was) opened on today."""
        self.ensure_pulse()
        g = self.state.game
        t = date.today().isoformat()
        p = self._pulse_progress_today()
        opened_today = g.pulse_last_date == t and g.pulse_streak > 0
        streak = g.pulse_streak
        day = streak if opened_today else streak + 1
        odds = self.vault_odds(day)
        bonus = g.last_real_action_date == t
        ready = bool(p.get("spend")) and bool(p.get("sort"))
        return {"opened_today": opened_today, "streak": streak, "day": day, "odds": odds,
                "bonus": bonus, "ready": ready, "progress": dict(p), "freezes": g.pulse_freezes,
                "best": g.pulse_best, "last_tier": g.vault_last_tier if opened_today else "",
                "repair": self.pulse_repairable(), "guaranteed": day % 7 == 0,
                "gold_with_bonus": self.VAULT_CHESTS["silver"][0] * (2 if bonus else 1)}

    def open_vault(self, force_tier: Optional[str] = None) -> Optional[dict]:
        """Final Pulse beat. Rolls the chest, extends the run, earns freezes."""
        import random
        st = self.vault_status()
        if st["opened_today"]:
            return None
        g = self.state.game
        today = date.today()
        tier = force_tier or g.vault_force_tier or random.choices(
            list(st["odds"].keys()), weights=list(st["odds"].values()), k=1)[0]
        g.vault_force_tier = ""
        gold, gems, xp, label = self.VAULT_CHESTS.get(tier, self.VAULT_CHESTS["bronze"])
        if st["bonus"]:
            gold *= 2
        g.pulse_streak = st["streak"] + 1
        g.pulse_best = max(g.pulse_best, g.pulse_streak)
        self.update_record("pulse_run", g.pulse_best)
        g.pulse_days_total += 1
        g.pulse_last_date = today.isoformat()
        g.pulse_broken_len = 0
        g.pulse_broken_date = ""
        g.vault_last_opened = today.isoformat()
        g.vault_visit_streak = g.pulse_streak
        g.vault_last_tier = tier
        freeze_earned = False
        if g.pulse_streak % 7 == 0 and g.pulse_freezes < self.PULSE_FREEZE_CAP:
            g.pulse_freezes += 1
            freeze_earned = True
        g.total_score += gold
        g.level = self.level_from_score(g.total_score)
        if gems:
            g.gems += gems
            g.lifetime_gems_earned += gems
        self.add_season_xp(xp)
        completed = self.complete_challenge("pulse")
        milestone = g.pulse_streak if g.pulse_streak in self.PULSE_MILESTONES else 0
        return {"tier": tier, "label": label, "gold": gold, "gems": gems, "xp": xp, "day": st["day"],
                "streak": g.pulse_streak, "bonus": st["bonus"], "freeze_earned": freeze_earned,
                "milestone": milestone, "completed_challenges": completed}

    def record_no_spend_day(self) -> int:
        """Yesterday was a no-spend day. Returns the new no-spend run length."""
        g = self.state.game
        y = (date.today() - timedelta(days=1)).isoformat()
        if g.no_spend_last == y:
            return g.no_spend_streak
        prev = date.fromisoformat(g.no_spend_last) if g.no_spend_last else None
        if prev and (date.fromisoformat(y) - prev).days == 1:
            g.no_spend_streak += 1
        else:
            g.no_spend_streak = 1
        g.no_spend_last = y
        g.no_spend_best = max(g.no_spend_best, g.no_spend_streak)
        g.no_spend_days_total += 1
        g.no_spend_dates = (g.no_spend_dates + [y])[-120:]
        self.update_record("no_spend_run", g.no_spend_best)
        self.complete_challenge("no_spend")
        return g.no_spend_streak

    # ── Weekly challenges ────────────────────────────────────────────────
    def ensure_weekly(self):
        g = self.state.game
        week = date.today().strftime("%G-W%V")
        if g.weekly_week == week and len(g.weekly_challenges) == len(WEEKLY_CHALLENGES):
            return
        g.weekly_week = week
        g.weekly_reward_claimed = False
        g.weekly_challenges = [{"id": c[0], "description": c[1], "trigger": c[2], "goal": c[3],
                                "progress": 0, "completed": False} for c in WEEKLY_CHALLENGES]

    def _advance_weekly(self, trigger: str) -> List[dict]:
        self.ensure_weekly()
        done = []
        for ch in self.state.game.weekly_challenges:
            if ch["trigger"] == trigger and not ch["completed"]:
                ch["progress"] = min(ch["goal"], ch["progress"] + 1)
                if ch["progress"] >= ch["goal"]:
                    ch["completed"] = True
                    done.append(dict(ch))
        return done

    def weekly_all_done(self) -> bool:
        self.ensure_weekly()
        return all(ch["completed"] for ch in self.state.game.weekly_challenges)

    def claim_weekly_reward(self) -> Optional[dict]:
        g = self.state.game
        if not self.weekly_all_done() or g.weekly_reward_claimed:
            return None
        g.weekly_reward_claimed = True
        return self.open_pack("gem", free=True)

    def is_pay_day_window(self) -> bool:
        s = self.state
        if not s.incomes:
            return False
        last = max(i.received_on for i in s.incomes)
        cycle = BudgetEngine.PAY_CYCLE_DAYS.get(s.pay_frequency, 14)
        return abs(((last + timedelta(days=cycle)) - date.today()).days) <= 1

    # ── Day-one head start ───────────────────────────────────────────────
    def day_one_head_start(self, *, award_pack: bool = True) -> dict:
        """Endowed progress for a new profile: Founder card, a free pack,
        season XP head start, and today's Pulse beats pre-done so the first
        vault opens with a guaranteed Gold chest. Idempotent."""
        g = self.state.game
        if g.day_one_done:
            return {}
        g.day_one_done = True
        out = {"founder": False, "pack": None}
        if FOUNDER_CARD_ID not in g.cards_owned:
            g.cards_owned.append(FOUNDER_CARD_ID)
            out["founder"] = True
        g.season_xp = max(g.season_xp, 30)
        self.mark_real_action()
        self.pulse_mark_beat("spend", note="Setting up your plan counts as today's real work.")
        self.pulse_mark_beat("sort")
        if not g.pulse_last_date:
            g.vault_force_tier = "gold"
        if award_pack:
            out["pack"] = self.open_pack("standard", free=True)
        return out

    # ── Homestead idle accrual (appointment mechanic) ───────────────────
    # The windmill mills Gold while the app is closed (rate by Homestead
    # tier, quartered while a bill is overdue, capped at 8 h of production);
    # a contribution plants a plot that ripens 12 h later into a pack
    # fragment. Five fragments open a free Standard Pack. All timestamp
    # based — nothing runs in the background.
    MILL_CAP_HOURS = 8.0
    PLOT_RIPEN_HOURS = 12.0
    FRAGMENTS_PER_PACK = 5

    def mill_rate(self) -> float:
        g = self.state.game
        rate = 2.0 + 2.0 * max(0, min(5, g.homestead_tier))
        today = date.today()
        if any(b.due_date < today and b.current_saved + 0.01 < b.amount for b in self.state.bills):
            rate *= 0.25
        return rate

    def mill_status(self, now: Optional[datetime] = None) -> dict:
        g = self.state.game
        now = now or datetime.now()
        if not g.mill_last_collected:
            g.mill_last_collected = now.isoformat(timespec="minutes")
        try:
            last = datetime.fromisoformat(g.mill_last_collected)
        except ValueError:
            last = now
            g.mill_last_collected = now.isoformat(timespec="minutes")
        hours = max(0.0, (now - last).total_seconds() / 3600.0)
        capped = hours >= self.MILL_CAP_HOURS
        hours = min(hours, self.MILL_CAP_HOURS)
        rate = self.mill_rate()
        gold = int(hours * rate)
        return {"gold": gold, "hours": hours, "capped": capped, "rate": rate, "ready": gold >= 1,
                "hours_to_cap": max(0.0, self.MILL_CAP_HOURS - hours)}

    def collect_mill(self, now: Optional[datetime] = None) -> int:
        g = self.state.game
        now = now or datetime.now()
        st = self.mill_status(now)
        if st["gold"] < 1:
            return 0
        gold = st["gold"]
        g.total_score += gold
        g.level = self.level_from_score(g.total_score)
        g.mill_last_collected = now.isoformat(timespec="minutes")
        g.mill_gold_total += gold
        self.update_record("mill_haul", gold)
        return gold

    def plant(self, kind: str, name: str, now: Optional[datetime] = None) -> bool:
        """A contribution plants `kind:name`; returns False if already growing."""
        g = self.state.game
        key = f"{kind}:{name}"
        if key in g.plot_timers:
            return False
        now = now or datetime.now()
        g.plot_timers[key] = (now + timedelta(hours=self.PLOT_RIPEN_HOURS)).isoformat(timespec="minutes")
        return True

    def plot_status(self, now: Optional[datetime] = None) -> List[dict]:
        g = self.state.game
        now = now or datetime.now()
        live = {f"fund:{f.name}" for f in self.state.funds} | {f"goal:{x.name}" for x in self.state.goals}
        for key in [k for k in g.plot_timers if k not in live]:
            del g.plot_timers[key]
        out = []
        for key, iso in sorted(g.plot_timers.items()):
            try:
                ripe_at = datetime.fromisoformat(iso)
            except ValueError:
                ripe_at = now
            left = (ripe_at - now).total_seconds() / 3600.0
            kind, _, name = key.partition(":")
            out.append({"key": key, "kind": kind, "name": name, "ripe": left <= 0, "hours_left": max(0.0, left)})
        return out

    def harvest(self, key: str, now: Optional[datetime] = None) -> Optional[dict]:
        g = self.state.game
        st = next((p for p in self.plot_status(now) if p["key"] == key), None)
        if not st or not st["ripe"]:
            return None
        del g.plot_timers[key]
        g.pack_fragments += 1
        g.harvests_total += 1
        pack = None
        if g.pack_fragments >= self.FRAGMENTS_PER_PACK:
            g.pack_fragments -= self.FRAGMENTS_PER_PACK
            pack = self.open_pack("standard", free=True)
        return {"name": st["name"], "fragments": g.pack_fragments, "pack": pack}

    def harvest_all(self, now: Optional[datetime] = None) -> dict:
        names, packs = [], []
        for p in [p for p in self.plot_status(now) if p["ripe"]]:
            r = self.harvest(p["key"], now)
            if r:
                names.append(r["name"])
                if r["pack"]:
                    packs.append(r["pack"])
        return {"names": names, "packs": packs, "fragments": self.state.game.pack_fragments}

    # ── Personal records + money milestones ──────────────────────────────
    RECORD_DEFS = {
        "savings_rate":         ("Best savings rate on a pay",      "{:.0%}"),
        "biggest_contribution": ("Biggest single contribution",     "${:,.0f}"),
        "reserved_total":       ("Most set aside at once",          "${:,.0f}"),
        "pulse_run":            ("Longest Daily Pulse run",         "{} days"),
        "no_spend_run":         ("Longest no-spend run",            "{} days"),
        "pay_streak":           ("Longest pay streak",              "{} pays"),
        "mill_haul":            ("Biggest windmill haul",           "{} Gold"),
    }

    def update_record(self, key: str, value, when: Optional[date] = None) -> Optional[str]:
        """Returns 'new' when a previous record was beaten, 'first' when set
        for the first time, else None."""
        g = self.state.game
        if key not in self.RECORD_DEFS or value is None:
            return None
        try:
            v = float(value)
        except (TypeError, ValueError):
            return None
        if v <= 0:
            return None
        prev = g.records.get(key)
        when = when or date.today()
        if prev is None:
            g.records[key] = {"value": v, "date": when.isoformat()}
            return "first"
        if v > float(prev.get("value", 0)) + 1e-9:
            g.records[key] = {"value": v, "date": when.isoformat(), "prev": float(prev.get("value", 0))}
            return "new"
        return None

    def record_text(self, key: str) -> str:
        label, fmt = self.RECORD_DEFS[key]
        rec = self.state.game.records.get(key)
        if not rec:
            return "—"
        v = rec["value"]
        return fmt.format(v if "{:" in fmt and "." in fmt else int(round(v)))

    MONEY_DOLLAR_STEPS = ((100, 10), (500, 25), (1000, 50), (2500, 75), (5000, 100), (10000, 150), (25000, 250))
    MONEY_PCT_STEPS = ((25, 15), (50, 25), (75, 35), (100, 60))

    def _reserved_total(self) -> float:
        s = self.state
        return sum(min(b.current_saved, b.amount) for b in s.bills) + sum(f.current_saved for f in s.funds) + sum(x.current_saved for x in s.goals)

    def check_money_milestones(self, award: bool = True) -> List[dict]:
        """Award (or, with award=False, silently seed) every dollar / percent
        milestone the plan has already crossed. Returns the new ones."""
        g = self.state.game
        claimed = set(g.money_milestones)
        new = []

        def hit(key, label, gold):
            if key in claimed:
                return
            claimed.add(key)
            g.money_milestones.append(key)
            if award:
                g.total_score += gold
                new.append({"key": key, "label": label, "gold": gold})

        for kind, items in (("fund", self.state.funds), ("goal", self.state.goals)):
            for obj in items:
                saved = float(obj.current_saved)
                for step, gold in self.MONEY_DOLLAR_STEPS:
                    if saved + 0.005 >= step:
                        hit(f"{kind}:{obj.name}:${step}", f"{obj.name} passed ${step:,}", gold)
                if BudgetEngine.has_end_target(obj) and obj.target_amount > 0:
                    pct = saved / obj.target_amount * 100.0
                    for step, gold in self.MONEY_PCT_STEPS:
                        if pct + 1e-6 >= step:
                            hit(f"{kind}:{obj.name}:pct{step}", f"{obj.name} {'is fully funded' if step == 100 else f'is {step}% there'}", gold)
        total = self._reserved_total()
        k = int(total // 1000)
        for n in range(1, k + 1):
            hit(f"total:{n}000", f"${n:,}k set aside across the plan", 30)
        if new:
            g.level = self.level_from_score(g.total_score)
        new.sort(key=lambda m: -m["gold"])
        return new

    def final_stretch_bonus(self, pre_ratios: dict) -> int:
        """+15 Gold for each fund/goal that was ≥80% funded before this pay
        and received money from it (goal-gradient reward). Cap 45."""
        g = self.state.game
        bonus = 0
        for kind, items in (("fund", self.state.funds), ("goal", self.state.goals)):
            for obj in items:
                key = f"{kind}:{obj.name}"
                pre = pre_ratios.get(key)
                if pre is None:
                    continue
                ratio, saved_before = pre
                if ratio >= 0.8 and obj.current_saved > saved_before + 0.005:
                    bonus += 15
        bonus = min(bonus, 45)
        if bonus:
            g.total_score += bonus
            g.last_score_gain += bonus
            g.level = self.level_from_score(g.total_score)
        return bonus

    def pre_pay_ratios(self) -> dict:
        out = {}
        for kind, items in (("fund", self.state.funds), ("goal", self.state.goals)):
            for obj in items:
                if BudgetEngine.has_end_target(obj) and obj.target_amount > 0:
                    out[f"{kind}:{obj.name}"] = (obj.current_saved / obj.target_amount, obj.current_saved)
        return out

    # ── Pacts with Gerald (commitment contracts in Gems) ─────────────────
    PACT_KINDS = {
        "reserve": {"title": "Reserve {pct}% of my next pay", "card": "p_oath_reserve", "days": 21},
        "cap":     {"title": "Keep {cat} under ${cap:,.0f} this week", "card": "p_oath_cap", "days": 7},
        "fund":    {"title": "Get {name} to ${target:,.0f} by {date}", "card": "p_oath_fund", "days": None},
        "nospend": {"title": "{n} no-spend days in the next 7", "card": "p_oath_nospend", "days": 7},
    }
    PACT_MAX_STAKE = 6

    def pact_title(self, pact: dict) -> str:
        kind = pact.get("kind", "")
        p = dict(pact.get("params", {}))
        spec = self.PACT_KINDS.get(kind)
        if not spec:
            return "Pact"
        if kind == "fund":
            p["date"] = pact.get("deadline", "")
            try:
                p["date"] = date.fromisoformat(pact["deadline"]).strftime("%d %b")
            except (ValueError, KeyError):
                pass
        try:
            return spec["title"].format(**p)
        except (KeyError, ValueError):
            return spec["title"]

    def make_pact(self, kind: str, params: dict, stake: int, today: Optional[date] = None) -> tuple:
        g = self.state.game
        today = today or date.today()
        if g.active_pact:
            return False, "One pact at a time — settle the current one first."
        if kind not in self.PACT_KINDS:
            return False, "Unknown pact."
        stake = int(stake)
        if stake < 1 or stake > self.PACT_MAX_STAKE:
            return False, f"Stake 1 to {self.PACT_MAX_STAKE} Gems."
        if g.gems < stake:
            return False, f"You have {g.gems} Gems — stake less."
        spec = self.PACT_KINDS[kind]
        if kind == "fund":
            try:
                deadline = date.fromisoformat(str(params.get("deadline", "")))
            except ValueError:
                return False, "Pick a date for the pact."
            if deadline <= today:
                return False, "The date has to be in the future."
            if not any(f.name == params.get("name") for f in self.state.funds) and not any(x.name == params.get("name") for x in self.state.goals):
                return False, "Pick a fund or goal."
        else:
            days = spec["days"]
            if kind == "reserve":
                days = max(7, int(BudgetEngine.PAY_CYCLE_DAYS.get(self.state.pay_frequency, 14) * 1.5))
            deadline = today + timedelta(days=days)
        g.gems -= stake
        g.active_pact = {"kind": kind, "params": dict(params), "stake": stake, "start": today.isoformat(),
                         "deadline": deadline.isoformat(), "status": "open", "created": datetime.now().isoformat(timespec="minutes")}
        return True, "Pact made."

    def _pact_spent_in_cap(self, pact: dict) -> float:
        cat = str(pact["params"].get("cat", "")).lower()
        start = date.fromisoformat(pact["start"]); end = date.fromisoformat(pact["deadline"])
        return sum(t.money_out for t in self.state.transactions
                   if t.money_out > 0 and (t.category or "").lower() == cat and start <= t.tx_date <= end)

    def pact_progress(self, today: Optional[date] = None) -> Optional[dict]:
        """{'text','pct','done','failed','days_left'} for the active pact."""
        g = self.state.game
        pact = g.active_pact
        if not pact:
            return None
        today = today or date.today()
        deadline = date.fromisoformat(pact["deadline"])
        days_left = (deadline - today).days
        kind, p = pact["kind"], pact["params"]
        done = failed = False
        if kind == "reserve":
            ratio = pact.get("result_ratio")
            if ratio is None:
                text = f"Waiting for your next pay (by {deadline:%d %b})."
                pct = 0.0
                failed = days_left < 0
            else:
                pct = min(1.0, ratio / (p["pct"] / 100.0))
                done = ratio * 100 + 1e-6 >= p["pct"]
                failed = not done
                text = f"Reserved {ratio:.0%} of ${pact.get('result_pay', 0):,.0f}."
        elif kind == "cap":
            spent = self._pact_spent_in_cap(pact)
            cap = float(p["cap"])
            pct = min(1.0, spent / cap) if cap else 1.0
            text = f"${spent:,.0f} of ${cap:,.0f} spent on {p['cat']}."
            failed = spent > cap + 0.005
            done = (not failed) and days_left < 0
        elif kind == "fund":
            obj = next((f for f in self.state.funds if f.name == p.get("name")), None) or \
                  next((x for x in self.state.goals if x.name == p.get("name")), None)
            saved = float(obj.current_saved) if obj else 0.0
            target = float(p["target"])
            pct = min(1.0, saved / target) if target else 1.0
            text = f"{p.get('name')}: ${saved:,.0f} of ${target:,.0f}."
            done = saved + 0.005 >= target
            failed = (not done) and days_left < 0
        else:  # nospend
            start = date.fromisoformat(pact["start"])
            n = sum(1 for d in g.no_spend_dates if start <= date.fromisoformat(d) <= deadline)
            goal = int(p["n"])
            pct = min(1.0, n / goal)
            text = f"{n} of {goal} no-spend days."
            done = n >= goal
            failed = (not done) and days_left < 0
        return {"text": text, "pct": pct, "done": done, "failed": failed, "days_left": days_left,
                "title": self.pact_title(pact), "stake": pact["stake"]}

    def pact_note_pay(self, pay_amount: float, reserved: float):
        pact = self.state.game.active_pact
        if pact and pact.get("kind") == "reserve" and pact.get("result_ratio") is None:
            pact["result_ratio"] = (reserved / pay_amount) if pay_amount > 0 else 0.0
            pact["result_pay"] = float(pay_amount)

    def settle_pacts(self, today: Optional[date] = None) -> Optional[dict]:
        """Resolve the active pact if it is decided. Returns the outcome or None."""
        g = self.state.game
        prog = self.pact_progress(today)
        if not prog or not (prog["done"] or prog["failed"]):
            return None
        pact = dict(g.active_pact)
        won = bool(prog["done"])
        stake = int(pact["stake"])
        card_awarded = ""
        if won:
            g.gems += stake * 2
            g.lifetime_gems_earned += stake
            g.total_score += 50
            g.level = self.level_from_score(g.total_score)
            self.add_season_xp(50)
            g.pacts_won += 1
            cid = self.PACT_KINDS[pact["kind"]]["card"]
            if cid not in g.cards_owned:
                g.cards_owned.append(cid)
                card_awarded = cid
        else:
            g.pacts_lost += 1
        pact["status"] = "won" if won else "lost"
        pact["settled"] = (today or date.today()).isoformat()
        g.pact_history = (g.pact_history + [pact])[-20:]
        g.active_pact = {}
        return {"won": won, "stake": stake, "title": self.pact_title(pact), "card": card_awarded, "text": prog["text"]}

    def cancel_pact(self) -> bool:
        """Call it off: the stake is forfeited (a pact is a pact)."""
        g = self.state.game
        if not g.active_pact:
            return False
        pact = dict(g.active_pact)
        pact["status"] = "cancelled"
        g.pact_history = (g.pact_history + [pact])[-20:]
        g.pacts_lost += 1
        g.active_pact = {}
        return True

    # ── Savings challenges ───────────────────────────────────────────────
    def challenge_spec(self, cid: str) -> Optional[dict]:
        return next((c for c in SAVINGS_CHALLENGES if c["id"] == cid), None)

    def challenge_fund(self, cid: str):
        return next((f for f in self.state.funds if getattr(f, "challenge", "") == cid), None)

    def challenge_active(self, cid: str) -> bool:
        spec = self.challenge_spec(cid)
        if not spec:
            return False
        if spec["kind"] == "fund":
            return self.challenge_fund(cid) is not None
        if spec["kind"] == "nospend":
            return bool(self.state.game.nospend_challenge.get("started"))
        if spec["kind"] == "goal":
            return any(x.name == spec["goal"]["name"] for x in self.state.goals)
        return False

    def start_challenge(self, cid: str, today: Optional[date] = None) -> tuple:
        spec = self.challenge_spec(cid)
        if not spec:
            return False, "Unknown challenge."
        if self.challenge_active(cid):
            return False, "Already running."
        today = today or date.today()
        if spec["kind"] == "fund":
            fs = spec["fund"]
            td = today + timedelta(days=fs.get("days", 0)) if fs.get("days") else None
            f = Fund(spec["name"], float(fs.get("target", 0.0)), td, "important", 0.0, fs.get("mode", "fixed"),
                     float(fs.get("fixed", 0.0)), "Fund")
            f.challenge = cid
            f.challenge_started = today.isoformat()
            self.state.funds.append(f)
            self.sync_challenge_funds(today)
        elif spec["kind"] == "goal":
            gs = spec["goal"]
            self.state.goals.append(Goal(gs["name"], float(gs.get("target", 0.0)), None, 5, 0.0, gs.get("mode", "percent_surplus"), float(gs.get("value", 10))))
        else:
            self.state.game.nospend_challenge = {"started": today.isoformat(), "claimed": []}
        return True, f"{spec['name']} started."

    def sync_challenge_funds(self, today: Optional[date] = None):
        """52-week: this pay's amount = the sum of the week numbers that fall in the next cycle."""
        today = today or date.today()
        cycle_weeks = max(1, round(BudgetEngine.PAY_CYCLE_DAYS.get(self.state.pay_frequency, 14) / 7))
        for f in self.state.funds:
            if getattr(f, "challenge", "") != "52week" or not f.challenge_started:
                continue
            start = date.fromisoformat(f.challenge_started)
            week = min(52, max(1, (today - start).days // 7 + 1))
            # weeks already covered by what's saved
            covered = self.challenge_filled("52week", f)
            nxt = max(week, covered + 1)
            f.fixed_amount = float(sum(range(nxt, min(52, nxt + cycle_weeks - 1) + 1)))

    def challenge_filled(self, cid: str, obj=None) -> int:
        """How many grid cells are filled for a challenge."""
        spec = self.challenge_spec(cid)
        if not spec:
            return 0
        if spec["kind"] == "nospend":
            ch = self.state.game.nospend_challenge
            if not ch.get("started"):
                return 0
            start = date.fromisoformat(ch["started"]); end = start + timedelta(days=spec["cells"] - 1)
            return sum(1 for d in self.state.game.no_spend_dates if start <= date.fromisoformat(d) <= end)
        f = obj or self.challenge_fund(cid)
        if f is None:
            return 0
        if cid == "52week":
            n = 0
            while n < 52 and (n + 1) * (n + 2) / 2 <= f.current_saved + 0.005:
                n += 1
            return n
        if cid == "fiver":
            return min(spec["cells"], int(f.current_saved // 5))
        if cid == "roundup":
            return min(spec["cells"], int(getattr(f, "challenge_ticks", 0)))
        return 0

    def check_challenge_rewards(self) -> List[dict]:
        """25% → +50 Gold, 50% → +2 Gems, 100% → +5 Gems + the Champion card."""
        g = self.state.game
        out = []
        for spec in SAVINGS_CHALLENGES:
            if spec["kind"] == "goal" or not self.challenge_active(spec["id"]):
                continue
            filled = self.challenge_filled(spec["id"])
            pct = filled / float(spec["cells"]) * 100.0
            if spec["kind"] == "nospend":
                claimed = g.nospend_challenge.setdefault("claimed", [])
            else:
                f = self.challenge_fund(spec["id"])
                claimed = f.challenge_claimed
            for step in (25, 50, 100):
                if pct + 1e-6 >= step and step not in claimed:
                    claimed.append(step)
                    if step == 25:
                        g.total_score += 50; reward = "+50 Gold"
                    elif step == 50:
                        g.gems += 2; g.lifetime_gems_earned += 2; reward = "+2 Gems"
                    else:
                        g.gems += 5; g.lifetime_gems_earned += 5; reward = "+5 Gems"
                        if CHAMPION_CARD_ID not in g.cards_owned:
                            g.cards_owned.append(CHAMPION_CARD_ID); reward += " + the Champion card"
                    out.append({"challenge": spec["name"], "step": step, "reward": reward})
        if out:
            g.level = self.level_from_score(g.total_score)
        return out

    def roundup_for_spend(self, amount: float) -> Optional[tuple]:
        """If a round-up jar is running, move the change up to the next $5 into it."""
        f = self.challenge_fund("roundup")
        if f is None or amount <= 0:
            return None
        diff = round(math.ceil(amount / 5.0) * 5.0 - amount, 2)
        if diff <= 0:
            return None
        f.current_saved = round(f.current_saved + diff, 2)
        f.challenge_ticks = int(getattr(f, "challenge_ticks", 0)) + 1
        return f, diff

    # ── Homestead decor + palettes ───────────────────────────────────────
    def buy_decor(self, decor_id: str) -> tuple:
        g = self.state.game
        d = HOMESTEAD_DECOR_BY_ID.get(decor_id)
        if not d:
            return False, "Unknown decor."
        if decor_id in g.homestead_decor:
            return False, "Already on the Homestead."
        _, name, ct, cost, *_r = d
        if ct == "gold":
            if g.total_score < cost:
                return False, f"Need {cost} Gold (have {g.total_score})."
            g.total_score -= cost
            g.level = self.level_from_score(g.total_score)
        else:
            if g.gems < cost:
                return False, f"Need {cost} Gems (have {g.gems})."
            g.gems -= cost
        g.homestead_decor.append(decor_id)
        return True, f"{name} placed."

    def set_palette(self, pid: str) -> tuple:
        g = self.state.game
        if pid != "classic" and pid not in g.homestead_palettes:
            return False, "That palette isn't unlocked yet."
        if pid not in HOMESTEAD_PALETTES:
            return False, "Unknown palette."
        g.homestead_palette = pid
        return True, f"{HOMESTEAD_PALETTES[pid]['name']} palette on."

    def unlock_season_palette(self) -> Optional[str]:
        """Called when the top season tier is claimed: unlock this season's palette."""
        g = self.state.game
        pid = season_for_month(date.today().month)
        if pid in g.homestead_palettes:
            return None
        g.homestead_palettes.append(pid)
        return pid

    # ── Live events, XP window, daily deal ───────────────────────────────
    def current_event(self, today: Optional[date] = None) -> dict:
        today = today or date.today()
        name, blurb = MONTHLY_EVENTS.get(today.month, ("This month", ""))
        season = season_for_month(today.month)
        set_name, cards = EVENT_CARD_SETS[season]
        owned = set(self.state.game.cards_owned)
        have = sum(1 for c in cards if c[0] in owned)
        return {"name": name, "blurb": blurb, "season": season, "set_name": set_name, "set_have": have, "set_total": len(cards),
                "set_claimed": season in self.state.game.event_sets_claimed, "xp_window": self.xp_window_active(today),
                "deal": self.featured_perk(today)}

    def xp_window_active(self, today: Optional[date] = None) -> bool:
        """Double Season XP on the Saturday/Sunday of a week in which a pay is expected."""
        today = today or date.today()
        if today.weekday() < 5 or not self.state.incomes:
            return False
        last = max(i.received_on for i in self.state.incomes)
        cycle = BudgetEngine.PAY_CYCLE_DAYS.get(self.state.pay_frequency, 14)
        expected = last + timedelta(days=cycle)
        while expected < today - timedelta(days=cycle):
            expected += timedelta(days=cycle)
        monday = today - timedelta(days=today.weekday())
        return monday <= expected <= monday + timedelta(days=6)

    def featured_perk(self, today: Optional[date] = None) -> tuple:
        today = today or date.today()
        perk = PERK_SHOP_ITEMS[today.toordinal() % len(PERK_SHOP_ITEMS)]
        return perk[0], max(1, int(round(perk[3] * 0.7)))

    def featured_cost(self, perk_id: str, gem_cost: int) -> int:
        pid, disc = self.featured_perk()
        return disc if pid == perk_id else gem_cost

    def _track_weekly_xp(self, gain: int):
        g = self.state.game
        week = date.today().strftime("%G-W%V")
        if g.weekly_xp_week != week:
            g.weekly_xp_week = week
            g.weekly_xp = 0
        g.weekly_xp += int(gain)

    def check_event_set(self) -> str:
        """All four of this season's cards owned → +8 Gems once. Returns the set name or ''."""
        g = self.state.game
        season = season_for_month(date.today().month)
        if season in g.event_sets_claimed:
            return ""
        set_name, cards = EVENT_CARD_SETS[season]
        if all(c[0] in g.cards_owned for c in cards):
            g.event_sets_claimed.append(season)
            g.gems += 8
            g.lifetime_gems_earned += 8
            ach = f"{set_name} Collector"
            if ach not in g.achievements:
                g.achievements.append(ach)
            return set_name
        return ""

    # ── Gerald's letters ─────────────────────────────────────────────────
    def letters_available(self) -> int:
        return min(len(GERALD_LETTERS), int(self.state.game.pulse_days_total))

    def letter_waiting(self) -> bool:
        return self.letters_available() > self.state.game.letters_read

    def read_next_letter(self) -> Optional[dict]:
        g = self.state.game
        if not self.letter_waiting():
            return None
        idx = g.letters_read
        g.letters_read += 1
        letter = dict(GERALD_LETTERS[idx])
        letter["index"] = idx
        return letter

    def choose_letter_gift(self, idx: int, item_id: str) -> tuple:
        g = self.state.game
        if idx < 0 or idx >= len(GERALD_LETTERS):
            return False, "No such letter."
        choices = GERALD_LETTERS[idx].get("choice") or []
        if not any(iid == item_id for _l, iid in choices):
            return False, "That wasn't on offer."
        if str(idx) in g.letter_choices:
            return False, "You already chose from this letter."
        g.letter_choices[str(idx)] = item_id
        if item_id not in g.character_items_owned:
            g.character_items_owned.append(item_id)
        return True, f"{AVATAR_ITEMS.get(item_id, {}).get('name', item_id)} is yours."

    # ── Weekly race against the villagers (clearly fictional rivals) ────
    RIVALS = [("Marta the Miller", 0.95, "🌾"), ("Old Tobias", 0.55, "🪵"), ("Pip", 1.15, "🍯"), ("Hazel Thorne", 1.35, "📘")]
    LEAGUES = ["bronze", "silver", "gold"]
    LEAGUE_MULT = {"bronze": 0.7, "silver": 1.0, "gold": 1.3}

    def _rival_baseline(self) -> float:
        g = self.state.game
        prev = float(g.rival_prev_user_xp or 0)
        return max(80.0, min(900.0, prev if prev > 0 else 120.0))

    def rival_standings(self, today: Optional[date] = None, full_week: bool = False, week: Optional[str] = None) -> List[dict]:
        """Standings for the current (or a given) week. NPC XP follows a pace curve
        scaled to the user's previous week, with a per-week jitter so it stays close."""
        import random
        today = today or date.today()
        g = self.state.game
        week = week or today.strftime("%G-W%V")
        f = 1.0 if full_week else (today.weekday() + 1) / 7.0
        base = self._rival_baseline() * self.LEAGUE_MULT.get(g.rival_league, 0.7)
        rows = [{"name": "You", "emoji": "★", "xp": int(g.weekly_xp), "you": True}]
        for i, (name, pace, emoji) in enumerate(self.RIVALS):
            rnd = random.Random(f"{week}:{i}:{g.rival_seed}")
            jitter = 0.85 + rnd.random() * 0.3
            rows.append({"name": name, "emoji": emoji, "xp": int(base * pace * jitter * f), "you": False})
        rows.sort(key=lambda r: (-r["xp"], r["you"]))
        for i, r in enumerate(rows):
            r["place"] = i + 1
        return rows

    def ensure_rival_week(self, today: Optional[date] = None) -> Optional[dict]:
        """Settle last week's race when a new ISO week starts. Returns the result once."""
        g = self.state.game
        today = today or date.today()
        week = today.strftime("%G-W%V")
        if not g.rival_week:
            g.rival_week = week
            g.rival_seed = g.rival_seed or int(datetime.now().timestamp()) % 100000
            return None
        if g.rival_week == week:
            return None
        # settle the week that just ended using the XP accumulated under it
        prev_week = g.rival_week
        user_xp = int(g.weekly_xp) if g.weekly_xp_week == prev_week else 0
        rows = self.rival_standings(today, full_week=True, week=prev_week)
        for r in rows:
            if r["you"]:
                r["xp"] = user_xp
        rows.sort(key=lambda r: (-r["xp"], r["you"]))
        place = next(i + 1 for i, r in enumerate(rows) if r["you"])
        league = g.rival_league
        li = self.LEAGUES.index(league) if league in self.LEAGUES else 0
        reward = ""
        if place == 1:
            g.gems += 4; g.lifetime_gems_earned += 4; reward = "+4 Gems"
            li = min(2, li + 1)
        elif place == 2:
            g.gems += 2; g.lifetime_gems_earned += 2; reward = "+2 Gems"
            li = min(2, li + 1)
        elif place == 3:
            g.total_score += 40; g.level = self.level_from_score(g.total_score); reward = "+40 Gold"
        else:
            li = max(0, li - 1)
        new_league = self.LEAGUES[li]
        moved = "promoted to " + new_league if new_league != league and li > self.LEAGUES.index(league) else ("relegated to " + new_league if new_league != league else "stayed in " + league)
        g.rival_league = new_league
        g.rival_prev_user_xp = user_xp
        g.rival_week = week
        g.rival_last = {"week": prev_week, "place": place, "xp": user_xp, "reward": reward, "moved": moved, "league": new_league}
        if g.weekly_xp_week != week:
            g.weekly_xp = 0
            g.weekly_xp_week = week
        return dict(g.rival_last)

    # ── Share cards (month / year) ───────────────────────────────────────
    def share_card_data(self, year: int, month: Optional[int], app) -> dict:
        """Stats for a poster: month (year, month) or year-to-date (month=None)."""
        g = self.state.game
        today = date.today()
        if month:
            d = app._monthly_report_data(year, month)
            label = d["label"]; start, end = d["start"], d["end"]
            income, spent, net, rate, top = d["income"], d["spent"], d["net"], d["savings_rate"], d["top"]
            prev_line = (f"Spending {abs(d['spend_delta']):.0f}% {'up' if d['spend_delta'] > 0 else 'down'} on {d['prev_label']}" if d.get("prev_spent") else "")
        else:
            start, end = date(year, 1, 1), (today if year == today.year else date(year, 12, 31))
            cur = app._current_month_review_data(bounds=(start, end))
            label = f"{year} so far" if year == today.year else str(year)
            income, spent, rate = cur["income_total"], cur["outgoing_total"], cur["savings_rate"]
            net = income - spent
            cats = outgoing_category_totals(self.state.transactions, start, end)
            top = sorted(cats.items(), key=lambda kv: -kv[1])[:5]
            prev_line = ""
        biggest = max((t for t in self.state.transactions if t.money_out > 0 and start <= t.tx_date <= end and t.matched_type not in ("transfer", "ignore")),
                      key=lambda t: t.money_out, default=None)
        no_spend = sum(1 for d_ in g.no_spend_dates if start <= date.fromisoformat(d_) <= end) if g.no_spend_dates else 0
        return {"label": label, "income": income, "spent": spent, "net": net, "rate": rate, "top": top, "prev_line": prev_line,
                "biggest": (extract_merchant_name(biggest.description), biggest.money_out, biggest.tx_date) if biggest else None,
                "no_spend": no_spend, "pulse_best": g.pulse_best, "pay_streak_best": g.best_streak,
                "level": g.level, "rank": app.rank_name_for_level(g.level, g.prestige_level), "tier": g.homestead_tier,
                "cards": len(set(g.cards_owned)), "pacts": g.pacts_won, "reserved": self._reserved_total()}

    def check_homestead_tiers(self, tier: int) -> list:
        """Record the Homestead tier and award any companion not yet claimed.
        Returns the list of newly awarded item ids."""
        g = self.state.game
        g.homestead_tier = max(0, min(5, int(tier)))
        awarded = []
        for n in range(1, g.homestead_tier + 1):
            if n in g.homestead_claimed_tiers:
                continue
            iid = self.HOMESTEAD_COMPANIONS.get(n)
            g.homestead_claimed_tiers.append(n)
            if iid and iid not in g.character_items_owned:
                g.character_items_owned.append(iid)
                awarded.append(iid)
            if n == 5 and "background_homestead" not in g.character_items_owned:
                g.character_items_owned.append("background_homestead")
                awarded.append("background_homestead")
        return awarded

    def buy_avatar_item(self, item_id: str) -> tuple:
        """Buy an avatar cosmetic. Returns (success, message)."""
        g = self.state.game
        item = AVATAR_ITEMS.get(item_id)
        if not item:
            return False, "Unknown item."
        if item_id in g.character_items_owned:
            return False, "Already owned."
        req = item.get("unlock_req")
        if req:
            t, v = req["type"], req["value"]
            if t == "level" and g.level < v:
                return False, f"Requires Level {v}."
            if t == "achievement" and v not in g.achievements:
                return False, f"Requires achievement: {v}."
            if t == "streak" and g.best_streak < v:
                return False, f"Requires best streak of {v}."
            if t == "prestige" and g.prestige_level < v:
                return False, f"Requires Prestige {v}."
            if t == "card_set":
                # Card set items can't be bought — auto-awarded on set completion
                return False, f"Complete the '{v.replace('set_', '').title()}' card set to unlock."
            if t == "homestead":
                return False, f"Reach Homestead Tier {v} — it's awarded automatically."
        ct, cost = item["cost_type"], item["cost"]
        if ct == "gold":
            if g.total_score < cost:
                return False, f"Need {cost} Gold (have {g.total_score})."
            g.total_score -= cost
            g.level = self.level_from_score(g.total_score)
        elif ct == "gems":
            if g.gems < cost:
                return False, f"Need {cost} Gems (have {g.gems})."
            g.gems -= cost
        g.character_items_owned.append(item_id)
        return True, f"Unlocked: {item['name']}!"

    def equip_avatar_item(self, item_id: str) -> tuple:
        """Equip an owned avatar item. Returns (success, message)."""
        g = self.state.game
        if item_id not in g.character_items_owned:
            return False, "Item not owned."
        item = AVATAR_ITEMS.get(item_id)
        if not item:
            return False, "Unknown item."
        g.character_equipped[item["slot"]] = item_id
        return True, f"Equipped {item['name']}."

    def unequip_avatar_slot(self, slot: str) -> tuple:
        """Clear an equipment slot. Returns (success, message)."""
        g = self.state.game
        if slot not in g.character_equipped or not g.character_equipped.get(slot):
            return False, "Slot is already empty."
        g.character_equipped[slot] = ""
        return True, f"Unequipped {slot}."

    def open_pack(self, pack_type_id: str, free: bool = False) -> dict:
        """Purchase and open a card pack. Returns {success, message, cards, cost_type, cost}."""
        import random
        g = self.state.game
        pack_data = next((p for p in PACK_TYPES if p[0] == pack_type_id), None)
        if not pack_data:
            return {"success": False, "message": "Unknown pack type.", "cards": []}
        _, name, _, cost_type, cost, card_count, rarity_weights, _ = pack_data
        # Check affordability
        if free:
            pass
        elif cost_type == "gold":
            if g.total_score < cost:
                return {"success": False, "message": f"Need {cost} Gold (you have {g.total_score}).", "cards": []}
            g.total_score -= cost
            # Recalc level
            g.level = self.level_from_score(g.total_score)
        else:  # gems
            if g.gems < cost:
                return {"success": False, "message": f"Need {cost} Gems (you have {g.gems}).", "cards": []}
            g.gems -= cost
        # Draw cards
        rarities = list(rarity_weights.keys())
        weights = list(rarity_weights.values())
        pool_by_rarity: dict = {}
        _season_now = season_for_month(date.today().month)
        for cid, cname, crarity, *_ in CARD_POOL:
            if cid in EXCLUSIVE_CARD_IDS:
                continue
            if cid in SEASONAL_CARD_SEASON and SEASONAL_CARD_SEASON[cid] != _season_now:
                continue
            pool_by_rarity.setdefault(crarity, []).append((cid, cname, crarity) + tuple(_))
        drawn = []
        # Pity timer: the 5th pack without an Epic+ is guaranteed one.
        pity_used = g.packs_since_epic >= 4
        for n_card in range(card_count):
            chosen_rarity = random.choices(rarities, weights=weights, k=1)[0]
            if pity_used and n_card == 0:
                chosen_rarity = "legendary" if random.random() < 0.2 else "epic"
            pool = pool_by_rarity.get(chosen_rarity, [])
            if not pool:
                # fallback to common
                pool = pool_by_rarity.get("common", list(CARD_POOL))
            card = random.choice(pool)
            # Duplicate protection: a set that is ≥80% complete rerolls a duplicate
            # from it once, toward one of its missing cards of the same rarity.
            if card[0] in g.cards_owned:
                for _sid, _sn, _sd, _cids, _rw in CARD_SETS:
                    if card[0] in _cids:
                        _owned = sum(1 for c_ in _cids if c_ in g.cards_owned)
                        if _owned >= 0.8 * len(_cids):
                            _missing = [c_ for c_ in pool if c_[0] in _cids and c_[0] not in g.cards_owned]
                            if _missing:
                                card = random.choice(_missing)
                        break
            drawn.append(card)
            g.cards_owned.append(card[0])
            # Apply bonus if card has one and is first copy
            if g.cards_owned.count(card[0]) == 1 and card[5]:
                bonus = card[5]
                if "+Gold" in bonus or "Gold bonus" in bonus:
                    try:
                        amt = int("".join(c for c in bonus if c.isdigit()))
                        g.total_score += amt
                    except Exception:
                        pass
                elif "+Gems" in bonus or "+1 Gem" in bonus:
                    try:
                        amt = int("".join(c for c in bonus if c.isdigit()))
                        g.gems += amt
                        g.lifetime_gems_earned += amt
                    except Exception:
                        pass
                elif "+Season XP" in bonus:
                    try:
                        amt = int("".join(c for c in bonus if c.isdigit()))
                        g.season_xp += amt
                    except Exception:
                        pass
        g.packs_opened += 1
        if any(c[2] in ("epic", "legendary") for c in drawn):
            g.packs_since_epic = 0
        else:
            g.packs_since_epic += 1
        # Achievement: first pack
        if g.packs_opened == 1 and "Pack Hunter" not in g.achievements:
            g.achievements.append("Pack Hunter")
        # Achievement: 5 packs
        if g.packs_opened >= 5 and "Fortune's Favourite" not in g.achievements:
            g.achievements.append("Fortune's Favourite")
        # Check card set completions — auto-claim rewards
        set_completions = self.check_card_set_completions()
        event_set = self.check_event_set()
        return {"success": True, "event_set": event_set, "message": f"Opened {name}!", "cards": drawn,
                "cost_type": cost_type, "cost": cost,
                "set_completions": set_completions, "pity_used": pity_used}

    def recycle_duplicate(self, card_id: str) -> dict:
        """Recycle one duplicate copy of a card for 1 Gem."""
        g = self.state.game
        if g.cards_owned.count(card_id) < 2:
            return {"success": False, "message": "You need at least 2 copies to recycle a duplicate."}
        g.cards_owned.remove(card_id)
        g.gems += 1
        g.lifetime_gems_earned += 1
        card = CARD_BY_ID.get(card_id)
        name = card[1] if card else card_id
        return {"success": True, "message": f"Recycled duplicate '{name}' for +1 Gem."}

    def prestige(self):
        """Reset score to 0, grant prestige level and permanent score multiplier."""
        g = self.state.game
        g.prestige_level += 1
        g.score_multiplier = round(1.0 + g.prestige_level * 0.10 + self._perk_multiplier_bonus(), 2)
        g.total_score = 0
        g.level = 1
        ach = f"Prestige {g.prestige_level}"
        if ach not in g.achievements:
            g.achievements.append(ach)

    def _check_achievements(self, is_good_pay: bool):
        """Check and award all achievement chains."""
        g = self.state.game
        for milestone, title in [(3, "Streak Starter"), (7, "Streak Builder"), (14, "Streak Master"), (30, "Streak Legend")]:
            if g.streak_pays >= milestone and title not in g.achievements:
                g.achievements.append(title)
        for threshold, title in [(500, "500 Score Club"), (1000, "1,000 Score Club"), (2500, "2,500 Score Club")]:
            if g.total_score >= threshold and title not in g.achievements:
                g.achievements.append(title)
        for count, title in [(1, "First Pay Processed"), (10, "10 Pays Processed"), (52, "Veteran Budgeter")]:
            if g.total_pays_processed >= count and title not in g.achievements:
                g.achievements.append(title)
        for gems_threshold, title in [(10, "Gem Collector"), (50, "Gem Hoarder")]:
            if g.lifetime_gems_earned >= gems_threshold and title not in g.achievements:
                g.achievements.append(title)

    def _update_income_baseline(self, pay_amount: float):
        """Exponential moving average of income. Called from UI after each pay."""
        b = self.state.income_baseline
        if b <= 0:
            self.state.income_baseline = pay_amount
        else:
            # 80% weight on existing baseline, 20% on new — slow drift, resistant to one-off spikes
            self.state.income_baseline = round(0.80 * b + 0.20 * pay_amount, 2)

    def score_pay(self, pay_amount: float, allocation: dict) -> dict:
        g = self.state.game
        today_str = date.today().isoformat()

        # ── Integrity: same-day duplicate limit ───────────────────────────────
        # After the first 2 pays (learning phase), cap any second pay on the same calendar day
        # at 10 points. This prevents rapid-entry farming while allowing legitimate same-day use.
        already_scored_today = (g.last_pay_scored_date == today_str and g.total_pays_processed >= 2)

        reserved = allocation["bill_total"] + allocation["fund_total"] + allocation["goal_total"] + allocation["invest_total"]
        ratio = 0 if pay_amount <= 0 else reserved / pay_amount
        base_points = min(int(ratio * 100), 40)
        breakdown = [f"Saved/reserved ratio bonus: +{base_points}"]
        if ratio >= 0.10:
            base_points += 10; breakdown.append("Reserved at least 10%: +10")
        if ratio >= 0.25:
            base_points += 15; breakdown.append("Reserved at least 25%: +15")
        if ratio >= 0.40:
            base_points += 20; breakdown.append("Reserved at least 40%: +20")
        penalty = len(allocation["warnings"]) * 8
        if penalty:
            base_points -= penalty; breakdown.append(f"Warnings penalty: -{penalty}")
        base_points = max(base_points, 0)

        # ── Integrity: cap same-day repeat scoring ────────────────────────────
        if already_scored_today:
            base_points = min(base_points, 10)
            breakdown.append("Integrity cap: second pay scored today — points limited to 10 (one full-score pay per day).")

        # ── Integrity: flag abnormally large pays vs established baseline ─────
        baseline = self.state.income_baseline
        if baseline > 0 and pay_amount > baseline * 4.0:
            breakdown.append(
                f"Note: This pay (${pay_amount:,.0f}) is significantly larger than your typical "
                f"pay of ~${baseline:,.0f}. Scoring is ratio-based so Gold earned is proportional — "
                f"but the streak count depends on consistent real behaviour over time."
            )

        # Double-mix buff (consumed on use)
        mix_bonus, mix_lines = self._expense_mix_match_bonus()
        if "double_mix" in g.active_buffs:
            mix_bonus *= 2
            g.active_buffs.remove("double_mix")
            breakdown.append("Double Mix buff active! Mix points doubled.")
        base_points += mix_bonus
        breakdown.extend(mix_lines)

        # Score multiplier from prestige + perks
        points = base_points
        if g.score_multiplier > 1.0:
            points = int(round(base_points * g.score_multiplier))
            breakdown.append(f"Score multiplier x{g.score_multiplier:.1f}: {base_points} -> {points}")

        # Streak: threshold uses pre-multiplier points to stay meaningful
        is_good_pay = base_points >= 35
        if not is_good_pay and g.streak_shields > 0:
            g.streak_shields -= 1
            is_good_pay = True
            breakdown.append(f"Streak Shield activated! Shields left: {g.streak_shields}")

        g.total_pays_processed += 1
        g.last_pay_scored_date = today_str
        g.last_score_gain = points
        g.total_score += points
        g.streak_pays = g.streak_pays + 1 if is_good_pay else 0
        g.best_streak = max(g.best_streak, g.streak_pays)
        self.update_record("pay_streak", g.best_streak)
        g.streak_history.append(is_good_pay)
        if len(g.streak_history) > 30:
            g.streak_history = g.streak_history[-30:]  # keep last 30

        # Gems from streaks
        gems_earned = 0
        if g.streak_pays >= 3:
            gems_earned += 1
            breakdown.append(f"+1 Gem (streak of {g.streak_pays})")
        if g.streak_pays in (5, 10, 15, 20, 25, 30):
            gems_earned += 2
            breakdown.append(f"+2 Gems (streak milestone: {g.streak_pays}!)")
        if "gem_magnet" in g.perks_unlocked and g.streak_pays >= 1:
            gems_earned += 1
            breakdown.append("+1 Gem (Gem Magnet perk)")
        if gems_earned:
            g.gems += gems_earned
            g.lifetime_gems_earned += gems_earned

        # Season XP
        season_xp_gain = 20 + (10 if is_good_pay else 0)
        self.add_season_xp(season_xp_gain)
        if is_good_pay:
            breakdown.append("+10 bonus Season XP (good pay)")

        prev = g.level
        g.level = self.level_from_score(g.total_score)
        self._check_achievements(is_good_pay)

        # Daily challenge checks
        completed_challenges = self.complete_challenge("pay")
        if ratio >= 0.40:
            completed_challenges += self.complete_challenge("pay_40")
        if is_good_pay:
            completed_challenges += self.complete_challenge("pay_35")
        if g.streak_pays >= 1:
            completed_challenges += self.complete_challenge("streak")

        return {
            "points": points,
            "level_up": g.level > prev,
            "breakdown": breakdown,
            "gems_earned": gems_earned,
            "completed_challenges": completed_challenges,
        }


class PDFTransactionImporter:
    DATE_RE = re.compile(r"^(\d{1,2}\s+[A-Za-z]{3}\s+\d{4})\s+(.*)$")
    MONEY_RE = re.compile(r"-?\$?[\d,]+\.\d{2}")

    def read_pdf_text(self, path: Path) -> str:
        """Extract text from a PDF, trying pypdf first then pdfminer.six.

        Many bank PDFs have malformed cross-reference tables that pypdf
        refuses even in lenient mode. pdfminer.six is slower but far more
        tolerant of broken structure, so it's the fallback of last resort."""
        pypdf_err = None
        try:
            from pypdf import PdfReader  # type: ignore
        except ImportError:
            pypdf_err = "not installed"
        else:
            for strict in (False, True):
                try:
                    reader = PdfReader(str(path), strict=strict)
                    if getattr(reader, "is_encrypted", False):
                        try:
                            reader.decrypt("")
                        except Exception:
                            raise RuntimeError(
                                "This PDF is password-protected. Remove the "
                                "password first (re-save without encryption "
                                "from your bank's site or a PDF tool) and "
                                "try again."
                            )
                    return "\n".join(page.extract_text() or "" for page in reader.pages)
                except RuntimeError:
                    raise  # password message — don't fall through
                except Exception as exc:
                    pypdf_err = exc

        # Fallback — pdfminer.six. More tolerant of broken xref/trailer.
        try:
            from pdfminer.high_level import extract_pages  # type: ignore
            from pdfminer.layout import LAParams, LTTextContainer, LTTextLine  # type: ignore
        except ImportError:
            if getattr(sys, "frozen", False):
                raise RuntimeError(
                    "Couldn't read this PDF with pypdf"
                    + (f" ({pypdf_err})" if pypdf_err else "")
                    + ".\n\nThe fallback parser isn't bundled in this build of the "
                    "app. Update to the latest version and try again."
                )
            raise RuntimeError(
                "Couldn't read this PDF with pypdf"
                + (f" ({pypdf_err})" if pypdf_err else "")
                + ".\n\nInstall the fallback parser:\n"
                "  pip install pdfminer.six\n\n"
                "Then try again."
            )
        try:
            text = self._pdfminer_rows(path, extract_pages, LAParams, LTTextContainer, LTTextLine)
            if text.strip():
                return text
            raise RuntimeError("empty text")
        except Exception as exc:
            raise RuntimeError(
                "Couldn't read this PDF with either pypdf or pdfminer.\n\n"
                f"pypdf: {pypdf_err}\n"
                f"pdfminer: {exc}\n\n"
                "This usually means the PDF is scanned (image-only — no "
                "text layer), heavily malformed, or uses an unusual "
                "format.\n\n"
                "Try: re-download the statement from your bank, or open it "
                "in a PDF viewer and use 'Print to PDF' (Microsoft Print "
                "to PDF works well) to produce a clean copy."
            )

    @staticmethod
    def _pdfminer_rows(path: Path, extract_pages, LAParams, LTTextContainer, LTTextLine,
                       y_tol: float = 3.0) -> str:
        """Rebuild statement rows from text coordinates.

        pdfminer's plain extract_text emits bank tables column by column (all
        the dates, then all the descriptions, then all the amounts), which the
        line parser can't use. Grouping text lines by their vertical position
        and sorting each group left-to-right gives back one line per row:
        "12 Sep 2026  WOOLWORTHS 1234  -$45.00  $1,234.56"."""
        out_lines: List[str] = []
        for page in extract_pages(str(path), laparams=LAParams(boxes_flow=None)):
            items = []
            for el in page:
                if isinstance(el, LTTextContainer):
                    for ln in el:
                        if isinstance(ln, LTTextLine):
                            s = ln.get_text().strip()
                            if s:
                                items.append((ln.y1, ln.x0, s))
            items.sort(key=lambda t: (-t[0], t[1]))
            row: List[str] = []
            row_y = None
            for y, _x, s in items:
                if row_y is None or abs(y - row_y) > y_tol:
                    if row:
                        out_lines.append(" ".join(row))
                    row, row_y = [s], y
                else:
                    row.append(s)
            if row:
                out_lines.append(" ".join(row))
        return "\n".join(out_lines)

    # ── CSV / OFX statements ─────────────────────────────────────────────
    # Every Australian bank exports CSV and OFX/QFX from internet banking,
    # and both parse far more reliably than PDF. Records come out identical
    # to the PDF path (same fingerprint), so cross-format dedup just works.
    _CSV_DATE_FORMATS = ("%d/%m/%Y", "%d/%m/%y", "%Y-%m-%d", "%d %b %Y", "%d-%m-%Y", "%d %B %Y",
                         "%d-%b-%Y", "%d-%b-%y", "%Y/%m/%d", "%Y%m%d", "%d.%m.%Y", "%m/%d/%Y")

    def extract_any(self, path: Path) -> tuple[list[TransactionRecord], list[str]]:
        """Dispatch on file type: .pdf, .csv, .ofx/.qfx."""
        ext = path.suffix.lower()
        if ext == ".pdf":
            return self.extract_transactions(path)
        if ext in (".csv", ".txt"):
            return self.extract_csv(path)
        if ext in (".ofx", ".qfx"):
            return self.extract_ofx(path)
        raise RuntimeError(f"Unsupported file type '{ext}'. Use a PDF, CSV or OFX/QFX export from your bank.")

    @classmethod
    def _parse_csv_date(cls, raw: str) -> Optional[date]:
        s = (raw or "").strip().strip('"').strip()
        if not s:
            return None
        if re.match(r"^\d{4}-\d{2}-\d{2}", s):
            s = s[:10]
        for fmt in cls._CSV_DATE_FORMATS:
            try:
                return datetime.strptime(s, fmt).date()
            except ValueError:
                continue
        toks = s.split()
        if len(toks) >= 3:
            try:
                return datetime.strptime(" ".join(toks[:3]), "%d %b %Y").date()
            except ValueError:
                pass
        return None

    @staticmethod
    def _parse_csv_money(raw: str) -> Optional[float]:
        s = (raw or "").strip().strip('"').replace("$", "").replace(",", "").replace(" ", "")
        if not s or s in ("-", "--", "—"):
            return None
        neg = False
        if s.startswith("(") and s.endswith(")"):
            neg, s = True, s[1:-1]
        up = s.upper()
        if up.endswith("CR"):
            s = s[:-2]
        elif up.endswith("DR"):
            neg, s = True, s[:-2]
        if s.startswith("+"):
            s = s[1:]
        try:
            v = float(s)
        except ValueError:
            return None
        return -abs(v) if neg else v

    def extract_csv(self, path: Path) -> tuple[list[TransactionRecord], list[str]]:
        raw = path.read_text(encoding="utf-8-sig", errors="replace")
        lines = [ln for ln in raw.splitlines() if ln.strip()]
        if not lines:
            return [], ["CSV is empty"]
        try:
            dialect = csv.Sniffer().sniff("\n".join(lines[:10]), delimiters=",;\t|")
        except csv.Error:
            dialect = csv.excel
        rows = [r for r in csv.reader(lines, dialect) if any(c.strip() for c in r)]
        if not rows:
            return [], ["CSV has no data rows"]
        qa: List[str] = []
        header = None
        first = [c.strip().lower() for c in rows[0]]
        header_words = ("date", "desc", "amount", "debit", "credit", "balance", "narrat", "detail", "memo", "payee", "transaction")
        if not any(self._parse_csv_date(c) for c in rows[0]) and any(any(k in c for k in header_words) for c in first):
            header, rows = first, rows[1:]

        col: Dict[str, Optional[int]] = {}
        if header:
            def find(*keys):
                for i, name in enumerate(header):
                    if any(re.search(r"\b" + k + r"\b", name) for k in keys):
                        return i
                return None
            col["date"] = find("date", "posted", "when", "time", "settled", "created")
            if col["date"] is None:
                # Header had no date-ish name — take the first column that parses as a date
                for i in range(len(header)):
                    if sum(1 for r in rows[:10] if i < len(r) and self._parse_csv_date(r[i])) >= max(1, min(len(rows), 10) // 2):
                        col["date"] = i
                        break
            col["desc"] = find("description", "narrative", "details", "memo", "payee", "particulars", "transaction details", "transaction")
            col["debit"] = find("debit", "withdrawal", "withdrawals", "money out", "out")
            col["credit"] = find("credit", "deposit", "deposits", "money in", "in")
            # A generic amount column must not be the debit/credit column
            # ("Debit Amount" also contains the word "amount").
            col["amount"] = None
            for i, name in enumerate(header):
                if i in (col["debit"], col["credit"]):
                    continue
                if re.search(r"\bamount\b", name) or re.search(r"\bvalue\b", name):
                    col["amount"] = i
                    break
            col["balance"] = find("balance")
            if col["desc"] == col["date"]:
                col["desc"] = None
        else:
            sample = rows[:25]
            ncols = max(len(r) for r in sample)

            def _is_date(v): return self._parse_csv_date(v) is not None
            def _is_num(v): return self._parse_csv_money(v) is not None and not _is_date(v)
            date_scores = [sum(1 for r in sample if i < len(r) and _is_date(r[i])) for i in range(ncols)]
            num_scores = [sum(1 for r in sample if i < len(r) and _is_num(r[i])) for i in range(ncols)]
            text_len = [sum(len(r[i]) for r in sample if i < len(r) and not _is_num(r[i]) and not _is_date(r[i])) for i in range(ncols)]
            col["date"] = max(range(ncols), key=lambda i: date_scores[i]) if max(date_scores) else None
            col["desc"] = max(range(ncols), key=lambda i: text_len[i]) if max(text_len) else None
            nums = [i for i in range(ncols) if num_scores[i] >= len(sample) * 0.6 and i not in (col["date"], col["desc"])]
            col["amount"] = nums[0] if nums else None
            col["balance"] = nums[-1] if len(nums) >= 2 else None
            col["debit"] = col["credit"] = None
        if col.get("date") is None or col.get("desc") is None or all(col.get(k) is None for k in ("amount", "debit", "credit")):
            return [], [f"Couldn't work out the CSV columns (header: {header or 'none'}). "
                        "Expected date, description and amount (or debit/credit) columns."]

        out: List[TransactionRecord] = []
        seen = set()
        for r in rows:
            def cell(k):
                i = col.get(k)
                return r[i] if i is not None and i < len(r) else ""
            d = self._parse_csv_date(cell("date"))
            if d is None:
                qa.append(f"Skipped row, bad date: {' | '.join(r[:3])[:60]}")
                continue
            desc = self.normalize_desc(cell("desc")) or "Unknown Transaction"
            amount, direction = None, "out"
            if col.get("debit") is not None or col.get("credit") is not None:
                dv = self._parse_csv_money(cell("debit"))
                cv = self._parse_csv_money(cell("credit"))
                if dv:
                    amount, direction = abs(dv), "out"
                elif cv:
                    amount, direction = abs(cv), "in"
            if amount is None and col.get("amount") is not None:
                v = self._parse_csv_money(cell("amount"))
                if v is not None:
                    amount, direction = abs(v), ("out" if v < 0 else "in")
            if not amount:
                qa.append(f"Skipped row, no amount: {desc[:40]}")
                continue
            bal = self._parse_csv_money(cell("balance")) if col.get("balance") is not None else None
            fp = self.fingerprint(d, desc, amount, direction)
            if (fp, bal) in seen:
                continue
            seen.add((fp, bal))
            out.append(TransactionRecord(d, desc, money_in=amount if direction == "in" else 0.0,
                                         money_out=amount if direction == "out" else 0.0, balance=bal,
                                         source_file=path.name, fingerprint=fp))
        qa.insert(0, f"Rows detected: {len(rows)}")
        qa.insert(1, f"Transactions parsed: {len(out)}")
        if header:
            qa.insert(2, "Columns: " + ", ".join(f"{k}={header[i]}" for k, i in col.items() if i is not None))
        return out, qa

    def extract_ofx(self, path: Path) -> tuple[list[TransactionRecord], list[str]]:
        raw = path.read_text(encoding="utf-8", errors="replace")
        chunks = re.split(r"<STMTTRN>", raw, flags=re.I)[1:]
        qa: List[str] = []
        out: List[TransactionRecord] = []
        seen = set()
        for ch in chunks:
            ch = re.split(r"</STMTTRN>", ch, flags=re.I)[0]

            def tag(t):
                m = re.search(rf"<{t}>([^<\r\n]*)", ch, re.I)
                return m.group(1).strip() if m else ""
            dt = tag("DTPOSTED")[:8]
            try:
                d = datetime.strptime(dt, "%Y%m%d").date()
            except ValueError:
                qa.append(f"Skipped transaction, bad date: {dt!r}")
                continue
            try:
                amt = float(tag("TRNAMT").replace(",", ""))
            except ValueError:
                qa.append("Skipped transaction, bad amount")
                continue
            if amt == 0:
                continue
            name, memo = tag("NAME"), tag("MEMO")
            desc_raw = name + ((" " + memo) if memo and memo.lower() not in name.lower() else "")
            desc = self.normalize_desc(desc_raw) or "Unknown Transaction"
            direction = "out" if amt < 0 else "in"
            amount = abs(amt)
            fp = self.fingerprint(d, desc, amount, direction)
            key = (fp, tag("FITID"))
            if key in seen:
                continue
            seen.add(key)
            out.append(TransactionRecord(d, desc, money_in=amount if direction == "in" else 0.0,
                                         money_out=amount if direction == "out" else 0.0, balance=None,
                                         source_file=path.name, fingerprint=fp))
        qa.insert(0, f"Rows detected: {len(chunks)}")
        qa.insert(1, f"Transactions parsed: {len(out)}")
        if not chunks:
            qa.append("No <STMTTRN> blocks found — is this an OFX/QFX export?")
        return out, qa

    def parse_amount(self, text: str) -> float:
        return float(text.replace("$", "").replace(",", "").strip())

    def normalize_desc(self, desc: str) -> str:
        return normalize_desc_text(desc)

    def fingerprint(self, tx_date: date, desc: str, amount: float, direction: str) -> str:
        return f"{tx_date.isoformat()}|{direction}|{amount:.2f}|{self.normalize_desc(desc).lower()}"

    def extract_transactions(self, path: Path) -> tuple[list[TransactionRecord], list[str]]:
        text = self.read_pdf_text(path)
        lines = [ln.rstrip() for ln in text.splitlines() if ln.strip()]
        candidates: List[str] = []
        qa: List[str] = []
        for line in lines:
            if re.match(r"^\d{1,2}\s+[A-Za-z]{3}\s+\d{4}\s+", line):
                candidates.append(line)
            elif candidates and not re.match(r"^(Date|Description|Money in|Money out|Balance|Page )", line):
                if not re.match(r"^(Transaction history|Current balance|Available balance|Account )", line):
                    candidates[-1] += " " + line.strip()

        out: List[TransactionRecord] = []
        seen = set()
        for raw in candidates:
            m = self.DATE_RE.match(raw)
            if not m:
                qa.append(f"Skipped row, no date match: {raw}")
                continue
            date_text, tail = m.group(1), m.group(2)
            monies = self.MONEY_RE.findall(tail)
            if len(monies) < 2:
                qa.append(f"Skipped row, not enough money columns: {raw}")
                continue
            try:
                tx_date = datetime.strptime(date_text, "%d %b %Y").date()
            except ValueError:
                qa.append(f"Skipped row, bad date: {raw}")
                continue
            balance_text = monies[-1]
            amount_text = monies[0]
            try:
                amount = abs(self.parse_amount(amount_text))
                balance = self.parse_amount(balance_text)
            except ValueError:
                qa.append(f"Skipped row, bad money parse: {raw}")
                continue
            desc = tail
            for part in monies:
                desc = desc.replace(part, " ")
            desc = self.normalize_desc(desc) or "Unknown Transaction"
            direction = "out" if amount_text.strip().startswith("-") else "in"
            fp = self.fingerprint(tx_date, desc, amount, direction)
            # Within one statement, two identical purchases on the same day
            # (same merchant, same amount) are real — the running balance
            # tells them apart. Cross-import dedup still uses the fingerprint.
            seen_key = (fp, balance)
            if seen_key in seen:
                continue
            seen.add(seen_key)
            rec = TransactionRecord(tx_date, desc, money_in=amount if direction == "in" else 0.0, money_out=amount if direction == "out" else 0.0, balance=balance, source_file=path.name, fingerprint=fp)
            out.append(rec)
        qa.insert(0, f"Rows detected: {len(candidates)}")
        qa.insert(1, f"Transactions parsed: {len(out)}")
        return out, qa


class TransactionMatcher:
    def __init__(self, state: AppState):
        self.state = state

    def classify_category(self, desc: str, direction: str = "out") -> str:
        # First, check merchant memory for a previously verified category
        mem_key = normalize_merchant_key(desc)
        if mem_key in self.state.merchant_memory:
            mem = self.state.merchant_memory[mem_key]
            if mem.direction == direction and mem.category:
                return mem.category
        desc_l = desc.lower()
        if any(k in desc_l for k in ["coles", "woolworths", "aldi", "iga", "foodworks", "costco"]):
            return "Groceries"
        if any(k in desc_l for k in ["bp ", "ampol", "shell", "7-eleven", "caltex", "united petro", "puma energy"]):
            return "Fuel"
        if any(k in desc_l for k in ["netflix", "spotify", "microsoft", "apple.com", "google play", "adobe", "amazon prime", "stan ", "binge", "foxtel", "paramount"]):
            return "Subscription"
        if any(k in desc_l for k in ["mcdonald", "kfc", "subway", "hungry jack", "domino", "pizza", "uber eat", "deliveroo", "doordash", "menulog"]):
            return "Food"
        if any(k in desc_l for k in ["woolworths petrol", "coles express"]):
            return "Fuel"
        if direction == "in":
            return "Income"
        return "General"

    def _name_match(self, desc: str, name: str) -> bool:
        parts = [p for p in re.split(r"\W+", name.lower()) if len(p) >= 3]
        desc_l = desc.lower()
        return any(p in desc_l for p in parts)

    def merchant_key(self, tx: TransactionRecord) -> str:
        return merchant_group_key(tx.description)

    def summarize_import_insights(self, transactions: List[TransactionRecord]) -> dict:
        merchant_counts: Dict[str, int] = {}
        merchant_samples: Dict[str, str] = {}
        merchant_amounts: Dict[str, List[float]] = {}
        unusual: List[str] = []
        new_merchants: List[str] = []
        known_memory = {merchant_group_key(k) for k in self.state.merchant_memory.keys()}
        known_rules = {merchant_group_key(r.keyword) for r in self.state.advanced_match_rules if r.keyword}
        committed_by_merchant: Dict[str, List[float]] = {}
        for tx in self.state.transactions:
            if tx.direction() != "out" or tx.matched_type == "ignore":
                continue
            committed_by_merchant.setdefault(self.merchant_key(tx), []).append(tx.money_out)

        for tx in transactions:
            if tx.direction() != "out" or tx.matched_type == "ignore":
                continue
            key = self.merchant_key(tx)
            merchant_counts[key] = merchant_counts.get(key, 0) + 1
            merchant_samples.setdefault(key, extract_merchant_name(tx.description))
            merchant_amounts.setdefault(key, []).append(tx.money_out)
            history = committed_by_merchant.get(key, [])
            if history:
                avg = sum(history) / len(history)
                if avg > 0 and tx.money_out >= avg * 1.8 and tx.money_out - avg >= 20:
                    unusual.append(f"{merchant_samples[key]} looks high: ${tx.money_out:,.2f} vs usual ${avg:,.2f}")
            elif key not in known_memory and key not in known_rules:
                if merchant_samples[key] not in new_merchants:
                    new_merchants.append(merchant_samples[key])

        recurring = []
        for key, count in merchant_counts.items():
            amounts = merchant_amounts.get(key, [])
            if count >= 2:
                spread = max(amounts) - min(amounts) if amounts else 0.0
                avg = sum(amounts) / max(len(amounts), 1)
                if avg > 0 and spread <= max(3.0, avg * 0.12):
                    recurring.append(f"{merchant_samples[key]} appears recurring ({count} charges around ${avg:,.2f})")

        recurring.sort()
        unusual.sort()
        new_merchants.sort()
        return {
            "recurring": recurring[:5],
            "unusual": unusual[:5],
            "new_merchants": new_merchants[:8],
        }

    def match(self, tx: TransactionRecord) -> TransactionRecord:
        desc_l = tx.description.lower()
        # Rules saved by the Sort Unrecognised flow use the merchant key (numbers and
        # bank noise stripped), so "contains" also checks that normalised form —
        # "ACME WIDGETS 5555 SYDNEY" still hits a rule for "acme widgets sydney".
        merchant_l = merchant_group_key(tx.description)
        for rule in self.state.advanced_match_rules:
            if not rule.is_active:
                continue
            kw = rule.keyword.lower().strip()
            matched = False
            if rule.rule_type == "exact" and kw and desc_l == kw:
                matched = True
            elif rule.rule_type == "contains" and kw and (kw in desc_l or kw in merchant_l):
                matched = True
            elif rule.rule_type == "amount_contains" and kw and (kw in desc_l or kw in merchant_l) and abs(tx.amount() - rule.amount) <= 2.0:
                matched = True
            if matched:
                tx.matched_type = rule.matched_type
                tx.matched_target = rule.matched_target
                tx.category = rule.category or self.classify_category(tx.description, tx.direction())
                tx.confidence = "manual"
                tx.needs_review = False
                tx.user_verified = True
                tx.notes = f"Matched by rule: {rule.rule_name}"
                return tx

        mem_key = normalize_merchant_key(tx.description)
        if mem_key in self.state.merchant_memory:
            mem = self.state.merchant_memory[mem_key]
            if mem.direction == tx.direction():
                tx.matched_type = mem.matched_type
                tx.matched_target = mem.matched_target
                tx.category = mem.category or self.classify_category(tx.description, tx.direction())
                tx.confidence = "memory"
                tx.needs_review = False
                tx.user_verified = True
                tx.notes = "Matched from saved merchant/category memory"
                return tx

        if tx.money_in > 0:
            tx.matched_type = "income"
            tx.category = "income"
            tx.confidence = "low"
            tx.needs_review = True
            tx.user_verified = False
            return tx

        for bill in self.state.bills:
            if self._name_match(tx.description, bill.name) or (abs(tx.money_out - bill.amount) <= 2.0 and abs((tx.tx_date - bill.due_date).days) <= 45):
                tx.matched_type = "linked_bill"
                tx.matched_target = bill.name
                tx.category = bill.category
                tx.confidence = "medium"
                tx.needs_review = True
                tx.user_verified = False
                return tx

        for fund in self.state.funds:
            if self._name_match(tx.description, fund.name):
                tx.matched_type = "linked_fund"
                tx.matched_target = fund.name
                tx.category = fund.category
                tx.confidence = "medium"
                tx.needs_review = True
                tx.user_verified = False
                return tx

        tx.matched_type = "discretionary"
        tx.category = self.classify_category(tx.description, tx.direction())
        tx.confidence = "low"
        tx.needs_review = True
        tx.user_verified = False
        return tx


class HomesteadEngine:
    """Derives the Homestead scene from real financial state. Stateless —
    nothing here is tracked separately; the scene is a view of the plan.

    snapshot() returns a dict the renderer and the page both read:
      time_of_day, weather, house_stage, lit_windows, plots, trees, fence,
      path_stones, mailbox_flag, windmill_spin, weeds, checks, tier
    """

    TIER_LABELS = {
        1: "Hen", 2: "Cat", 3: "Fox", 4: "Owl", 5: "Dragonet",
    }

    def __init__(self, state: AppState):
        self.state = state

    @staticmethod
    def _milestone_stage(amount: float, steps=(100.0, 500.0, 1000.0, 2500.0)) -> int:
        return sum(1 for m in steps if amount >= m)

    @staticmethod
    def _target_stage(saved: float, target: float) -> int:
        if saved <= 0:
            return 0
        pct = saved / max(target, 0.01)
        if pct >= 0.999:
            return 4
        return min(3, 1 + int(pct * 3))

    def snapshot(self, now: Optional[datetime] = None) -> dict:
        s = self.state
        g = s.game
        now = now or datetime.now()
        today = now.date()
        hour = now.hour
        time_of_day = "day" if 7 <= hour < 17 else "evening" if 17 <= hour < 20 else "night"
        streak = g.streak_pays
        weather = "clear" if streak >= 3 else "cloud" if streak >= 1 else "overcast"
        lvl = g.level
        house_stage = 5 if lvl >= 15 else 4 if lvl >= 10 else 3 if lvl >= 6 else 2 if lvl >= 3 else 1
        overdue = [b for b in s.bills if b.due_date < today and b.current_saved + 0.01 < b.amount]

        plots = []
        for f in s.funds[:8]:
            if BudgetEngine.has_end_target(f):
                stage = self._target_stage(f.current_saved, f.target_amount)
            else:
                stage = self._milestone_stage(f.current_saved)
            plots.append({"name": f.name, "stage": stage, "saved": f.current_saved})
        trees = []
        for gl in s.goals[:6]:
            if BudgetEngine.has_end_target(gl):
                stage = self._target_stage(gl.current_saved, gl.target_amount)
            else:
                stage = self._milestone_stage(gl.current_saved, (1000.0, 2500.0, 5000.0, 10000.0))
            trees.append({"name": gl.name, "stage": stage, "saved": gl.current_saved})
        fence = [{"name": b.name, "ok": not (b.due_date < today and b.current_saved + 0.01 < b.amount)}
                 for b in sorted(s.bills, key=lambda b: b.due_date)[:10]]
        path_stones = min(12, len({t.source_file for t in s.transactions if t.source_file}))
        mailbox_flag = any(getattr(t, "flagged", False) for t in s.transactions)
        cycle = BudgetEngine.PAY_CYCLE_DAYS.get(s.pay_frequency, 14)
        last_pay = max((i.received_on for i in s.incomes), default=None)
        weeds = bool(last_pay) and (today - last_pay).days > cycle * 1.5
        windmill_spin = streak > 0 and not overdue
        grown = sum(1 for p in plots if p["stage"] >= 3)
        checks = {
            "house": (house_stage >= 3, "House is a cottage or better (Level 6+)",
                      f"Level {lvl} · stage {house_stage}/5"),
            "plots": (len(plots) >= 2 and grown >= max(1, (len(plots) + 1) // 2),
                      "At least half your set-asides are well grown (2+ funds)",
                      f"{grown} of {len(plots)} plots grown"),
            "fence": (bool(fence) and all(f["ok"] for f in fence),
                      "Fence complete — no bill overdue",
                      f"{sum(1 for f in fence if f['ok'])} of {len(fence)} posts standing"),
            "path": (path_stones >= 6, "Path laid — 6 statements imported",
                     f"{path_stones} of 6 stones"),
            "mailbox": (bool(s.transactions) and not mailbox_flag,
                        "Mailbox flag down — no unresolved follow-ups",
                        "flag up" if mailbox_flag else ("flag down" if s.transactions else "no mail yet")),
        }
        tier = sum(1 for ok, _, _ in checks.values() if ok)
        mill_ready = False
        try:
            mill_ready = BudgetGameEngine(s).mill_status(now)["gold"] >= 5
        except Exception:
            pass
        return {
            "time_of_day": time_of_day, "weather": weather, "house_stage": house_stage,
            "lit_windows": not overdue, "plots": plots, "trees": trees, "fence": fence,
            "path_stones": path_stones, "mailbox_flag": mailbox_flag, "windmill_spin": windmill_spin,
            "weeds": weeds, "checks": checks, "tier": tier, "streak": streak, "level": lvl, "mill_ready": mill_ready,
            "palette": g.homestead_palette or "classic", "decor": list(g.homestead_decor),
        }

