class BudgetApp(tk.Tk):
    FORECAST_WINDOWS = (30, 60, 90)
    APP_TITLE = "Budget Planner"
    APP_SUBTITLE = "Operate your money like a calm system. Come back for the progression."

    def __init__(self):
        super().__init__()
        self.title(self.APP_TITLE)
        # Fit the default window to the screen (a 1366×768 laptop can't show
        # 920px tall) and allow a smaller minimum so overlays can adapt.
        try:
            sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
        except tk.TclError:
            sw, sh = 1520, 920
        self.geometry(f"{min(1520, max(1100, sw - 40))}x{min(920, max(640, sh - 90))}")
        self.minsize(1100, 640)
        self._apply_window_icon()
        self.updater = AppUpdater(self)

        self.state = self.load_state()
        apply_text_scale(self.state.ui_prefs.get("text_scale", 1.0))
        self.engine = BudgetEngine(self.state)
        self.game_engine = BudgetGameEngine(self.state)
        self.importer = PDFTransactionImporter()
        self.matcher = TransactionMatcher(self.state)
        self.homestead = HomesteadEngine(self.state)
        self.last_allocation = None
        self.last_game_result = None
        self.latest_import: List[TransactionRecord] = []
        self.latest_import_qa: List[str] = []
        self.transaction_insights: dict = {"recurring": [], "unusual": [], "new_merchants": []}
        self.rule_settings = {"investment_mode": "fixed", "investment_value": 0.0, "minimum_buffer": 0.0}
        try:
            saved_rules = dict(getattr(self.state, "investment_rules", {}) or {})
            if saved_rules.get("investment_mode") in ("fixed", "percent"):
                self.rule_settings["investment_mode"] = saved_rules["investment_mode"]
            self.rule_settings["investment_value"] = float(saved_rules.get("investment_value", 0.0) or 0.0)
            self.rule_settings["minimum_buffer"] = float(saved_rules.get("minimum_buffer", 0.0) or 0.0)
        except (TypeError, ValueError):
            pass
        self._target_drag_boundary_idx: Optional[int] = None
        self._scroll_canvases: list = []
        self._scroll_canvas_page: dict = {}  # canvas → page key (for wheel routing)
        self._toast_stack: list = []  # active toast frames (bottom-right, stacked upward)
        self.nav_buttons: dict[str, tk.Widget] = {}
        self.page_frames: dict[str, tk.Widget] = {}
        self.page_button_meta: dict[str, dict] = {}
        self.current_page_key = "today"
        self.nav_compact_labels = {
            "income": "Log Pay",
            "transactions": "Statements",
            "collection": "Cards",
            "character": "Avatar",
            "investments": "Invest",
            "review": "Analysis",
        }
        self._configure_styles()
        self._build_ui()
        _dark_titlebar(self)
        self._show_page(self.current_page_key)
        self.game_engine.generate_daily_challenges()
        self.game_engine.ensure_season()
        self._startup_progression_migration()
        self._render_sample_banner()
        self._log_engagement("launch")
        self.refresh_all_views()
        self.protocol("WM_DELETE_WINDOW", self.on_close)

        # Ensure all free starter avatar items are owned (migration for existing saves)
        _starters = {"hair_short_dark", "eyes_focused_brown", "outfit_starter_hoodie",
                      "background_midnight", "acc_none", "aura_none"}
        for sid in _starters:
            if sid not in self.state.game.character_items_owned:
                self.state.game.character_items_owned.append(sid)

        # Onboarding: show wizard for new users; auto-complete flag for existing users
        if not self.state.onboarding_complete:
            has_data = bool(self.state.bills or self.state.funds or self.state.goals or self.state.incomes)
            if has_data:
                self.state.onboarding_complete = True
                self.save_state()
            else:
                self.after(250, self._run_onboarding)
        elif not self.state.tutorial_complete:
            # Existing user who finished onboarding but hasn't seen tutorial yet
            self.after(400, self._run_tutorial)
        else:
            # Gerald proactive alert — 1.5s after UI settles
            self.after(1500, self._gerald_startup_alert)
            # End-of-month report prompt (once per month, after the UI settles)
            self.after(2200, self._maybe_prompt_monthly_report)
            self.after(2800, self._maybe_welcome_back)
        # Background update check — non-blocking, silent on failure.
        self.after(5000, self._check_for_updates_silent)

    def _check_for_updates_silent(self):
        """Startup check. If a newer version exists, offer it via toast."""
        if not self.updater.enabled():
            return
        def on_result(manifest, err):
            if not manifest or err:
                return
            remote = str(manifest.get("version", "")).strip()
            if not remote or not self.updater.is_newer(remote):
                return
            min_req = manifest.get("min_version")
            if min_req and self.updater._parse_version(APP_VERSION) < self.updater._parse_version(min_req):
                # Current build is below the min-supported floor — offer but flag it
                pass
            try:
                self._show_toast(
                    f"Update available: v{remote}",
                    "info",
                    6000,
                    action_label="Install",
                    action_cb=lambda m=manifest: self._offer_update_dialog(m),
                )
            except Exception:
                pass
        self.updater.check_async(on_result)

    def check_for_updates_now(self):
        """Manual check — shows a result regardless (found or already current)."""
        if not self.updater.enabled():
            if not self.updater.is_frozen():
                messagebox.showinfo("Updates",
                    "Update checks only run in the installed .exe build, not from source.",
                    parent=self)
            else:
                messagebox.showinfo("Updates",
                    "Update checks are disabled — no manifest URL configured.",
                    parent=self)
            return
        self._show_toast("Checking for updates…", "info", 2500)
        def on_result(manifest, err):
            if err or not manifest:
                self._show_toast(f"Update check failed: {err or 'no response'}", "warning", 4000)
                return
            remote = str(manifest.get("version", "")).strip()
            if self.updater.is_newer(remote):
                self._offer_update_dialog(manifest)
            else:
                self._show_toast(f"You're on the latest version (v{APP_VERSION}).", "success", 3000)
        self.updater.check_async(on_result)

    def _offer_update_dialog(self, manifest: dict):
        """Modal dialog showing release notes + Download / Later."""
        remote = str(manifest.get("version", "?")).strip()
        url = str(manifest.get("download_url", "")).strip()
        sha = manifest.get("sha256") or None
        notes = str(manifest.get("notes", "")).strip() or "(no release notes)"
        if not url:
            messagebox.showerror("Update", "Manifest missing download_url.", parent=self)
            return

        dlg = tk.Toplevel(self)
        dlg.title("Update available")
        dlg.transient(self)
        dlg.grab_set()
        dlg.configure(bg=UI_BG)
        dlg.geometry("520x360")
        dlg.resizable(False, False)

        card = tk.Frame(dlg, bg=UI_SURFACE, padx=SP_XL, pady=SP_LG)
        card.pack(fill="both", expand=True, padx=SP_MD, pady=SP_MD)

        tk.Label(card, text=f"Version {remote} is available",
                 bg=UI_SURFACE, fg=UI_TEXT,
                 font=FONT_DISPLAY_SM).pack(anchor="w")
        tk.Label(card, text=f"You have v{APP_VERSION}.",
                 bg=UI_SURFACE, fg=UI_MUTED,
                 font=FONT_SMALL).pack(anchor="w", pady=(2, SP_MD))

        notes_frame = tk.Frame(card, bg=UI_SURFACE2,
                               highlightthickness=1, highlightbackground=UI_BORDER)
        notes_frame.pack(fill="both", expand=True, pady=(0, SP_MD))
        header_row = tk.Frame(notes_frame, bg=UI_SURFACE2)
        header_row.pack(fill="x", padx=SP_MD, pady=(SP_SM, 0))
        tk.Label(header_row, text="What's new", bg=UI_SURFACE2, fg=UI_MUTED,
                 font=FONT_CAPTION_BOLD).pack(side="left")
        history = manifest.get("history") or []
        if len(history) > 1:
            def _open_history():
                self._show_changelog_dialog(history, current=remote, parent=dlg)
            ttk.Button(header_row, text="Previous updates…",
                       command=_open_history).pack(side="right")
        notes_lbl = tk.Label(notes_frame, text=notes, bg=UI_SURFACE2, fg=UI_TEXT,
                             font=FONT_SMALL, justify="left", wraplength=440, anchor="nw")
        notes_lbl.pack(anchor="nw", padx=SP_MD, pady=(2, SP_SM), fill="both", expand=True)

        progress_var = tk.StringVar(value="")
        progress_lbl = tk.Label(card, textvariable=progress_var, bg=UI_SURFACE, fg=UI_MUTED,
                                font=FONT_SMALL)
        progress_lbl.pack(anchor="w")
        bar = ttk.Progressbar(card, mode="determinate", length=460)
        bar.pack(fill="x", pady=(2, SP_MD))
        bar.pack_forget()

        btn_row = tk.Frame(card, bg=UI_SURFACE)
        btn_row.pack(fill="x")
        later_btn = ttk.Button(btn_row, text="Later", command=dlg.destroy)
        later_btn.pack(side="left")
        install_btn = ttk.Button(btn_row, text="Download & Install",
                                 style="Accent.TButton")
        install_btn.pack(side="right")

        def _on_progress(done, total):
            if total > 0:
                pct = (done / total) * 100
                bar.configure(value=pct)
                progress_var.set(f"Downloading… {done/1024/1024:.1f} / {total/1024/1024:.1f} MB")
            else:
                progress_var.set(f"Downloading… {done/1024/1024:.1f} MB")

        def _on_done(ok, result):
            if not ok:
                progress_var.set("")
                bar.pack_forget()
                install_btn.configure(state="normal")
                later_btn.configure(state="normal")
                messagebox.showerror("Download failed", result, parent=dlg)
                return
            progress_var.set("Download complete.")
            if messagebox.askyesno("Restart required",
                                   "Restart now to finish installing?",
                                   parent=dlg):
                try:
                    self.updater.apply_and_restart(result)
                except Exception as e:
                    messagebox.showerror("Update", f"Couldn't restart: {e}", parent=dlg)
            else:
                self._pending_update_exe = result
                self._show_toast("Update will install on next launch.", "info", 4000)
                dlg.destroy()

        def _start():
            install_btn.configure(state="disabled")
            later_btn.configure(state="disabled")
            bar.pack(fill="x", pady=(2, SP_MD), before=btn_row)
            progress_var.set("Starting download…")
            self.updater.download_async(url, sha, _on_progress, _on_done)

        install_btn.configure(command=_start)

    def _show_changelog_dialog(self, history: list, current: str = "", parent=None):
        """Scrollable list of past releases. `history` is manifest['history']."""
        owner = parent if parent is not None else self
        dlg = tk.Toplevel(owner)
        dlg.title("Changelog")
        dlg.transient(owner)
        dlg.configure(bg=UI_BG)
        dlg.geometry("560x480")
        dlg.minsize(440, 320)

        card = tk.Frame(dlg, bg=UI_SURFACE, padx=SP_LG, pady=SP_LG)
        card.pack(fill="both", expand=True, padx=SP_MD, pady=SP_MD)

        tk.Label(card, text="What's changed",
                 bg=UI_SURFACE, fg=UI_TEXT,
                 font=FONT_DISPLAY_SM).pack(anchor="w")
        sub = f"You're on v{APP_VERSION}."
        if current and current != APP_VERSION:
            sub = f"You're on v{APP_VERSION}. Latest: v{current}."
        tk.Label(card, text=sub, bg=UI_SURFACE, fg=UI_MUTED,
                 font=FONT_SMALL).pack(anchor="w", pady=(2, SP_MD))

        body = tk.Frame(card, bg=UI_SURFACE2,
                        highlightthickness=1, highlightbackground=UI_BORDER)
        body.pack(fill="both", expand=True)
        canvas = tk.Canvas(body, bg=UI_SURFACE2, highlightthickness=0, bd=0)
        vbar = ttk.Scrollbar(body, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=vbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        vbar.pack(side="right", fill="y")
        inner = tk.Frame(canvas, bg=UI_SURFACE2)
        canvas.create_window((0, 0), window=inner, anchor="nw")

        def _resize(_e=None):
            canvas.configure(scrollregion=canvas.bbox("all"))
        inner.bind("<Configure>", _resize)
        def _wheel(ev):
            canvas.yview_scroll(int(-1 * (ev.delta / 120)), "units")
        canvas.bind("<MouseWheel>", _wheel)
        inner.bind("<MouseWheel>", _wheel)

        if not history:
            tk.Label(inner, text="No release history available.",
                     bg=UI_SURFACE2, fg=UI_MUTED, font=FONT_SMALL,
                     padx=SP_MD, pady=SP_MD).pack(anchor="w")
        else:
            for i, entry in enumerate(history):
                ver = str(entry.get("version", "?")).strip()
                date = str(entry.get("date", "")).strip()
                notes = str(entry.get("notes", "")).strip() or "(no notes)"
                is_current = (ver == APP_VERSION)

                row = tk.Frame(inner, bg=UI_SURFACE2)
                row.pack(fill="x", padx=SP_MD, pady=(SP_SM if i == 0 else 0, SP_SM))

                head = tk.Frame(row, bg=UI_SURFACE2)
                head.pack(fill="x")
                tag_fg = UI_GOLD if is_current else UI_TEXT
                tk.Label(head, text=f"v{ver}", bg=UI_SURFACE2, fg=tag_fg,
                         font=FONT_BODY_BOLD).pack(side="left")
                if is_current:
                    tk.Label(head, text="  ← you are here", bg=UI_SURFACE2,
                             fg=UI_GOLD, font=FONT_CAPTION).pack(side="left")
                if date:
                    tk.Label(head, text=date, bg=UI_SURFACE2, fg=UI_MUTED,
                             font=FONT_CAPTION).pack(side="right")

                tk.Label(row, text=notes, bg=UI_SURFACE2, fg=UI_TEXT,
                         font=FONT_SMALL, justify="left", wraplength=480,
                         anchor="nw").pack(anchor="w", pady=(2, 0))

                if i < len(history) - 1:
                    tk.Frame(inner, bg=UI_BORDER, height=1).pack(
                        fill="x", padx=SP_MD, pady=SP_XS)

        btn_row = tk.Frame(card, bg=UI_SURFACE)
        btn_row.pack(fill="x", pady=(SP_MD, 0))
        ttk.Button(btn_row, text="Close", command=dlg.destroy).pack(side="right")

    def view_changelog(self):
        """Command-palette entry point: fetch manifest, show changelog dialog."""
        if not self.updater.enabled():
            # Offline/source mode — show just the current version.
            self._show_changelog_dialog(
                [{"version": APP_VERSION, "date": "", "notes": "(running from source — no release history available)"}],
                current=APP_VERSION,
            )
            return
        self._show_toast("Fetching changelog…", "info", 2000)
        def on_result(manifest, err):
            if err or not manifest:
                self._show_toast(f"Couldn't load changelog: {err or 'no response'}",
                                 "warning", 4000)
                return
            history = list(manifest.get("history") or [])
            if not history:
                history = [{
                    "version": str(manifest.get("version", "?")),
                    "date": str(manifest.get("date", "")),
                    "notes": str(manifest.get("notes", "")),
                }]
            self._show_changelog_dialog(history, current=str(manifest.get("version", "")))
        self.updater.check_async(on_result)

    def _gerald_startup_alert(self):
        """Fire one proactive alert + reminder scan after app launch."""
        try:
            if hasattr(self, "gerald_assistant"):
                self.gerald_assistant.check_proactive_alerts(rate_limit_seconds=0)
                self.gerald_assistant.scan_due_reminders()
        except Exception:
            pass

    def load_state(self) -> AppState:
        if DATA_FILE.exists():
            try:
                return AppState.from_dict(json.loads(DATA_FILE.read_text(encoding="utf-8")))
            except Exception as exc:
                bak = DATA_FILE.with_suffix(".bak")
                if bak.exists():
                    use_bak = messagebox.askyesno(
                        "Load error",
                        f"Could not load {DATA_FILE.name}:\n{exc}\n\nRestore from backup ({bak.name})?",
                    )
                    if use_bak:
                        try:
                            return AppState.from_dict(json.loads(bak.read_text(encoding="utf-8")))
                        except Exception as exc2:
                            messagebox.showerror("Backup load failed", f"Backup also failed:\n{exc2}\n\nStarting fresh.")
                else:
                    messagebox.showerror("Load error", f"Could not load {DATA_FILE.name}:\n{exc}\n\nStarting fresh.")
        return AppState()

    def save_state(self):
        # Keep only the most recent 104 income records (~2 years of fortnightly pay)
        if len(self.state.incomes) > 104:
            self.state.incomes = self.state.incomes[-104:]
        tmp = DATA_FILE.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.state.to_dict(), indent=2), encoding="utf-8")
        if DATA_FILE.exists():
            DATA_FILE.replace(DATA_FILE.with_suffix(".bak"))
        tmp.replace(DATA_FILE)

    def on_close(self):
        try:
            self._remember_window_prefs()
        except Exception:
            pass
        self.save_state()
        self.destroy()

