        selector_host.grid(row=0, column=0, sticky="w", padx=SP_XL, pady=(SP_LG, SP_SM))
        self._build_score_section_selector(selector_host)

        # Two hosts stacked in the same grid cell; we toggle visibility
        self._score_progress_host = tk.Frame(outer, bg=UI_BG)
        self._score_arcade_host = tk.Frame(outer, bg=UI_BG)
