    def _settings_load_sample(self):
        from tkinter import messagebox as _mb
        has_data = bool(self.state.bills or self.state.funds or self.state.goals or self.state.incomes or self.state.transactions)
        if has_data and not _mb.askyesno("Load sample data?", "Your current data will be saved to budget_data.before-sample.json and restored when you clear the sample.\n\nContinue?", parent=self):
            return
        if has_data:
            try:
                DATA_FILE.with_name(self.SAMPLE_BACKUP_NAME).write_text(json.dumps(self.state.to_dict(), indent=2), encoding="utf-8")
            except OSError as e:
                self._show_toast(f"Couldn't back up first: {e}", "warning", 5000); return
        self._replace_state(self._build_sample_state())
        self._startup_progression_migration()
        self._render_sample_banner()
        self._show_page("today")
        self._show_toast("Sample data loaded — a fortnightly earner three months in. Clear it from Settings or the banner.", "success", 6000)

    def _settings_clear_sample(self):
        bak = DATA_FILE.with_name(self.SAMPLE_BACKUP_NAME)
        if bak.exists():
            try:
                st = AppState.from_dict(json.loads(bak.read_text(encoding="utf-8")))
            except Exception as e:
                self._show_toast(f"Backup unreadable: {e}", "warning", 5000); return
            self._replace_state(st)
            try:
                bak.unlink()
            except OSError:
                pass
            self._show_toast("Your data is back.", "success", 3500)
        else:
            st = AppState()
            st.first_launch_date = date.today().isoformat()
            self._replace_state(st)
            self._show_toast("Sample cleared — a fresh start. The setup wizard is under Setup → Accounts.", "info", 5000)
        self._render_sample_banner()
        self._show_page("today")

    def _render_sample_banner(self):
        lbl = getattr(self, "_sample_banner", None)
        if lbl is None:
            return
        if self.state.ui_prefs.get("sample_mode"):
            lbl.configure(text="▲ SAMPLE DATA — click to clear")
            lbl.grid()
        else:
            lbl.grid_remove()

    # ── Engagement log (local only: engagement.jsonl beside the data file) ──
    def _log_engagement(self, action: str):
        try:
            path = DATA_FILE.with_name("engagement.jsonl")
            with path.open("a", encoding="utf-8") as f:
                f.write(json.dumps({"ts": datetime.now().isoformat(timespec="minutes"), "action": action}) + "\n")
        except Exception:
            pass

    def _engagement_stats(self) -> dict:
        """Active days in the last 7 / 30, first-seen date, and whether the
        profile came back on day 7 / day 30 after first launch."""
        path = DATA_FILE.with_name("engagement.jsonl")
        days = set()
        try:
            for line in path.read_text(encoding="utf-8").splitlines():
                try:
                    days.add(date.fromisoformat(json.loads(line)["ts"][:10]))
                except Exception:
                    continue
        except OSError:
            pass
        if not days:
            return {"first": None, "active7": 0, "active30": 0, "d7": None, "d30": None, "total": 0}
        today = date.today()
        first = min(days)
        d7 = (first + timedelta(days=7)) <= today
        d30 = (first + timedelta(days=30)) <= today
        return {"first": first, "total": len(days),
                "active7": sum(1 for d in days if (today - d).days < 7),
                "active30": sum(1 for d in days if (today - d).days < 30),
                "d7": (any(7 <= (d - first).days <= 9 for d in days) if d7 else None),
                "d30": (any(28 <= (d - first).days <= 34 for d in days) if d30 else None)}

    def _refresh_settings_engagement(self):
        var = getattr(self, "_settings_engagement_var", None)
        if var is None:
            return
        s = self._engagement_stats()
        if not s["first"]:
            var.set("No activity logged yet.")
            return
        yn = lambda v: "—" if v is None else ("yes" if v else "no")
        var.set(f"First opened {s['first']:%d %b %Y} · {s['total']} active days · {s['active7']} of the last 7 · {s['active30']} of the last 30"
                f" · came back on day 7: {yn(s['d7'])} · day 30: {yn(s['d30'])}")

    # ── Collection nudges ────────────────────────────────────────────────
    def _nearest_set_nudge(self) -> str:
        try:
            prog = self.game_engine.card_set_progress()
        except Exception:
            return ""
        best = None
        for sid, sname, _d, _cids, reward in CARD_SETS:
            owned, total, complete, _c = prog.get(sid, (0, 1, False, False))
            if complete:
                continue
            left = total - owned
            if left <= 2 and (best is None or left < best[0]):
                best = (left, sname, AVATAR_ITEMS.get(reward, {}).get("name", "a reward"))
        if not best:
            return ""
        left, sname, rname = best
        return f"✦ {left} card{'s' if left != 1 else ''} from completing {sname} → {rname}. Duplicates of that set are rerolled while you're this close."

    # ── Homestead phase 2: harvest burst, tier-up card ───────────────────
    def _homestead_burst(self, kind: str, name: str):
        """A short sparkle burst over a plot/tree on whichever Homestead canvas is visible."""
        snap = getattr(self, "_homestead_snap", None) or self.homestead.snapshot()
        items = snap.get("plots" if kind == "fund" else "trees", [])
        idx = next((i for i, p in enumerate(items) if p.get("name") == name), None)
        if idx is None:
            return
        for c, full in ((getattr(self, "_homestead_canvas", None), True), (getattr(self, "_today_homestead_canvas", None), False)):
            if c is None:
                continue
            try:
                if not c.winfo_ismapped():
                    continue
                w, h = c.winfo_width(), c.winfo_height()
                if kind == "fund":
                    r_, c_ = divmod(idx, 4)
                    x, y = (0.40 + c_ * 0.085) * w, (0.76 + r_ * 0.1) * h
                else:
                    x, y = (0.6 + idx * 0.058) * w, 0.64 * h
            except tk.TclError:
                continue
            self._sparkle_burst(c, x, y, 18 if full else 8, 14 if full else 6)

    def _sparkle_burst(self, c, x, y, n=16, r=14, frames=12):
        import random, math as _m
        ids = []
        pts = []
        for i in range(n):
            a = random.random() * 2 * _m.pi
            sp = r * (0.5 + random.random())
            col = random.choice([UI_GOLD, "#ffffff", UI_EMERALD, UI_AMETHYST])
            try:
                iid = c.create_oval(x - 2, y - 2, x + 2, y + 2, fill=col, outline="", tags="burst")
            except tk.TclError:
                return
            ids.append(iid); pts.append((_m.cos(a) * sp / frames, _m.sin(a) * sp / frames - 0.6))

        def step(k=0):
            try:
                if k >= frames:
                    c.delete("burst"); return
                for iid, (dx, dy) in zip(ids, pts):
                    c.move(iid, dx, dy + 0.15 * k)
                self.after(40, lambda: step(k + 1))
            except tk.TclError:
                pass
        step()

    def _show_tier_up_card(self, tier: int, item_ids: list, _tries: int = 0):
        # Don't stack on top of a wizard, the sort queue or another card — wait for it to close.
        busy = any(isinstance(w_, tk.Frame) and str(w_.cget("bg")) == UI_HERO and w_.winfo_manager() == "place"
                   for w_ in self.winfo_children()) or any(isinstance(w_, tk.Toplevel) for w_ in self.winfo_children())
        if busy and _tries < 40:
            self.after(3000, lambda: self._show_tier_up_card(tier, item_ids, _tries + 1))
            return
        scrim, content, btn_row, step_var, close = self._overlay_card(f"HOMESTEAD TIER {tier}", 560, min(720, 230 + 180 * max(1, len(item_ids))))
        names = []
        for iid in item_ids:
            it = AVATAR_ITEMS.get(iid, {})
            names.append(it.get("name", iid))
            row = tk.Frame(content, bg=UI_SURFACE2, highlightthickness=1, highlightbackground=UI_AMETHYST, padx=SP_MD, pady=SP_SM)
            row.pack(fill="x", pady=(0, SP_SM))
            c = tk.Canvas(row, width=120, height=150, bg=UI_SURFACE2, highlightthickness=0)
            c.pack(side="left", padx=(0, SP_MD))
            try:
                eq = dict(self.state.game.character_equipped); eq["companion"] = iid
                draw_avatar(c, eq, 120, 150)
            except Exception:
                c.create_text(60, 75, text=it.get("emoji", "✦"), font=("Segoe UI Symbol", 40), fill=UI_AMETHYST)
            txt = tk.Frame(row, bg=UI_SURFACE2)
            txt.pack(side="left", fill="x", expand=True)
            tk.Label(txt, text=it.get("name", iid), bg=UI_SURFACE2, fg=UI_TEXT_BRIGHT, font=FONT_HEADING).pack(anchor="w")
            tk.Label(txt, text=it.get("description", ""), bg=UI_SURFACE2, fg=UI_TEXT, font=FONT_SMALL, wraplength=340, justify="left").pack(anchor="w", pady=(2, 0))
            tk.Label(txt, text=f"Companion · {it.get('rarity', '').upper()} · joins your avatar's shoulder", bg=UI_SURFACE2, fg=UI_MUTED, font=FONT_CAPTION).pack(anchor="w", pady=(2, 0))
        tk.Label(content, text=f"The Homestead reached tier {tier} of 5 because the plan is in better shape — this is the place saying thanks.",
                 bg=UI_SURFACE, fg=UI_MUTED, font=FONT_CAPTION, wraplength=500, justify="left").pack(anchor="w")

        def _equip():
            for iid in item_ids:
                try:
                    ok, msg = self.game_engine.equip_avatar_item(iid)
                    if not ok:
                        self._show_toast(msg, "warning", 4000)
                except Exception:
                    pass
            self.save_state()
            try:
                self.refresh_character_tab()
            except Exception:
                pass
            close()
            self._show_toast(f"{', '.join(names)} equipped.", "success", 3000)
        ttk.Button(btn_row, text="Later", style="Ghost.TButton", command=close).pack(side="left")
        ttk.Button(btn_row, text="Equip now  ✓", style="Primary.TButton", command=_equip).pack(side="right")

    def _scene_quips(self, snap: dict) -> list:
        """Gerald noticing the Homestead — (priority, text, expression)."""
        q = []
        if snap.get("weeds"):
            q.append((62, "Weeds in the Homestead — a pay's overdue to be logged. One log and they're gone.", "thinking"))
        fence = snap.get("fence", [])
        if fence and not all(f["ok"] for f in fence):
            bad = next(f["name"] for f in fence if not f["ok"])
            q.append((58, f"There's a gap in the fence where {bad} is overdue. Mark it paid or move the date and the post stands back up.", "thinking"))
        if not snap.get("trees"):
            q.append((30, "The orchard's empty — no goals yet. Even an open-ended 'Emergency' goal plants a tree.", "normal"))
        elif all(t["stage"] == 0 for t in snap.get("trees", [])):
            q.append((28, "The orchard's looking thin. A little into a goal and the first leaves show.", "normal"))
        if snap.get("plots") and sum(1 for p in snap["plots"] if p["stage"] == 0) >= 2:
            q.append((26, "Two bare plots out there. Add $ to a set-aside and it starts sprouting — and ripens into a pack fragment.", "wink"))
        if not snap.get("windmill_spin") and self.state.incomes:
            q.append((24, "The windmill's still. It turns while a pay streak is alive and nothing's overdue.", "normal"))
        if snap.get("mill_ready"):
            q.append((44, "Grain sack's full by the windmill — Gold waiting on the Homestead. Collect it.", "happy"))
        return q

    # ── Homestead phase 3 UI: decor shop, palettes, share as image ───────
    def _render_homestead_shop(self):
        host = getattr(self, "_homestead_shop_host", None)
        if host is None:
            return
        for w_ in host.winfo_children():
            w_.destroy()
        g = self.state.game
        eng = self.game_engine
        if not self._feature_unlocked("decor"):
            self._locked_line(host, "decor", "Decor & palettes")
            return
        # Palettes
        prow = tk.Frame(host, bg=UI_SURFACE)
        prow.pack(fill="x", pady=(0, SP_SM))
        tk.Label(prow, text="PALETTE", bg=UI_SURFACE, fg=UI_MUTED, font=FONT_CAPTION_BOLD).pack(side="left", padx=(0, SP_SM))
        cur = g.homestead_palette or "classic"
        for pid, pal in HOMESTEAD_PALETTES.items():
            owned = pid == "classic" or pid in g.homestead_palettes
            on = pid == cur
            lbl = tk.Label(prow, text=pal["name"] + ("" if owned else " 🔒"), bg=UI_GOLD if on else UI_SURFACE2,
                           fg=UI_HERO if on else (UI_TEXT if owned else UI_MUTED), font=FONT_CAPTION_BOLD, padx=SP_SM, pady=3,
                           cursor="hand2" if owned else "", highlightthickness=1, highlightbackground=UI_GOLD if on else UI_BORDER)
            lbl.pack(side="left", padx=(0, 4))
            if owned:
                lbl.bind("<Button-1>", lambda _e, p=pid: self._set_palette_ui(p))
            else:
                lbl.bind("<Button-1>", lambda _e, p=pal: self._show_toast(p["blurb"], "info", 4500))
        tk.Label(host, text="Seasonal palettes unlock when you claim the top Season Pass tier during that season (Australian seasons).",
                 bg=UI_SURFACE, fg=UI_MUTED, font=FONT_CAPTION, wraplength=700, justify="left").pack(anchor="w", pady=(0, SP_SM))
        # Decor grid
        grid = tk.Frame(host, bg=UI_SURFACE)
        grid.pack(fill="x")
        for c in range(5):
            grid.columnconfigure(c, weight=1, uniform="decor")
        for i, (did, name, ct, cost, desc, _u, _v) in enumerate(HOMESTEAD_DECOR):
            owned = did in g.homestead_decor
            card = tk.Frame(grid, bg=UI_SURFACE2, highlightthickness=1, highlightbackground=UI_EMERALD if owned else UI_BORDER, padx=SP_SM, pady=SP_SM)
            card.grid(row=i // 5, column=i % 5, sticky="nsew", padx=(0, SP_XS), pady=(0, SP_XS))
            tk.Label(card, text=name, bg=UI_SURFACE2, fg=UI_TEXT_BRIGHT, font=FONT_SMALL_BOLD, anchor="w").pack(anchor="w")
            tk.Label(card, text=desc, bg=UI_SURFACE2, fg=UI_MUTED, font=FONT_CAPTION, wraplength=120, justify="left").pack(anchor="w")
            if owned:
                tk.Label(card, text="placed ✓", bg=UI_SURFACE2, fg=UI_EMERALD, font=FONT_CAPTION_BOLD).pack(anchor="w", pady=(2, 0))
            else:
                price = f"{cost} Gold" if ct == "gold" else f"{cost} Gem{'s' if cost != 1 else ''}"
                can = (g.total_score >= cost) if ct == "gold" else (g.gems >= cost)
                ttk.Button(card, text=price, style="Gold.TButton" if ct == "gold" else "Gem.TButton",
                           command=lambda d=did: self._buy_decor_ui(d), state="normal" if can else "disabled").pack(anchor="w", pady=(2, 0))

    def _buy_decor_ui(self, did: str):
        ok, msg = self.game_engine.buy_decor(did)
        self._show_toast(msg, "success" if ok else "warning", 3500)
        if ok:
            self.save_state()
            self.refresh_game_text()
            self.refresh_homestead_tab()
            self._log_engagement("decor")
            d = HOMESTEAD_DECOR_BY_ID[did]
            c = getattr(self, "_homestead_canvas", None)
            if c is not None:
                try:
                    self._sparkle_burst(c, d[5] * c.winfo_width(), d[6] * c.winfo_height(), 14, 12)
                except tk.TclError:
                    pass

    def _set_palette_ui(self, pid: str):
        ok, msg = self.game_engine.set_palette(pid)
        self._show_toast(msg, "success" if ok else "warning", 3000)
        if ok:
            self.save_state()
            self.refresh_homestead_tab()
            try:
                self._draw_today_homestead()
            except Exception:
                pass

    def _share_homestead_png(self):
        c = getattr(self, "_homestead_canvas", None)
        if c is None:
            return
        try:
            from PIL import ImageGrab
        except Exception:
            self._show_toast("Image export needs Pillow (pip install pillow).", "warning", 5000)
            return
        try:
            self.update_idletasks()
            x, y = c.winfo_rootx(), c.winfo_rooty()
            w, h = c.winfo_width(), c.winfo_height()
            img = ImageGrab.grab(bbox=(x, y, x + w, y + h))
        except Exception as e:
            self._show_toast(f"Couldn't capture the scene: {e}", "warning", 5000)
            return
        try:
            if sum(img.convert("L").resize((32, 32)).getdata()) / 1024.0 < 2:
                self._show_toast("The capture came back black — Windows won't paint windows while the session is locked. Try again with the desktop visible.", "warning", 6000)
                return
        except Exception:
            pass
        path = filedialog.asksaveasfilename(title="Save Homestead image", defaultextension=".png",
                                            initialfile=f"homestead-{date.today().isoformat()}.png",
                                            filetypes=[("PNG image", "*.png")])
        if not path:
            return
        try:
            img.save(path)
        except Exception as e:
            self._show_toast(f"Couldn't save: {e}", "warning", 5000)
            return
        self._log_engagement("share_homestead")
        self._show_toast(f"Saved {Path(path).name}.", "success", 5000, action_label="Open folder",
                         action_cb=lambda p=path: os.startfile(str(Path(p).parent)))

    # ── Today: live event banner ─────────────────────────────────────────
    def _render_event_banner(self):
        host = getattr(self, "_event_host", None)
