        ttk.Button(form, text="Update Selected",
                   command=self.update_selected_bill).grid(row=15, column=0, sticky="ew", pady=(0, SP_SM))
        ttk.Button(form, text="Mark as Paid", style="Gold.TButton",
                   command=self.mark_selected_bill_paid).grid(row=16, column=0, sticky="ew", pady=(0, SP_SM))
        ttk.Button(form, text="Delete Selected", style="Danger.TButton",
                   command=self.delete_selected_bill).grid(row=17, column=0, sticky="ew")
        # Table side
