    def _show_gerald_overlay(self):
        if getattr(self, "_gerald_overlay", None) is None:
            self._build_gerald_overlay()
        self._gerald_overlay.place(x=0, y=0, relwidth=1, relheight=1)
        self._gerald_overlay.lift()
        self._gerald_overlay_visible = True
        try:
            self.gerald_assistant.greet_contextually()
            self.gerald_assistant.scan_due_reminders()
            self._render_gerald_transcript()
        except Exception:
            pass
        try:
            self._gerald_overlay_entry.focus_set()
        except Exception:
            pass
        for surf in getattr(self, "_gerald_surfaces", []):
            c = surf["canvas"]
            c.after(20, lambda c=c: c.yview_moveto(1.0))

    def _hide_gerald_overlay(self):
        if getattr(self, "_gerald_overlay", None) is not None:
            self._gerald_overlay.place_forget()
            self._gerald_overlay_visible = False

    def _toggle_gerald_overlay(self, _e=None):
        if getattr(self, "_gerald_overlay_visible", False):
            self._hide_gerald_overlay()
        else:
            self._show_gerald_overlay()
        return "break"

