    def _build_quick_add_fab(self):
        """Floating quick-add button, bottom-left. Pops a small action menu."""
        if getattr(self, "_quick_add_fab", None) is not None:
            return
        glow = tk.Frame(self, bg=UI_BORDER, padx=1, pady=1, cursor="hand2")
        inner = tk.Frame(glow, bg=UI_SURFACE, padx=SP_MD, pady=SP_XS, cursor="hand2")
        inner.pack()
        tk.Label(inner, text="\u2795  Add", bg=UI_SURFACE, fg=UI_GOLD,
                 font=FONT_CAPTION_BOLD, cursor="hand2").pack()
        for w in (glow, inner, *inner.winfo_children()):
            w.bind("<Button-1>", self._toggle_quick_add_menu)
        glow.place(relx=0.0, rely=1.0, anchor="sw", x=SP_LG, y=-SP_LG)
        self._quick_add_fab = glow
        self._quick_add_menu = None

    def _toggle_quick_add_menu(self, _event=None):
        existing = getattr(self, "_quick_add_menu", None)
        if existing is not None and existing.winfo_exists():
            try: existing.destroy()
            except tk.TclError: pass
            self._quick_add_menu = None
            return
        self._open_quick_add_menu()

    def _open_quick_add_menu(self):
        fab = getattr(self, "_quick_add_fab", None)
        if fab is None:
            return
        menu = tk.Frame(self, bg=UI_GOLD, padx=1, pady=1)
        inner = tk.Frame(menu, bg=UI_SURFACE2, padx=SP_XS, pady=SP_XS)
        inner.pack(fill="both", expand=True)
        tk.Label(inner, text="QUICK ADD", bg=UI_SURFACE2, fg=UI_MUTED,
                 font=FONT_MICRO).pack(anchor="w", padx=SP_SM, pady=(SP_XS, SP_XS))

        def _close_and(cb):
            def _run(_e=None):
                try:
                    if self._quick_add_menu is not None:
                        self._quick_add_menu.destroy()
                except tk.TclError:
                    pass
                self._quick_add_menu = None
                cb()
            return _run

        def _log_pay():
            self._show_page("income")
            try: self.pay_amount_entry.focus_set()
            except Exception: pass

        def _add_bill():
            self._show_page("setup")
            if hasattr(self, "_show_setup_sub"):
                self._show_setup_sub("bills")
            try: self.clear_bill_form(); self.bill_name.focus_set()
            except Exception: pass

        def _add_fund():
            self._show_page("setup")
            if hasattr(self, "_show_setup_sub"):
                self._show_setup_sub("funds")
            try: self.clear_fund_form(); self.fund_name.focus_set()
            except Exception: pass

        def _add_goal():
            self._show_page("setup")
            if hasattr(self, "_show_setup_sub"):
                self._show_setup_sub("goals")
            try: self.clear_goal_form(); self.goal_name.focus_set()
            except Exception: pass

        items = [
            ("\u26a1  Log Pay", UI_EMERALD, _log_pay),
            ("\U0001f4a1  Add Bill", UI_RUBY, _add_bill),
            ("\U0001f3e6  Add Fund", UI_SAPPHIRE, _add_fund),
            ("\U0001f3af  Add Goal", UI_GOLD, _add_goal),
        ]
        for label, color, cb in items:
            row_outer = tk.Frame(inner, bg=UI_SURFACE2, cursor="hand2")
            row_outer.pack(fill="x", padx=2, pady=1)
            stripe = tk.Frame(row_outer, bg=color, width=3)
            stripe.pack(side="left", fill="y")
            text_lbl = tk.Label(row_outer, text=label, bg=UI_SURFACE2, fg=UI_TEXT,
                                 font=FONT_SMALL_BOLD, anchor="w", padx=SP_SM,
                                 pady=4, cursor="hand2")
            text_lbl.pack(side="left", fill="x", expand=True)
            handler = _close_and(cb)
            for w in (row_outer, stripe, text_lbl):
                w.bind("<Button-1>", handler)
                w.bind("<Enter>", lambda _e, r=row_outer, t=text_lbl: (
                    r.configure(bg=UI_SURFACE_HOVER),
                    t.configure(bg=UI_SURFACE_HOVER)))
                w.bind("<Leave>", lambda _e, r=row_outer, t=text_lbl: (
                    r.configure(bg=UI_SURFACE2),
                    t.configure(bg=UI_SURFACE2)))

        self._quick_add_menu = menu
        self.update_idletasks()
        # Anchor the menu above the FAB, bottom-left.
        fab.update_idletasks()
        fx = fab.winfo_x()
        fy = fab.winfo_y()
        menu.update_idletasks()
        mh = menu.winfo_reqheight()
        menu.place(x=fx, y=fy - mh - 6)
        menu.lift()

        # Close on Escape or click outside
        self.bind("<Escape>", lambda _e: self._toggle_quick_add_menu())
        def _on_app_click(event):
            w = event.widget
            if menu is None or not menu.winfo_exists():
                return
            # Walk up to see if the click target is inside the menu
            cur = w
            while cur is not None:
                if cur is menu:
                    return
                try: cur = cur.master
                except Exception: break
            try: menu.destroy()
            except tk.TclError: pass
            self._quick_add_menu = None
            try: self.unbind("<Button-1>", self._quick_add_click_bind_id)
            except Exception: pass
        self._quick_add_click_bind_id = self.bind("<Button-1>", _on_app_click, add="+")

    # ── Command Palette (Ctrl+K) ─────────────────────────────────────────────
