        self._cmd_palette_entry.bind("<Up>", lambda e: self._cmd_palette_move(-1))
        self._cmd_palette_entry.bind("<Return>", lambda e: self._cmd_palette_run())
        self._cmd_palette_entry.bind("<Escape>", lambda e: self._hide_command_palette())

