    def _show_command_palette(self):
        if getattr(self, "_cmd_palette", None) is None:
            self._build_command_palette_overlay()
        self._cmd_palette.place(x=0, y=0, relwidth=1, relheight=1)
        self._cmd_palette.lift()
        self._cmd_palette_visible = True
        try:
            self._cmd_palette_var.set("")
            self._cmd_palette_entry.focus_set()
        except Exception:
            pass
        self._cmd_palette_refresh()

    def _hide_command_palette(self, _e=None):
        if getattr(self, "_cmd_palette", None) is not None:
            self._cmd_palette.place_forget()
            self._cmd_palette_visible = False

    def _cmd_palette_all_items(self):
        """Build the full list of palette items. Each: (label, hint, action_cb)."""
        items = []
        # Tabs
        tab_labels = [
            ("today", "Today"), ("income", "Log Pay"),
            ("transactions", "Review / Import"), ("score", "Score"),
            ("setup", "Setup"), ("gerald", "Ask Gerald"),
            ("collection", "Cards"), ("character", "Avatar"),
            ("review", "Analysis"),
        ]
        for key, lbl in tab_labels:
            items.append((f"Go to {lbl}", "tab",
                          (lambda k=key: self._show_page(k))))
        # Setup sub-tabs
        for sub, lbl in [("bills", "Bills"), ("funds", "Funds"),
                         ("goals", "Goals"), ("investments", "Investments"),
                         ("rules", "Rules"), ("accounts", "Accounts")]:
            items.append((f"Go to Setup · {lbl}", "setup",
                          (lambda s=sub: (self._show_page("setup"),
                                          self._show_setup_sub(s)
                                          if hasattr(self, "_show_setup_sub") else None))))
        # Actions
        def _focus(widget_attr, page_key, sub=None, clear_fn=None):
            def _run():
                self._show_page(page_key)
                if sub and hasattr(self, "_show_setup_sub"):
                    self._show_setup_sub(sub)
                if clear_fn:
                    try: clear_fn()
                    except Exception: pass
                try: getattr(self, widget_attr).focus_set()
                except Exception: pass
            return _run
        items += [
            ("Log Pay (focus amount)", "action",
             _focus("pay_amount_entry", "income")),
            ("Add Bill", "action",
             _focus("bill_name", "setup", "bills", getattr(self, "clear_bill_form", None))),
            ("Add Fund", "action",
             _focus("fund_name", "setup", "funds", getattr(self, "clear_fund_form", None))),
            ("Add Goal", "action",
             _focus("goal_name", "setup", "goals", getattr(self, "clear_goal_form", None))),
            ("Import Bank Statement (PDF / CSV / OFX)", "action",
             (lambda: (self._show_page("transactions"),
                       self.import_pdf_transactions()))),
            ("Sort Unrecognised Transactions", "action",
             (lambda: (self._show_page("transactions"),
                       self.open_review_queue()))),
            ("Set Up Money Plan (wizard)", "action",
             (lambda: self._show_setup_wizard())),
            ("Add a bill / set-aside / goal", "action",
             (lambda: self._show_quick_add("bill"))),
            ("Toggle Focus Mode (hide the game)", "action",
             (lambda: self._toggle_focus_mode())),
            ("Open Perk Shop", "action",
             (lambda: self._open_perk_shop()
              if hasattr(self, "_open_perk_shop") else None)),
            ("Ask Gerald (overlay)", "action",
             self._show_gerald_overlay),
            ("Save Now", "action",
             (lambda: (self.save_state(),
                       self._show_toast("Saved.", "success", 1600)))),
            ("Check for updates", "action", self.check_for_updates_now),
            ("View changelog", "action", self.view_changelog),
        ]
        # Bills — jump + quick actions
        for idx, b in enumerate(getattr(self.state, "bills", [])):
            nm = b.name
            items.append((f"Bill · {nm} → jump to row", "bill",
                          (lambda i=idx: self._cmd_palette_select_tree(
                              "bills", "bill_tree", i))))
            items.append((f"Bill · {nm} → mark paid", "bill",
                          (lambda bill=b: self._mark_bill_paid_with_undo(bill)
                           if hasattr(self, "_mark_bill_paid_with_undo") else None)))
            items.append((f"Bill · {nm} → contribute", "bill",
                          (lambda i=idx: self._contribute_to_target("bill", i)
                           if hasattr(self, "_contribute_to_target") else None)))
        # Funds
        for idx, f in enumerate(getattr(self.state, "funds", [])):
            nm = f.name
            items.append((f"Fund · {nm} → jump to row", "fund",
                          (lambda i=idx: self._cmd_palette_select_tree(
                              "funds", "fund_tree", i))))
            items.append((f"Fund · {nm} → contribute", "fund",
                          (lambda i=idx: self._contribute_to_target("fund", i)
                           if hasattr(self, "_contribute_to_target") else None)))
        # Goals
        for idx, g in enumerate(getattr(self.state, "goals", [])):
            nm = g.name
            items.append((f"Goal · {nm} → jump to row", "goal",
                          (lambda i=idx: self._cmd_palette_select_tree(
                              "goals", "goal_tree", i))))
            items.append((f"Goal · {nm} → contribute", "goal",
                          (lambda i=idx: self._contribute_to_target("goal", i)
                           if hasattr(self, "_contribute_to_target") else None)))
        return items

    def _cmd_palette_select_tree(self, sub, tree_attr, idx):
        self._show_page("setup")
        if hasattr(self, "_show_setup_sub"):
            self._show_setup_sub(sub)
        tree = getattr(self, tree_attr, None)
        if tree is None:
            return
        iid = str(idx)
        try:
            tree.selection_set(iid)
            tree.focus(iid)
            tree.see(iid)
        except tk.TclError:
            pass

    @staticmethod
    def _cmd_palette_score(query: str, label: str) -> int:
        """Fuzzy-ish score. Higher = better. 0 = no match."""
        if not query:
            return 1
        q = query.lower()
        lbl = label.lower()
        if q == lbl:
            return 1000
        if lbl.startswith(q):
            return 600
        if q in lbl:
            return 400 - lbl.index(q)
        # Subsequence match
        i = 0
        for ch in lbl:
            if i < len(q) and ch == q[i]:
                i += 1
        if i == len(q):
            return 200 - (len(lbl) - len(q))
        return 0

    def _cmd_palette_refresh(self, _e=None):
        frame = getattr(self, "_cmd_palette_frame", None)
        if frame is None:
            return
        for child in list(frame.winfo_children()):
            try: child.destroy()
            except tk.TclError: pass
        self._cmd_palette_rows = []
        query = self._cmd_palette_var.get().strip()
        items = self._cmd_palette_all_items()
        scored = []
        for label, hint, action in items:
            s = self._cmd_palette_score(query, label)
            if s > 0:
                scored.append((s, label, hint, action))
        scored.sort(key=lambda t: (-t[0], t[1].lower()))
        scored = scored[:30]

        if not scored:
            tk.Label(frame, text="No matches.", bg=UI_SURFACE, fg=UI_MUTED,
                     font=FONT_SMALL, anchor="w", padx=SP_MD, pady=SP_MD).pack(
                     fill="x")
            return

        hint_color = {
            "tab": UI_ACCENT, "setup": UI_ACCENT,
            "action": UI_EMERALD, "bill": UI_RUBY,
            "fund": UI_SAPPHIRE, "goal": UI_GOLD,
        }
        for rank, (s, label, hint, action) in enumerate(scored):
            row = tk.Frame(frame, bg=UI_SURFACE, cursor="hand2")
            row.pack(fill="x", padx=2, pady=1)
            stripe = tk.Frame(row, bg=hint_color.get(hint, UI_BORDER), width=3)
            stripe.pack(side="left", fill="y")
            lbl = tk.Label(row, text=label, bg=UI_SURFACE, fg=UI_TEXT,
                            font=FONT_SMALL, anchor="w", padx=SP_MD, pady=5,
                            cursor="hand2")
            lbl.pack(side="left", fill="x", expand=True)
            tag = tk.Label(row, text=hint.upper(), bg=UI_SURFACE, fg=UI_MUTED,
                            font=FONT_MICRO, padx=SP_MD, cursor="hand2")
            tag.pack(side="right")
            entry = {"frame": row, "label": lbl, "tag": tag,
                     "action": action, "stripe": stripe}
            self._cmd_palette_rows.append(entry)
            for w in (row, lbl, tag, stripe):
                w.bind("<Button-1>", lambda _e, i=rank: self._cmd_palette_run(i))
        self._cmd_palette_selected = 0
        self._cmd_palette_restyle()

    def _cmd_palette_restyle(self):
        for i, r in enumerate(self._cmd_palette_rows):
            active = i == self._cmd_palette_selected
            bg = UI_SURFACE_HOVER if active else UI_SURFACE
            fg = UI_TEXT_BRIGHT if active else UI_TEXT
            try:
                r["frame"].configure(bg=bg)
                r["label"].configure(bg=bg, fg=fg)
                r["tag"].configure(bg=bg)
            except tk.TclError:
                pass
        # Scroll selected into view
        if self._cmd_palette_rows:
            try:
                r = self._cmd_palette_rows[self._cmd_palette_selected]["frame"]
                r.update_idletasks()
                c = self._cmd_palette_canvas
                c.update_idletasks()
                bbox = c.bbox("all")
                if bbox:
                    y = r.winfo_y()
                    h = r.winfo_height()
                    top = c.canvasy(0)
                    bot = top + c.winfo_height()
                    if y < top:
                        c.yview_moveto(max(0, y / max(1, bbox[3])))
                    elif y + h > bot:
                        c.yview_moveto(max(0, (y + h - c.winfo_height()) / max(1, bbox[3])))
            except tk.TclError:
                pass

    def _cmd_palette_move(self, delta):
        if not self._cmd_palette_rows:
            return "break"
        n = len(self._cmd_palette_rows)
        self._cmd_palette_selected = (self._cmd_palette_selected + delta) % n
        self._cmd_palette_restyle()
        return "break"

    def _cmd_palette_run(self, idx=None):
        if not self._cmd_palette_rows:
            return "break"
        if idx is None:
            idx = self._cmd_palette_selected
        if idx < 0 or idx >= len(self._cmd_palette_rows):
            return "break"
        action = self._cmd_palette_rows[idx]["action"]
        self._hide_command_palette()
        try:
            if action:
                action()
        except Exception:
            pass
        return "break"

    def _build_collection_tab(self):
        frame = self.collection_tab
        frame.columnconfigure(0, weight=1)
        frame.rowconfigure(1, weight=1)

        # ── Hero header with avatar + stats ───────────────────────────────────
        _hbg = UI_GRADIENT_TOP
        hero_canvas, hero = self._gradient_hero(frame, height=100)
        hero_canvas.grid(row=0, column=0, sticky="ew", padx=SP_XL, pady=(SP_XL, SP_MD))
        hero.configure(padx=SP_XL, pady=SP_LG)
        hero.columnconfigure(2, weight=1)

        # Mini avatar preview in header
        self._coll_mini_avatar = tk.Canvas(hero, width=64, height=84,
                                            bg=UI_SURFACE2, highlightthickness=1,
                                            highlightbackground=UI_BORDER)
        self._coll_mini_avatar.grid(row=0, column=0, rowspan=2, sticky="w", padx=(0, 14))

        # Title + progress
