    # selection helpers
    def on_bill_select(self, _=None):
        sel = self.bill_tree.selection()
        if not sel: return
        b = self.state.bills[int(sel[0])]
        self.clear_bill_form(); self.bill_name.insert(0, b.name); self.bill_amount.insert(0, str(b.amount)); self.bill_due.insert(0, b.due_date.isoformat()); self.bill_saved.insert(0, str(b.current_saved)); self.bill_priority.set(b.priority); self.bill_frequency.set(b.frequency)

    def on_fund_select(self, _=None):
        sel = self.fund_tree.selection()
        if not sel: return
        f = self.state.funds[int(sel[0])]
        self.clear_fund_form()
        self.fund_mode.set(self._fund_label_from_mode(f.contribution_mode)); self._sync_fund_form_mode()
        self.fund_name.insert(0, f.name)
        if f.target_amount > 0 and str(self.fund_target.cget("state")) == "normal":
            self.fund_target.insert(0, str(f.target_amount))
        if f.fixed_amount > 0 and str(self.fund_per_pay.cget("state")) == "normal":
            self.fund_per_pay.insert(0, str(f.fixed_amount))
        self.fund_saved.insert(0, str(f.current_saved)); self.fund_priority.set(f.priority)
        if f.target_date and str(self.fund_date.cget("state")) == "normal": self.fund_date.insert(0, f.target_date.isoformat())

    def on_goal_select(self, _=None):
        sel = self.goal_tree.selection()
        if not sel: return
        g = self.state.goals[int(sel[0])]
        self.clear_goal_form(); self.goal_name.insert(0, g.name); self.goal_target.insert(0, str(g.target_amount) if g.target_amount > 0 else ""); self.goal_value.insert(0, str(g.value)); self.goal_saved.insert(0, str(g.current_saved)); self.goal_mode.set(g.mode); self.goal_priority.set(self._priority_word(g.priority))

    def clear_bill_form(self):
        for w in [self.bill_name, self.bill_amount, self.bill_due, self.bill_saved]: w.delete(0, tk.END)
        self.bill_priority.set("essential"); self.bill_frequency.set("monthly")

    def clear_fund_form(self):
        for w in [self.fund_target, self.fund_date, self.fund_per_pay]:
            w.configure(state="normal")
        for w in [self.fund_name, self.fund_target, self.fund_date, self.fund_saved, self.fund_per_pay]: w.delete(0, tk.END)
        self.fund_priority.set("important")
        self.fund_mode.set(self._FUND_MODE_LABELS[0][1]); self._sync_fund_form_mode()

    def clear_goal_form(self):
        for w in [self.goal_name, self.goal_target, self.goal_value, self.goal_saved]: w.delete(0, tk.END)
        self.goal_mode.set("fixed"); self.goal_priority.set("important")

    def _recent_income_average(self, lookback_count: int = 6) -> float:
        incomes = sorted(self.state.incomes, key=lambda x: x.received_on)
        if not incomes:
            return max(float(self.state.income_baseline or 0.0), 0.0)
        recent = incomes[-lookback_count:]
        return round(sum(x.amount for x in recent) / max(len(recent), 1), 2)

    def _projected_income_within_days(self, days: int) -> float:
        avg_pay = self._recent_income_average()
        if avg_pay <= 0:
            return 0.0
        cycle_days = max(self.engine.current_cycle_days(), 1)
        projected_pays = max(0, math.floor(days / cycle_days))
        return round(avg_pay * projected_pays, 2)

    def _monthly_outgoing_baseline(self, months_back: int = 3) -> float:
        today = date.today()
        start = today - timedelta(days=30 * months_back)
        outgoing_total = sum(
            tx.money_out for tx in self.state.transactions
            if tx.direction() == "out" and tx.matched_type != "ignore" and start <= tx.tx_date <= today
        )
        if outgoing_total <= 0:
            return 0.0
        months = max((today - start).days / 30.0, 1.0)
        return round(outgoing_total / months, 2)

    def _available_liquid_balance_estimate(self) -> float:
        latest_balance = None
        for tx in sorted(self.state.transactions, key=lambda x: (x.tx_date, x.description)):
            if tx.balance is not None:
                latest_balance = float(tx.balance)
        if latest_balance is not None:
            return round(latest_balance, 2)
        saved_total = sum(b.current_saved for b in self.state.bills) + sum(f.current_saved for f in self.state.funds) + sum(g.current_saved for g in self.state.goals)
        recent_income = self._recent_income_average()
        return round(max(saved_total + self.state.last_safe_to_spend + recent_income * 0.5, 0.0), 2)

    def _obligations_within_days(self, days: int) -> list[dict]:
        end_day = date.today() + timedelta(days=days)
        obligations: list[dict] = []
        for bill in self.state.bills:
            if bill.due_date <= end_day:
                remaining = max(bill.amount - bill.current_saved, 0.0)
                if remaining > 0:
                    obligations.append({"kind": "bill", "name": bill.name, "due_date": bill.due_date, "amount_due": round(remaining, 2), "saved": round(bill.current_saved, 2)})
        for fund in self.state.funds:
            if fund.target_date and fund.target_date <= end_day:
                remaining = max(fund.target_amount - fund.current_saved, 0.0)
                if remaining > 0:
                    obligations.append({"kind": "fund", "name": fund.name, "due_date": fund.target_date, "amount_due": round(remaining, 2), "saved": round(fund.current_saved, 2)})
        for goal in self.state.goals:
            if goal.target_date and goal.target_date <= end_day:
                remaining = max(goal.target_amount - goal.current_saved, 0.0)
                if remaining > 0:
                    obligations.append({"kind": "goal", "name": goal.name, "due_date": goal.target_date, "amount_due": round(remaining, 2), "saved": round(goal.current_saved, 2)})
        obligations.sort(key=lambda x: (x["due_date"], -x["amount_due"]))
        return obligations

    def calculate_cashflow_forecast(self, windows: tuple[int, ...] = FORECAST_WINDOWS) -> dict:
        liquid_now = self._available_liquid_balance_estimate()
        monthly_outgoing = self._monthly_outgoing_baseline()
        all_obligations = self._obligations_within_days(max(windows) if windows else 90)
        results = []
        pressure_points = []
        avg_income = self._recent_income_average()
        for days in windows:
            income_in = self._projected_income_within_days(days)
            obligations = [o for o in all_obligations if (o["due_date"] - date.today()).days <= days]
            obligation_total = round(sum(o["amount_due"] for o in obligations), 2)
            baseline_spend = round(monthly_outgoing * (days / 30.0), 2)
            projected_end = round(liquid_now + income_in - obligation_total - baseline_spend, 2)
            min_cushion = round(max(avg_income * 0.15, 250.0), 2) if avg_income > 0 else 250.0
            pressure = "critical" if projected_end < 0 else "warning" if projected_end < min_cushion else "stable"
            if pressure != "stable":
                pressure_points.append(f"{days}-day pressure: projected ${projected_end:,.0f} after ${obligation_total:,.0f} obligations and ${baseline_spend:,.0f} baseline spend.")
            results.append({
                "days": days,
                "starting_liquid": liquid_now,
                "projected_income": income_in,
                "obligations_total": obligation_total,
                "baseline_spend": baseline_spend,
                "projected_end_balance": projected_end,
                "pressure": pressure,
                "obligations": obligations[:8],
            })
        return {
            "starting_liquid": round(liquid_now, 2),
            "monthly_outgoing_baseline": round(monthly_outgoing, 2),
            "windows": results,
            "pressure_points": pressure_points,
            "upcoming_obligations": all_obligations[:12],
        }

    def calculate_daily_safe_spend(self) -> dict:
        cycle_days = max(self.engine.current_cycle_days(), 1)
        safe_total = max(float(self.state.last_safe_to_spend), 0.0)
        last_income_date = max((x.received_on for x in self.state.incomes), default=date.today())
        next_pay_date = last_income_date + timedelta(days=cycle_days)
        if next_pay_date <= date.today():
            next_pay_date = date.today() + timedelta(days=cycle_days)
        days_left = max((next_pay_date - date.today()).days, 1)
        safe_per_day = round(safe_total / days_left, 2)

        cycle_start = next_pay_date - timedelta(days=cycle_days)
        spent_this_cycle = sum(
            tx.money_out for tx in self.state.transactions
            if tx.direction() == "out" and tx.matched_type != "ignore" and cycle_start <= tx.tx_date < next_pay_date
        )
        elapsed_cycle_days = max((date.today() - cycle_start).days + 1, 1)
        current_daily_spend = round(spent_this_cycle / elapsed_cycle_days, 2)
        pace_ratio = 0.0 if safe_per_day <= 0 else current_daily_spend / safe_per_day
        status = "safe" if pace_ratio <= 0.9 else "tight" if pace_ratio <= 1.1 else "over"

        return {
            "safe_to_spend_total": round(safe_total, 2),
            "days_left_in_cycle": days_left,
            "next_pay_date": next_pay_date,
            "cycle_start": cycle_start,
            "safe_per_day": safe_per_day,
            "spent_this_cycle": round(spent_this_cycle, 2),
            "current_daily_spend": current_daily_spend,
            "pace_ratio": round(pace_ratio, 2),
            "status": status,
        }

    def _next_actions_snapshot(self) -> dict:
        pending_review = len([tx for tx in self.state.transactions if tx.needs_review and not tx.user_verified]) + len([tx for tx in self.latest_import if tx.needs_review and not tx.user_verified])
        pace = self.calculate_daily_safe_spend()
        forecast = self.calculate_cashflow_forecast()
        health = self.calculate_financial_health_score()

        due_items = []
        for bill in self.state.bills:
            due_items.append(("Bill", bill.name, bill.amount, bill.current_saved, (bill.due_date - date.today()).days, bill.due_date))
        for fund in self.state.funds:
            if fund.target_date:
                due_items.append(("Fund", fund.name, fund.target_amount, fund.current_saved, (fund.target_date - date.today()).days, fund.target_date))
        for goal in self.state.goals:
            if goal.target_date:
                due_items.append(("Goal", goal.name, goal.target_amount, goal.current_saved, (goal.target_date - date.today()).days, goal.target_date))
        due_items.sort(key=lambda x: (x[4], x[5]))

        actions = []
        if not self.state.incomes:
            actions.append({"priority": 100, "title": "Log your first pay", "detail": "Income is the trigger for the whole system. Use the Log Pay tab to create your first allocation plan.", "cta": "Go to Log Pay"})
        if pending_review:
            actions.append({"priority": 95, "title": f"Verify {pending_review} transaction(s)", "detail": "Your insights and score depend on verified transaction data. Clear the review queue first.", "cta": "Open Transactions"})
        urgent_due = [x for x in due_items if x[4] <= self.engine.current_cycle_days()]
        if urgent_due:
            item_type, name, amount, saved, days, _ = urgent_due[0]
            actions.append({
                "priority": 90,
                "title": f"{item_type} due soon: {name}",
                "detail": f"${amount:,.2f} is due {'today' if days == 0 else f'in {days} day(s)' if days > 0 else f'{abs(days)} day(s) overdue'}. Currently saved ${saved:,.2f}.",
                "cta": "Review bills/funds"
            })
        if pace["status"] == "over":
            actions.append({"priority": 88, "title": "Spending pace is too high", "detail": f"You're spending about ${pace['current_daily_spend']:,.2f}/day this cycle versus a safe pace of ${pace['safe_per_day']:,.2f}/day.", "cta": "Check Today tab"})
        elif pace["status"] == "tight":
            actions.append({"priority": 72, "title": "Stay tight on daily spend", "detail": f"Daily pace is ${pace['current_daily_spend']:,.2f}/day against a safe limit of ${pace['safe_per_day']:,.2f}/day until {pace['next_pay_date'].isoformat()}.", "cta": "Hold discretionary spend"})
        if forecast["pressure_points"]:
            actions.append({"priority": 86, "title": "Forecast pressure ahead", "detail": forecast["pressure_points"][0], "cta": "Open Plan"})
        if health["status"] == "fragile":
            actions.append({"priority": 84, "title": "Financial health needs stabilising", "detail": f"Health score is {health['score']:.0f}/100. Focus on coverage, consistency, and verification before extra spending.", "cta": "Follow the top actions"})
        elif health["status"] == "fair":
            actions.append({"priority": 60, "title": "You are stable but not buffered yet", "detail": f"Health score is {health['score']:.0f}/100. One or two improvements would lift your resilience.", "cta": "Strengthen weak spots"})
        if not self.state.transactions:
            actions.append({"priority": 70, "title": "Import a bank statement", "detail": "Real transaction data unlocks spending review, category mix analysis, and better recommendations.", "cta": "Import PDF"})
        if not self.state.last_target_submit:
            actions.append({"priority": 52, "title": "Submit a spending target mix", "detail": "Set your target pie on the Score tab so your real spending can be compared against a plan.", "cta": "Open Score"})
        if g := self.state.game:
            if g.level >= 10 and g.prestige_level == 0:
                actions.append({"priority": 50, "title": "Prestige is unlocked", "detail": "Reset your level for a permanent score multiplier and keep your progression systems.", "cta": "Open Score"})
            if g.gems >= min((item[3] for item in PERK_SHOP_ITEMS), default=999):
                actions.append({"priority": 48, "title": "Spend your Gems", "detail": f"You have {g.gems} Gems ready for permanent upgrades in the Perk Shop.", "cta": "Open Perk Shop"})
            incomplete_challenges = [ch for ch in g.daily_challenges if not ch.get("completed")]
            if incomplete_challenges:
                actions.append({"priority": 42, "title": "Daily challenge available", "detail": incomplete_challenges[0]["description"], "cta": "Progress challenge"})

        if not actions:
            actions.append({"priority": 1, "title": "System is clear", "detail": "No urgent blockers. Maintain the plan, keep spending deliberate, and return after the next pay or statement import.", "cta": "Stay consistent"})

        actions.sort(key=lambda x: (-x["priority"], x["title"]))
        return {
            "actions": actions,
            "due_items": due_items,
            "pending_review": pending_review,
            "pace": pace,
            "forecast": forecast,
            "health": health,
        }

    def calculate_financial_health_score(self) -> dict:
        today = date.today()
        due_30 = [b for b in self.state.bills if b.due_date <= today + timedelta(days=30)]
        due_30_total = sum(b.amount for b in due_30)
        due_30_saved = sum(min(b.current_saved, b.amount) for b in due_30)
        bill_coverage_ratio = 1.0 if due_30_total <= 0 else clamp(due_30_saved / due_30_total, 0.0, 1.0)
        bill_points = round(30 * bill_coverage_ratio, 1)

        emergency_saved = sum(g.current_saved for g in self.state.goals if "emergency" in g.name.lower())
        emergency_ratio = 1.0 if self.state.emergency_fund_target <= 0 else clamp(emergency_saved / self.state.emergency_fund_target, 0.0, 1.0)
        emergency_points = round(25 * emergency_ratio, 1)

        recent_incomes = sorted(self.state.incomes, key=lambda x: x.received_on)[-6:]
        consistency_ratio = clamp(len(recent_incomes) / 6.0, 0.0, 1.0)
        reserve_base = self.state.last_reserved_total + self.state.last_fund_total + self.state.last_goal_total + self.state.last_invest_total
        reserve_ratio = 0.0
        if recent_incomes:
            reserve_ratio = clamp(sum(min(reserve_base / max(x.amount, 1.0), 1.0) for x in recent_incomes) / len(recent_incomes), 0.0, 1.0)
        savings_consistency = clamp((consistency_ratio * 0.5) + (reserve_ratio * 0.5), 0.0, 1.0)
        savings_points = round(20 * savings_consistency, 1)

        target_adherence = 0.0
        if self.state.last_target_submit and self.state.expense_target_order and self.state.expense_target_pct:
            start_m, end_m = previous_calendar_month_window(today)
            actual_amounts = outgoing_category_totals(self.state.transactions, start_m, end_m)
            if sum(actual_amounts.values()) > 0:
                actual_pct = percents_from_amounts(actual_amounts)
                distance = 0.0
                for idx, label in enumerate(self.state.expense_target_order):
                    if idx < len(self.state.expense_target_pct):
                        distance += abs(actual_pct.get(label, 0.0) - float(self.state.expense_target_pct[idx]))
                target_adherence = clamp(1.0 - (distance / 200.0), 0.0, 1.0)
        target_points = round(15 * target_adherence, 1)

        total_tx = len(self.state.transactions)
        verified_tx = sum(1 for tx in self.state.transactions if tx.user_verified or tx.direction() == "in")
        verification_ratio = 1.0 if total_tx <= 0 else clamp(verified_tx / total_tx, 0.0, 1.0)
        verification_points = round(10 * verification_ratio, 1)

        total_score = round(bill_points + emergency_points + savings_points + target_points + verification_points, 1)
        status = "strong" if total_score >= 80 else "fair" if total_score >= 60 else "fragile"
        components = [
            ("Bill coverage", bill_points, 30, bill_coverage_ratio),
            ("Emergency fund", emergency_points, 25, emergency_ratio),
            ("Savings consistency", savings_points, 20, savings_consistency),
            ("Target adherence", target_points, 15, target_adherence),
            ("Verification", verification_points, 10, verification_ratio),
        ]
        insights = []
        if bill_coverage_ratio < 0.75:
            insights.append("Near-term bills are not fully covered by current saved balances.")
        if emergency_ratio < 0.25:
            insights.append("Emergency fund progress is still shallow relative to the target.")
        if verification_ratio < 0.85:
            insights.append("Transaction verification is incomplete, which weakens insight accuracy.")
        if target_adherence >= 0.75 and target_points > 0:
            insights.append("Recent spending mix tracked closely to your submitted target.")
        elif not self.state.last_target_submit:
            insights.append("Submit a target mix to measure spending discipline more precisely.")
        return {
            "score": total_score,
            "status": status,
            "components": components,
            "insights": insights,
        }

    def _compute_personality(self) -> dict:
        """Compute 6 attributes (0-99) and the best-fit archetype from current state."""
        import math
        today = date.today()
        state = self.state
        g = state.game

        start_90 = today - timedelta(days=90)
        outgoing = [tx for tx in state.transactions
                    if tx.direction() == "out" and tx.matched_type != "ignore"
                    and tx.tx_date >= start_90]
        cat_totals = outgoing_category_totals(state.transactions, start_90, today)
        cat_pct = percents_from_amounts(cat_totals)

        income_total = sum(x.amount for x in state.incomes if x.received_on >= start_90)
        reserve_total = (state.last_reserved_total + state.last_fund_total
                         + state.last_goal_total + state.last_invest_total)

        streak_hist = g.streak_history or []
        recent = streak_hist[-20:] if streak_hist else []
        tx_committed = len(state.transactions)
        verified = sum(1 for tx in state.transactions if tx.user_verified or tx.direction() == "in")

        # Data-signal count — gates whether we reveal archetype.
        data_points = (
            len(streak_hist)
            + min(10, tx_committed // 5)
            + min(10, len(state.incomes))
            + (2 if state.funds else 0)
            + (2 if state.goals else 0)
        )
        analyzing = data_points < 5

        def clamp99(v):
            return int(round(max(0.0, min(99.0, v))))

        # ── Discipline ────────────────────────────────────────────────────────
        streak_consistency = (sum(1 for b in recent if b) / len(recent)) if recent else 0.0
        streak_depth = min(1.0, (g.streak_pays or 0) / 10.0)
        verify_rate = (verified / tx_committed) if tx_committed else 0.0
        if state.bills:
            bill_cov = sum(min(1.0, b.current_saved / max(b.amount, 1.0)) for b in state.bills) / len(state.bills)
        else:
            bill_cov = 0.0
        discipline = clamp99(99 * (0.30 * streak_consistency + 0.25 * streak_depth
                                   + 0.25 * verify_rate + 0.20 * bill_cov))

        # ── Thrift ────────────────────────────────────────────────────────────
        savings_rate = (reserve_total / income_total) if income_total > 0 else 0.0
        savings_score = min(1.0, savings_rate / 0.40)  # 40%+ = full marks
        disc_share = 0.0
        for c in DISCRETIONARY_CATEGORIES:
            disc_share += cat_pct.get(c, 0.0)
            disc_share += cat_pct.get(c.title(), 0.0)
            disc_share += cat_pct.get(c.capitalize(), 0.0)
        disc_share /= 100.0
        thrift_raw = 0.65 * savings_score + 0.35 * (1.0 - min(1.0, disc_share / 0.50))
        thrift = clamp99(99 * thrift_raw) if income_total > 0 or cat_totals else 0

        # ── Vision ────────────────────────────────────────────────────────────
        fund_count = len(state.funds)
        goal_count = len(state.goals)
        # Open-ended funds/goals (no target) can't be "full" — count them as on
        # track once they hold anything, so they don't drag the score down.
        def _prog(item) -> float:
            if not BudgetEngine.has_end_target(item):
                return 1.0 if item.current_saved > 0 else 0.5
            return min(1.0, item.current_saved / max(item.target_amount, 1.0))
        fund_progress = (sum(_prog(f) for f in state.funds) / fund_count) if fund_count else 0.0
        goal_progress = (sum(_prog(go) for go in state.goals) / goal_count) if goal_count else 0.0
        breadth = min(1.0, (fund_count + goal_count) / 8.0)
        prestige_bonus = min(0.25, (g.prestige_level or 0) * 0.08)
        has_invest = state.last_invest_total > 0
        vision_raw = 0.30 * breadth + 0.30 * fund_progress + 0.25 * goal_progress + 0.10 * (1.0 if has_invest else 0.0) + prestige_bonus
        vision = clamp99(99 * vision_raw) if (fund_count or goal_count or has_invest or g.prestige_level) else 0

        # ── Diversity ─────────────────────────────────────────────────────────
        shares = [v / 100.0 for v in cat_pct.values() if v > 0]
        if len(shares) >= 2:
            H = -sum(s * math.log(s) for s in shares)
            H_max = math.log(len(shares))
            diversity_raw = H / H_max if H_max > 0 else 0.0
        else:
            diversity_raw = 0.0
        diversity = clamp99(99 * diversity_raw)

        # ── Volatility ────────────────────────────────────────────────────────
        if len(recent) >= 3:
            breaks = sum(1 for b in recent if not b)
            swing_rate = breaks / len(recent)
            runs = 0
            for i in range(1, len(recent)):
                if recent[i] != recent[i-1]:
                    runs += 1
            flip_rate = runs / max(1, len(recent) - 1)
            volatility = clamp99(99 * (0.55 * swing_rate + 0.45 * flip_rate))
        else:
            volatility = 0

        # ── Resilience ────────────────────────────────────────────────────────
        emergency_saved = sum(go.current_saved for go in state.goals if "emergency" in go.name.lower())
        if state.emergency_fund_target > 0:
            emergency_ratio = min(1.0, emergency_saved / state.emergency_fund_target)
        elif emergency_saved > 0:
            emergency_ratio = min(1.0, emergency_saved / 2000.0)
        else:
            emergency_ratio = 0.0
        shield_score = min(1.0, (g.streak_shields or 0) / 3.0)
        bill_buffer = min(1.0, bill_cov * 1.1)
        resilience = clamp99(99 * (0.50 * emergency_ratio + 0.20 * shield_score + 0.30 * bill_buffer))

        attrs = {
            "discipline": discipline, "thrift": thrift, "vision": vision,
            "diversity": diversity, "volatility": volatility, "resilience": resilience,
        }

        # ── Archetype selection ───────────────────────────────────────────────
        scored = []
        for tup in PERSONALITY_ARCHETYPES:
            aid, aname, adesc, acolor, aglyph, profile = tup
            dist = sum((attrs[k] - profile[k]) ** 2 for k in profile)
            scored.append((dist, aid, aname, adesc, acolor, aglyph, profile))
        scored.sort(key=lambda r: r[0])
        best = scored[0]
        runner = scored[1] if len(scored) > 1 else None

        # Tier based on match closeness.
        tier_name, tier_color = "Novice", UI_MUTED
        for threshold, name, color in PERSONALITY_TIERS:
            if best[0] <= threshold:
                tier_name, tier_color = name, color
                break
        else:
            tier_name, tier_color = "Seeker", UI_MUTED

        # Confidence: how decisive is the pick vs runner-up? 0..100.
        if runner and (best[0] + runner[0]) > 0:
            gap = (runner[0] - best[0]) / max(1.0, runner[0] + best[0])
            confidence = int(round(clamp(gap * 200.0, 0.0, 100.0)))
        else:
            confidence = 0

        # Top 3 defining traits = highest-valued attributes.
        top3 = sorted(attrs.items(), key=lambda kv: kv[1], reverse=True)[:3]

        # Trend vs last snapshot.
        trends = {}
        snap = getattr(g, "personality_snapshot", {}) or {}
        prev_attrs = snap.get("attrs", {}) if isinstance(snap, dict) else {}
        for k, v in attrs.items():
            prev = prev_attrs.get(k)
            if prev is None:
                trends[k] = 0
            else:
                d = v - int(prev)
                trends[k] = 1 if d >= 3 else (-1 if d <= -3 else 0)

        # Suggestion: which attributes to raise/lower to reach runner-up.
        runner_deltas = []
        if runner:
            rp = runner[6]
            for k in rp:
                d = rp[k] - attrs[k]
                if abs(d) >= 10:
                    runner_deltas.append((k, d))
            runner_deltas.sort(key=lambda kv: abs(kv[1]), reverse=True)
            runner_deltas = runner_deltas[:2]

        return {
            "attributes": attrs,
            "archetype_id": best[1],
            "archetype_name": best[2],
            "archetype_desc": best[3],
            "archetype_color": best[4],
            "archetype_glyph": best[5],
            "archetype_profile": best[6],
            "runner_up_id": runner[1] if runner else None,
            "runner_up_name": runner[2] if runner else None,
            "runner_up_deltas": runner_deltas,
            "tier_name": tier_name,
            "tier_color": tier_color,
            "confidence": confidence,
            "match_distance": best[0],
            "analyzing": analyzing,
            "top_attributes": top3,
            "data_points": data_points,
            "trends": trends,
        }

    def _capture_personality_snapshot(self):
        """Store current personality as baseline for future trend comparisons."""
        p = self._compute_personality()
        if p["analyzing"]:
            return
        self.state.game.personality_snapshot = {
            "attrs": dict(p["attributes"]),
            "archetype_id": p["archetype_id"],
            "captured_on": date.today().isoformat(),
        }

    # refresh
    def refresh_all_views(self):
        self.refresh_today_tab(); self.refresh_review_tab(); self.refresh_income_history(); self.refresh_transactions_tab(); self.refresh_rules_tab(); self.refresh_bills(); self.refresh_funds(); self.refresh_goals(); self.refresh_investments_text(); self.refresh_game_text(); self.refresh_collection(); self.refresh_character_tab()
        if hasattr(self, "_homestead_canvas"):
            self.refresh_homestead_tab()
        if hasattr(self, "_plan_host"):
            self.refresh_plan_tab()

    def rank_name_for_level(self, level: int, prestige: int = 0) -> str:
        if prestige >= 3:
            return "The Ascended"
        if prestige == 2:
            return "The Immortal"
        if prestige == 1:
            return "The Legend"
        ranks = [
            "The Recruit",      # L1  — you've decided to start
            "The Consistent",   # L2  — showing up every pay
            "The Tracker",      # L3  — you know where money goes
            "The Planner",      # L4  — thinking ahead
            "The Builder",      # L5  — actively growing wealth
            "The Analyst",      # L6  — data-driven decisions
            "The Strategist",   # L7  — sophisticated approach
            "The Accumulator",  # L8  — wealth is compounding
            "The Architect",    # L9  — master of your financial design
            "The Sovereign",    # L10 — full command, ready to prestige
        ]
        return ranks[min(level - 1, len(ranks) - 1)]

    def rank_icon_for_level(self, level: int, prestige: int = 0) -> str:
        if prestige >= 1:
            return "\u2654"   # ♔ crown
        icons = ["\u25cb", "\u25c8", "\u25c6", "\u2b21", "\u2b22", "\u2726", "\u2605", "\u272a", "\u2736", "\u265b"]
        return icons[min(level - 1, len(icons) - 1)]

    def refresh_income_history(self):
        if hasattr(self, "_quick_pay_host"):
            self._render_quick_pay()
        for row in self.income_tree.get_children(): self.income_tree.delete(row)
        for idx, entry in reversed(list(enumerate(self.state.incomes))):
            self.income_tree.insert("", tk.END, iid=str(idx), values=(self._format_date_with_relative(entry.received_on), entry.source, f"${entry.amount:,.2f}"))
        self._restripe_tree(self.income_tree)
        self._toggle_tree_empty_state(self.income_tree)

    def _pie_slice_hover_on(self, tag: str, color: str, label: str, val: float, pct: float):
        canvas = self.expense_pie_canvas
        canvas.configure(cursor="hand2")
        try:
            canvas.itemconfigure(tag, outline=UI_GOLD, width=3)
        except tk.TclError:
            return
        # Restyle center text
        if hasattr(self, "_pie_center_vars"):
            try:
                canvas.itemconfigure("pie_center_label", text=label[:22].upper())
                canvas.itemconfigure("pie_center_total", text=f"${val:,.0f}", fill=color)
                canvas.itemconfigure("pie_center_sub", text=f"{pct:.1f}% of total")
            except tk.TclError:
                pass

    def _pie_slice_hover_off(self, tag: str):
        canvas = self.expense_pie_canvas
        canvas.configure(cursor="")
        try:
            canvas.itemconfigure(tag, outline=UI_BG, width=2)
        except tk.TclError:
            return
        if hasattr(self, "_pie_center_vars"):
            pv = self._pie_center_vars
            try:
                canvas.itemconfigure("pie_center_label", text="TOTAL")
                canvas.itemconfigure("pie_center_total",
                                     text=f"${pv['total_sum']:,.0f}", fill=UI_GOLD)
                canvas.itemconfigure("pie_center_sub", text=f"{pv['count']} categories")
            except tk.TclError:
                pass

    def refresh_expense_pie_chart(self, _event=None):
        canvas = self.expense_pie_canvas
        canvas.delete("all")
        canvas.update_idletasks()
        w = max(int(canvas.winfo_width() or 0), 400)
        h = int(canvas.winfo_height() or 300)
        totals: Dict[str, float] = {}
        for tx in self.state.transactions:
            if tx.direction() != "out":
                continue
            if tx.matched_type == "ignore":
                continue
            cat = (tx.category or "").strip() or "Uncategorized"
            totals[cat] = totals.get(cat, 0.0) + tx.money_out
        if not totals:
            canvas.create_text(w // 2, h // 2, text="No committed outgoing transactions yet.", font=FONT_SUBHEADING, fill=UI_MUTED)
            return
        total_sum = sum(totals.values())
        if total_sum <= 0:
            canvas.create_text(w // 2, h // 2, text="No outgoing amounts in committed data.", font=FONT_SUBHEADING, fill=UI_MUTED)
            return
        items = sorted(totals.items(), key=lambda x: -x[1])
        cx = w // 2
        cy = min(130, h // 2 - 10)
        r = min(w // 2 - 40, 115, cy - 8)
        inner_r = max(int(r * 0.55), 40)
        start = 90.0
        # Cache so hover can restyle without rebuilding
        self._pie_slice_tags = []
        for i, (label, val) in enumerate(items):
            extent = -360.0 * (val / total_sum)
            color = PIE_COLORS[i % len(PIE_COLORS)]
            tag = f"pie_slice_{i}"
            self._pie_slice_tags.append(tag)
            canvas.create_arc(cx - r, cy - r, cx + r, cy + r, start=start, extent=extent,
                              fill=color, outline=UI_BG, width=2,
                              tags=(tag, "pie_clickable"))
            canvas.tag_bind(tag, "<Button-1>",
                             lambda _e, c=label: self._open_category_drilldown(c))
            canvas.tag_bind(tag, "<Enter>",
                             lambda _e, c=color, lbl=label, v=val, pct=100.0 * val / total_sum, t=tag:
                                 self._pie_slice_hover_on(t, c, lbl, v, pct))
            canvas.tag_bind(tag, "<Leave>",
                             lambda _e, t=tag: self._pie_slice_hover_off(t))
            start += extent
        # Donut hole + center total
        canvas.create_oval(cx - inner_r, cy - inner_r, cx + inner_r, cy + inner_r,
                           fill=UI_SURFACE, outline=UI_BORDER, width=1,
                           tags=("pie_center",))
        canvas.create_text(cx, cy - 12, text="TOTAL", fill=UI_MUTED,
                           font=FONT_MICRO, tags=("pie_center_label", "pie_center"))
        canvas.create_text(cx, cy + 6, text=f"${total_sum:,.0f}", fill=UI_GOLD,
                           font=FONT_SUBHEADING, tags=("pie_center_total", "pie_center"))
        canvas.create_text(cx, cy + 24, text=f"{len(items)} categories", fill=UI_MUTED,
                           font=FONT_MICRO, tags=("pie_center_sub", "pie_center"))
        self._pie_center_vars = {
            "cx": cx, "cy": cy, "total_sum": total_sum, "count": len(items),
        }
        y = min(cy + r + 28, h - 40)
        canvas.create_text(16, y, anchor="w", text=f"Total outgoing in chart: ${total_sum:,.2f}", font=FONT_SMALL_BOLD, fill=UI_TEXT)
        canvas.create_text(w - 16, y, anchor="e", text="Tip: click a slice to see transactions",
                            font=FONT_MICRO, fill=UI_MUTED)
        y += 40
        for i, (label, val) in enumerate(items[:18]):
            color = PIE_COLORS[i % len(PIE_COLORS)]
            pct = 100.0 * val / total_sum
            legend_tag = f"pie_legend_{i}"
            canvas.create_rectangle(16, y, 30, y + 12, fill=color, outline="", tags=(legend_tag,))
            canvas.create_text(36, y + 6, anchor="w",
                                text=f"{label}: ${val:,.2f} ({pct:.1f}%)",
                                font=FONT_SMALL, fill=UI_TEXT, tags=(legend_tag,))
            canvas.tag_bind(legend_tag, "<Button-1>",
                             lambda _e, c=label: self._open_category_drilldown(c))
            canvas.tag_bind(legend_tag, "<Enter>",
                             lambda _e: canvas.configure(cursor="hand2"))
            canvas.tag_bind(legend_tag, "<Leave>",
                             lambda _e: canvas.configure(cursor=""))
            y += 18
        if len(items) > 18:
            canvas.create_text(16, y + 4, anchor="w", text=f"… and {len(items) - 18} more categories", font=("Segoe UI Variable Text",9, "italic"), fill=UI_MUTED)

    def _parse_filter_date(self, s: str):
        s = (s or "").strip()
        if not s:
            return None
        for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y", "%d/%m/%y"):
            try:
                return datetime.strptime(s, fmt).date()
            except ValueError:
                continue
        return None

    def _clear_tx_filters(self):
        if hasattr(self, "tx_filter_keyword_var"):
            self.tx_filter_keyword_var.set("")
        if hasattr(self, "tx_filter_from_var"):
            self.tx_filter_from_var.set("")
        if hasattr(self, "tx_filter_to_var"):
            self.tx_filter_to_var.set("")
        self.refresh_transactions_tab()

    def refresh_transactions_tab(self):
        if hasattr(self, "_bank_links_host"):
            self._render_bank_buttons()
        self._update_nav_badges()
        self.refresh_category_combo()
        for row in self.transaction_tree.get_children(): self.transaction_tree.delete(row)
        for idx, tx in enumerate(self.latest_import):
            status = "Verified" if tx.user_verified else "Needs review"
            if getattr(tx, "flagged", False):
                status = "🚩 " + status
            tag = "matched" if tx.user_verified else "review" if tx.needs_review else "urgent"
            self.transaction_tree.insert("", tk.END, iid=str(idx), values=(
                tx.tx_date.isoformat(),
                tx.description[:40],
                f"${tx.amount():,.2f}",
                tx.direction(),
                tx.matched_type,
                tx.matched_target,
                (tx.category or "")[:24],
                status,
            ), tags=(tag,))
        self._restripe_tree(self.transaction_tree)
        self._toggle_tree_empty_state(self.transaction_tree)
        for row in self.tx_history_tree.get_children(): self.tx_history_tree.delete(row)
        kw = (getattr(self, "tx_filter_keyword_var", None).get().strip().lower()
              if hasattr(self, "tx_filter_keyword_var") else "")
        d_from = self._parse_filter_date(getattr(self, "tx_filter_from_var", None).get()
                                          if hasattr(self, "tx_filter_from_var") else "")
        d_to = self._parse_filter_date(getattr(self, "tx_filter_to_var", None).get()
                                        if hasattr(self, "tx_filter_to_var") else "")
        shown = 0
        total = len(self.state.transactions)
        for idx, tx in reversed(list(enumerate(self.state.transactions))):
            if kw and kw not in tx.description.lower() and kw not in (tx.category or "").lower() and kw not in (tx.matched_target or "").lower():
                continue
            if d_from and tx.tx_date < d_from:
                continue
            if d_to and tx.tx_date > d_to:
                continue
            self.tx_history_tree.insert("", tk.END, iid=str(idx), values=(
                tx.tx_date.isoformat(),
                ("🚩 " if getattr(tx, "flagged", False) else "") + tx.description[:40],
                f"${tx.amount():,.2f}",
                tx.matched_type,
                tx.matched_target,
                (tx.category or "")[:24],
                tx.source_file,
            ))
            shown += 1
        self._restripe_tree(self.tx_history_tree)
        if hasattr(self, "tx_filter_count_var"):
            if kw or d_from or d_to:
                self.tx_filter_count_var.set(f"{shown} of {total}")
            else:
                self.tx_filter_count_var.set(f"{total} total")
        self.tx_committed_summary_var.set(f"{total} committed")
        self.transaction_log_text.delete("1.0", tk.END)
        verified = sum(1 for t in self.latest_import if t.user_verified)
        needs_review = sum(1 for t in self.latest_import if t.direction() == "out" and not t.user_verified)
        if hasattr(self, "tx_sort_btn_var"):
            self.tx_sort_btn_var.set(
                f"Sort Unrecognised ({needs_review})" if needs_review else "Sort Unrecognised")
        summary = [
            f"Preview transactions: {len(self.latest_import)}",
            f"Verified in preview: {verified}",
            f"Outgoing still needing review: {needs_review}",
            f"Committed transactions: {len(self.state.transactions)}",
        ]
        log_lines = self.latest_import_qa if self.latest_import_qa else ["No active import. Import a bank PDF to preview transactions here."]
        self.transaction_log_text.insert(tk.END, "\n".join(summary + [""] + log_lines + ["", "Note: Suggested matches are not trusted until user-verified."]))
        recurring = self.transaction_insights.get("recurring", [])
        unusual = self.transaction_insights.get("unusual", [])
        new_merchants = self.transaction_insights.get("new_merchants", [])
        insight_lines = []
        if recurring:
            insight_lines.append("Likely recurring: " + " • ".join(recurring[:3]))
        if unusual:
            insight_lines.append("Unusual spend: " + " • ".join(unusual[:3]))
        if new_merchants:
            insight_lines.append("New merchants needing review: " + ", ".join(new_merchants[:5]))
        if not insight_lines:
            insight_lines.append("No notable insights yet. Import a statement to see recurring and unusual spend.")
        if not self.latest_import:
            self.transaction_workflow_state_var.set("Step 1: import a bank statement PDF to start a review batch.")
        elif needs_review > 0:
            self.transaction_workflow_state_var.set(f"Step 2: {needs_review} outgoing transaction(s) still unsorted — click Sort Unrecognised.")
        else:
            self.transaction_workflow_state_var.set("Step 3: every outgoing row is sorted — commit this batch when ready.")
        self.transaction_insights_var.set("\n".join(insight_lines))
        # Collapsed-header summaries
        self.tx_log_summary_var.set(
            f"Preview {len(self.latest_import)} · verified {verified} · review {needs_review}")
        cat_totals = {}
        for t in self.state.transactions:
            if t.direction() == "out":
                cat = t.category or "Uncategorized"
                cat_totals[cat] = cat_totals.get(cat, 0.0) + t.amount()
        if cat_totals:
            top_cat, top_amt = max(cat_totals.items(), key=lambda kv: kv[1])
            self.tx_insights_summary_var.set(f"Top category: {top_cat} ${top_amt:,.0f}")
        else:
            self.tx_insights_summary_var.set("No committed outgoing yet")
        self.refresh_expense_pie_chart()

    def refresh_rules_tab(self):
        for row in self.rules_tree.get_children(): self.rules_tree.delete(row)
        for idx, rule in enumerate(self.state.advanced_match_rules):
            self.rules_tree.insert("", tk.END, iid=str(idx), values=(rule.rule_type, rule.keyword, f"${rule.amount:,.2f}" if rule.amount else "", rule.matched_type, rule.matched_target, rule.category, "Yes" if rule.is_active else "No"))
        self._restripe_tree(self.rules_tree)

    def _priority_pill(self, priority: str) -> str:
        key = (priority or "").strip().lower()
        icon = {"essential": "\U0001f534", "important": "\U0001f7e0",
                "optional": "\u26aa"}.get(key, "\u26aa")
        return f"{icon} {priority}" if priority else icon

    def _frequency_pill(self, freq: str) -> str:
        key = (freq or "").strip().lower()
        icon = {"weekly": "\U0001f535", "fortnightly": "\U0001f7e3",
                "monthly": "\U0001f7e2", "quarterly": "\U0001f7e0", "yearly": "\U0001f7e1",
                "one-off": "\u26aa", "one_off": "\u26aa"}.get(key, "\u26aa")
        return f"{icon} {freq}" if freq else icon

