            for line in self.last_game_result["breakdown"]:
                tk.Label(lp, text=f"• {line}", bg=UI_SURFACE, fg=UI_TEXT,
                         font=FONT_SMALL, anchor="w", justify="left",
                         wraplength=420).pack(anchor="w")
